INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('978213c1-b154-4786-abf4-87068bbf7284', '三月三日宴王明府山亭', '三月三日宴王明府山亭', 'fec69cd5-862d-4163-b68b-8ecfa48dac37', '唐', '["暮春元巳，春服初裁。","童冠八九，于洛之隈。","河堤草變，鞏樹花開。","逸人談發，仙御舟來。","間關黃鳥，瀺灂丹腮。","樂飲命席，優哉悠哉。"]', '["暮春元巳，春服初裁。","童冠八九，于洛之隈。","河堤草变，鞏樹花开。","逸人談發，仙御舟来。","间关黄鸟，瀺灂丹腮。","乐饮命席，優哉悠哉。"]', '诗', 'shi', '', NULL, '三月三日宴王明府山亭 高瑾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3fd3c655-b0a9-4b60-86af-8b6dd41df9a2', '晦日宴高氏林亭', '晦日宴高氏林亭', 'fec69cd5-862d-4163-b68b-8ecfa48dac37', '唐', '["試入山亭望，言是石崇家。","二月風光起，三春桃李華。","鶯吟上喬木，雁往息平沙。","相看會取醉，寧知還路賒。"]', '["試入山亭望，言是石崇家。","二月风光起，三春桃李华。","鶯吟上喬木，雁往息平沙。","相看會取醉，寧知還路賒。"]', '诗', 'shi', '', NULL, '晦日宴高氏林亭 高瑾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9e98389-3c67-44ab-8a62-c88c5be0fa00', '晦日重宴', '晦日重宴', 'fec69cd5-862d-4163-b68b-8ecfa48dac37', '唐', '["忽聞鶯響谷，於此命相知。","正開彭澤酒，來向高陽池。","柳葉風前弱，梅花影處危。","賞洽林亭晚，落照下參差。"]', '["忽闻鶯响谷，於此命相知。","正开彭澤酒，来向高陽池。","柳葉风前弱，梅花影处危。","賞洽林亭晚，落照下參差。"]', '诗', 'shi', '', NULL, '晦日重宴 高瑾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34b69c2d-d8c1-4bff-9e3d-2508a1e83716', '上元夜效小庾體', '上元夜效小庾體', 'fec69cd5-862d-4163-b68b-8ecfa48dac37', '唐', '["初年三五夜，相知一兩人。","連鑣出巷口，飛轂下池漘。","燈光恰似月，人面倂如春。","遨遊終未已，相歡待日輪。"]', '["初年三五夜，相知一兩人。","連鑣出巷口，飞轂下池漘。","灯光恰似月，人面倂如春。","遨游終未已，相歡待日輪。"]', '诗', 'shi', '', NULL, '上元夜效小庾體 高瑾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66e9672b-8a2a-4876-819d-bd4aeb091640', '晦日宴高氏林亭', '晦日宴高氏林亭', '9df666d7-0a58-44d2-980b-9974727e4af5', '唐', '["踐勝尋良會，乘春翫物華。","還隨張放友，來向石崇家。","止水分巖鏡，閑庭枕浦沙。","未極林泉賞，參差落照斜。"]', '["踐勝尋良會，乘春翫物华。","還隨張放友，来向石崇家。","止水分巖镜，闲庭枕浦沙。","未極林泉賞，參差落照斜。"]', '诗', 'shi', '', NULL, '晦日宴高氏林亭 王茂時 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cfccbfd5-e1a9-4b6a-a3fd-9bd0918b7361', '晦日宴高氏林亭', '晦日宴高氏林亭', '5fbb0c34-a923-47d0-a87e-b4be036ce453', '唐', '["綺筵乘暇景，瓊醑對年華。","門多金埒騎，路引璧人車。","蘋早猶藏葉，梅殘正落花。","藹藹林亭晚，餘興促流霞。"]', '["綺筵乘暇景，瓊醑对年华。","门多金埒騎，路引璧人车。","蘋早猶藏葉，梅殘正落花。","藹藹林亭晚，餘兴促流霞。"]', '诗', 'shi', '', NULL, '晦日宴高氏林亭 徐皓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9113e0d7-e9c4-4353-9aca-8021d40eb19d', '晦日宴高氏林亭', '晦日宴高氏林亭', 'ee94fca9-5965-4793-aad6-8e520a384022', '唐', '["晦晚屬煙霞，遨遊重歲華。","歌鐘雖戚里，林藪是山家。","細雨猶開日，深池不漲沙。","淹留迷處所，巖岫幾重花。"]', '["晦晚屬煙霞，遨游重歲华。","歌鐘雖戚里，林藪是山家。","細雨猶开日，深池不漲沙。","淹留迷处所，巖岫幾重花。"]', '诗', 'shi', '', NULL, '晦日宴高氏林亭 長孫正隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6224c81-e134-4905-ab41-b0c639eef760', '上元夜效小庾體同用春字', '上元夜效小庾體同用春字', 'ee94fca9-5965-4793-aad6-8e520a384022', '唐', '["薄晚嘯遊人，車馬亂驅塵。","月光三五夜，燈燄一重春。","煙雲迷北闕，簫管識南鄰。","洛城終不閉，更出小平津。"]', '["薄晚嘯游人，车马亂驱塵。","月光三五夜，灯燄一重春。","煙云迷北闕，簫管識南鄰。","洛城終不閉，更出小平津。"]', '诗', 'shi', '', NULL, '上元夜效小庾體同用春字 長孫正隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eab43c99-79c0-4b79-89f5-a7408f8e547e', '晦日宴高氏林亭', '晦日宴高氏林亭', 'bad71495-3832-4267-b2df-6cf89fab77d7', '唐', '["嘯侶入山家，臨春翫物華。","葛弦調綠水，桂醑酌丹霞。","岸柳開新葉，庭梅落早花。","興洽林亭晚，方還倒載車。"]', '["嘯侶入山家，臨春翫物华。","葛弦調綠水，桂醑酌丹霞。","岸柳开新葉，庭梅落早花。","兴洽林亭晚，方還倒載车。"]', '诗', 'shi', '', NULL, '晦日宴高氏林亭 高紹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0464ebb-ba52-474f-ac7b-6b3a13cec685', '晦日宴高氏林亭', '晦日宴高氏林亭', '0bb81ade-17f9-4c15-909e-c7ef3b2914dc', '唐', '["三春休晦節，九谷泛年華。","半晴餘細雨，全晚澹殘霞。","尊開疎竹葉，管應落梅花。","興闌相顧起，流水送香車。"]', '["三春休晦節，九谷泛年华。","半晴餘細雨，全晚澹殘霞。","尊开疎竹葉，管應落梅花。","兴闌相顧起，流水送香车。"]', '诗', 'shi', '', NULL, '晦日宴高氏林亭 郎餘令 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a280978-cd68-4d49-bf3a-d197d5b0bd63', '聽歌', '听歌', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["朱檻滿明月，美人歌落梅。","忽驚塵起處，疑是有風來。","一曲聽初徹，幾年愁暫開。","東南正雲雨，不得見陽臺。"]', '["朱檻满明月，美人歌落梅。","忽驚塵起处，疑是有风来。","一曲听初徹，幾年愁暫开。","东南正云雨，不得见陽台。"]', '诗', 'shi', '', NULL, '聽歌 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9eea7ec-888e-44f0-8a5a-e92b9d7554bf', '青龍寺僧院', '青龙寺僧院', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["常多簪組客，非獨看高松。","此地堪終日，開門見數峰。","苔新禽跡少，泉冷樹陰重。","師意如山裏，空房曉暮鐘。"]', '["常多簪組客，非独看高松。","此地堪終日，开门见數峰。","苔新禽跡少，泉冷樹陰重。","師意如山裏，空房晓暮鐘。"]', '诗', 'shi', '', NULL, '青龍寺僧院 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46dd7555-5804-4a56-b362-26df4dcf816e', '夏夜會同人', '夏夜會同人', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["沈沈清暑夕，星斗儼虛空。","岸幘栖禽下，烹茶玉漏中。","形骸忘已久，偃仰趣無窮。","日汲泉來漱，微開密篠風。"]', '["沈沈清暑夕，星斗儼虛空。","岸幘栖禽下，烹茶玉漏中。","形骸忘已久，偃仰趣無窮。","日汲泉来漱，微开密篠风。"]', '诗', 'shi', '', NULL, '夏夜會同人 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e7e64ea-aa87-456e-b4aa-942822271e15', '遊崔監丞城南別業', '游崔監丞城南別業', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["門與青山近，青山復幾重。","雪融皇子岸，春浥翠微峰。","地有經冬草，林無未老松。","竹寒溪隔寺，晴日直聞鐘。"]', '["门與青山近，青山复幾重。","雪融皇子岸，春浥翠微峰。","地有經冬草，林無未老松。","竹寒溪隔寺，晴日直闻鐘。"]', '诗', 'shi', '', NULL, '遊崔監丞城南別業 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02de7d48-2092-43ac-9f42-b34c0f529353', '荅韋先輩春雨後見寄', '荅韋先輩春雨後见寄', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["風散五更雨，鳥啼三月春。","軒窗透初日，硯席絕纖塵。","帝里峰頭出，鄰家樹色新。","憐君高且靜，有句寄閑人。"]', '["风散五更雨，鸟啼三月春。","軒窗透初日，硯席絕纖塵。","帝里峰头出，鄰家樹色新。","怜君高且静，有句寄闲人。"]', '诗', 'shi', '', NULL, '荅韋先輩春雨後見寄 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab5c8c16-35c2-42f5-8726-764b7ddac590', '題吳先生山居', '題吳先生山居', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["先生此幽隱，便可謝人羣。","潭底見秋石，樹間飛霽雲。","山居心已慣，俗事耳憎聞。","念我要多疾，開爐藥許分。"]', '["先生此幽隐，便可謝人羣。","潭底见秋石，樹间飞霽云。","山居心已慣，俗事耳憎闻。","念我要多疾，开爐藥許分。"]', '诗', 'shi', '', NULL, '題吳先生山居 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21ae5fa9-4166-4a87-8fa2-9cde7be03edf', '晚遊慈恩寺', '晚游慈恩寺', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["寺去幽居近，每來因採薇。","伴僧行不困，臨水語忘歸。","磬動青林晚，人驚白鷺飛。","堪嗟浮俗事，皆與道相違。"]', '["寺去幽居近，每来因採薇。","伴僧行不困，臨水語忘归。","磬动青林晚，人驚白鷺飞。","堪嗟浮俗事，皆與道相違。"]', '诗', 'shi', '', NULL, '晚遊慈恩寺 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ec90e57-dc10-4b78-a5ee-522f9b0c781b', '題王處士山居', '題王处士山居', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["茅堂入谷遠，林暗絕其鄰。","終日有流水，經年無到人。","溪雲常欲雨，山洞別開春。","自得仙家術，栽松獨養真。"]', '["茅堂入谷远，林暗絕其鄰。","終日有流水，經年無到人。","溪云常欲雨，山洞別开春。","自得仙家術，栽松独養真。"]', '诗', 'shi', '', NULL, '題王處士山居 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7622a4bf-6053-4613-8a94-b1a60a7b163f', '宿僧院', '宿僧院', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["禪地無塵夜，焚香話所歸。","樹搖幽鳥夢，螢入定僧衣。","破月斜天半，高河下露微。","翻令嫌白日，動即與心違。"]', '["禪地無塵夜，焚香話所归。","樹搖幽鸟梦，螢入定僧衣。","破月斜天半，高河下露微。","翻令嫌白日，动即與心違。"]', '诗', 'shi', '', NULL, '宿僧院 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6552a1cc-269d-414b-9e6b-1ec167fd77a8', '曉別呂山人', '晓別呂山人', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["疎鐘兼漏盡，曙色照青氛。","栖鶴出高樹，山人歸白雲。","月盈期重宿，丹熟約相分。","羨入秋風洞，幽泉仔細聞。"]', '["疎鐘兼漏尽，曙色照青氛。","栖鹤出高樹，山人归白云。","月盈期重宿，丹熟約相分。","羨入秋风洞，幽泉仔細闻。"]', '诗', 'shi', '', NULL, '曉別呂山人 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f3306e9-a602-49b5-8183-c04e89396d3d', '送知全禪師南遊', '送知全禪師南游', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["師譽振京城，談空萬乘聽。","北行山已雪，南去木猶青。","夜嶽禪銷月，秋潭汲動星。","迴期不可定，孤鶴在高冥。"]', '["師譽振京城，談空万乘听。","北行山已雪，南去木猶青。","夜嶽禪銷月，秋潭汲动星。","迴期不可定，孤鹤在高冥。"]', '诗', 'shi', '', NULL, '送知全禪師南遊 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d752d820-ad9b-4c1d-afe6-869523196ef8', '上張水部', '上張水部', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["出入門闌久，兒童亦有情。","不須將姓字，長說向公卿。","每許連牀坐，時容並馬行。","恩深轉無語，懷抱自分明。"]', '["出入门闌久，兒童亦有情。","不須將姓字，长说向公卿。","每許連牀坐，时容並马行。","恩深轉無語，懷抱自分明。"]', '诗', 'shi', '', NULL, '上張水部 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a695501a-4c10-4201-9f0d-c1b714a703d1', '塞上行作', '塞上行作', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["鄉井從離別，窮邊觸目愁。","生人居外地，塞雪下中秋。","鴈舉之衡翅，河穿入虜流。","將軍心莫苦，向此取封侯。"]', '["乡井從離別，窮邊觸目愁。","生人居外地，塞雪下中秋。","鴈舉之衡翅，河穿入虜流。","將軍心莫苦，向此取封侯。"]', '诗', 'shi', '', NULL, '塞上行作 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e9a141b-c628-4caf-8644-3b81fd30c436', '贈江夏盧使君', '贈江夏盧使君', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["詩人中最屈，無與使君儔。","白髮雖求退，明時合見收。","登山猶自健，縱酒可多愁。","好是能騎馬，相逢見鄂州。"]', '["诗人中最屈，無與使君儔。","白髮雖求退，明时合见收。","登山猶自健，縱酒可多愁。","好是能騎马，相逢见鄂州。"]', '诗', 'shi', '', NULL, '贈江夏盧使君 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8350a26b-4f98-47f8-81a1-dc51ee8f3495', '冬夜寄白閣僧', '冬夜寄白閣僧', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["營營不自息，暌闊數年情。","林下期難逐，人間事旋生。","鳥棲寒水迥，月映積冰清。","石室焚香坐，懸知不爲名。"]', '["營營不自息，暌闊數年情。","林下期难逐，人间事旋生。","鸟棲寒水迥，月映積冰清。","石室焚香坐，懸知不爲名。"]', '诗', 'shi', '', NULL, '冬夜寄白閣僧 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('303ad4fe-b67f-476e-aa48-0de91ba3e9f4', '送姚合郎中任杭州', '送姚合郎中任杭州', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["水陸中分程，看花一月行。","會稽山隔浪，天竺樹連城。","候吏齎魚印，迎船載斾旌。","渡江春始半，列嶼草初生。"]', '["水陸中分程，看花一月行。","會稽山隔浪，天竺樹連城。","候吏齎鱼印，迎船載斾旌。","渡江春始半，列嶼草初生。"]', '诗', 'shi', '', NULL, '送姚合郎中任杭州 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b23b1ca-c2b6-4e37-8988-8a50b9ca0c3c', '西園', '西园', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["夏圃秋涼入，樹低逢幘欹。","水聲翻敗堰，山翠濕疎籬。","綠滑莎藏徑，紅連果壓枝。","幽人更何事，旦夕與僧期。"]', '["夏圃秋涼入，樹低逢幘欹。","水声翻敗堰，山翠濕疎籬。","綠滑莎藏徑，紅連果壓枝。","幽人更何事，旦夕與僧期。"]', '诗', 'shi', '', NULL, '西園 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2824170-01ff-4e81-8ad8-68a0d03a402f', '昊天觀新栽竹', '昊天观新栽竹', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["清風枝葉上，山鳥已栖來。","根別古溝岸，影生秋觀苔。","徧思諸草木，惟此出塵埃。","恨爲移君晚，空庭更擬栽。"]', '["清风枝葉上，山鸟已栖来。","根別古溝岸，影生秋观苔。","徧思諸草木，惟此出塵埃。","恨爲移君晚，空庭更擬栽。"]', '诗', 'shi', '', NULL, '昊天觀新栽竹 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce87d6be-f182-452d-9bcf-8c92c74dd567', '晚步曲江因謁慈恩寺恭上人', '晚步曲江因謁慈恩寺恭上人', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["豈曰趣名者，年年待命通。","坐令青嶂上，興起白雲中。","岸浸如天水，林含似雨風。","南宗猶有碍，西寺問恭公。"]', '["豈曰趣名者，年年待命通。","坐令青嶂上，兴起白云中。","岸浸如天水，林含似雨风。","南宗猶有碍，西寺问恭公。"]', '诗', 'shi', '', NULL, '晚步曲江因謁慈恩寺恭上人 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b53de07-354c-417a-bc20-46b39309233c', '送姚處士歸亳州', '送姚处士归亳州', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["白髮麻衣破，還譙別弟迴。","首垂聽樂淚，花落待歌杯。","石路尋芝熟，柴門有鹿來。","明王下徵詔，應就碧峰開。"]', '["白髮麻衣破，還譙別弟迴。","首垂听乐泪，花落待歌杯。","石路尋芝熟，柴门有鹿来。","明王下徵詔，應就碧峰开。"]', '诗', 'shi', '', NULL, '送姚處士歸亳州 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1dd6b649-cea8-4b5d-906f-880bf0d94a43', '寄樓子山雲棲上人', '寄楼子山云棲上人', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["一室鑿崔嵬，危梯疊蘚苔。","永無塵事到，時有至人來。","澗谷冬深靜，煙嵐日午開。","修身知得地，京寺未言迴。"]', '["一室鑿崔嵬，危梯叠蘚苔。","永無塵事到，时有至人来。","澗谷冬深静，煙嵐日午开。","修身知得地，京寺未言迴。"]', '诗', 'shi', '', NULL, '寄樓子山雲棲上人 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1bdbd392-323e-42fd-86e6-1e577ed63975', '秋夜喜友人宿', '秋夜喜友人宿', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["莫說春闈事，清宵且共吟。","頻年遺我輩，何日遇知音。","逼曙天傾斗，將寒葉墜林。","無將簪紱意，只損壯夫心。"]', '["莫说春闈事，清宵且共吟。","頻年遺我輩，何日遇知音。","逼曙天傾斗，將寒葉墜林。","無將簪紱意，只損壯夫心。"]', '诗', 'shi', '', NULL, '秋夜喜友人宿 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b52ca1a-7472-4e9c-a758-8a1a2bd17b18', '秋日同僧宿西池', '秋日同僧宿西池', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["菡萏遍秋水，隔林香似焚。","僧同池上宿，霞向月邊分。","渚鳥栖蒲立，城砧接曙聞。","來宵莫他約，重此話孤雲。"]', '["菡萏遍秋水，隔林香似焚。","僧同池上宿，霞向月邊分。","渚鸟栖蒲立，城砧接曙闻。","来宵莫他約，重此話孤云。"]', '诗', 'shi', '', NULL, '秋日同僧宿西池 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8d996b4-2eb5-4fdf-9572-6af8ecdc4a85', '宿韋津山居', '宿韋津山居', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["永夕見招宿，詩書盈草堂。","靜吟傾美酒，高論出名場。","窗颯松篁韻，庭兼雪月光。","心期身未老，一去泛瀟湘。"]', '["永夕见招宿，诗书盈草堂。","静吟傾美酒，高論出名場。","窗颯松篁韻，庭兼雪月光。","心期身未老，一去泛瀟湘。"]', '诗', 'shi', '', NULL, '宿韋津山居 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('136bbd8c-eb1c-43c1-8b24-782ca328e0c4', '夜攜酒訪崔正字', '夜携酒訪崔正字', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["只應芸閣吏，知我僻兼愚。","吟興忘飢凍，生涯任有無。","慘雲埋遠岫，陰吹吼寒株。","忽起圍爐思，招攜酒滿壺。"]', '["只應芸閣吏，知我僻兼愚。","吟兴忘飢凍，生涯任有無。","慘云埋远岫，陰吹吼寒株。","忽起圍爐思，招携酒满壺。"]', '诗', 'shi', '', NULL, '夜攜酒訪崔正字 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76688ee0-108b-4fb1-8369-5b643832349d', '送蔡京東歸迎侍', '送蔡京东归迎侍', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["高堂惟兩別，此別是榮歸。","薄俸迎親遠，平時知己稀。","鄆郊秋木見，魯寺夜鐘微。","近臘西來日，多逢霰雪飛。"]', '["高堂惟兩別，此別是榮归。","薄俸迎親远，平时知己稀。","鄆郊秋木见，魯寺夜鐘微。","近臘西来日，多逢霰雪飞。"]', '诗', 'shi', '', NULL, '送蔡京東歸迎侍 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64f7ffee-d8d2-40c2-96b1-f65bb510bf2b', '中秋', '中秋', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["塵裏兼塵外，咸期此夕明。","一年惟一度，長恐有雲生。","露洗微埃盡，光濡是物清。","朗吟看正好，惆悵又西傾。"]', '["塵裏兼塵外，咸期此夕明。","一年惟一度，长恐有云生。","露洗微埃尽，光濡是物清。","朗吟看正好，惆悵又西傾。"]', '诗', 'shi', '', NULL, '中秋 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b0aeb3c-26cd-40cf-98ec-6d898b7d2bf4', '池上宿', '池上宿', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["事事不求奢，長吟省嘆嗟。","無才堪世棄，有句向誰誇。","老樹呈秋色，空池浸月華。","涼風白露夕，此境屬詩家。"]', '["事事不求奢，长吟省嘆嗟。","無才堪世棄，有句向誰誇。","老樹呈秋色，空池浸月华。","涼风白露夕，此境屬诗家。"]', '诗', 'shi', '', NULL, '池上宿 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed167333-59af-4452-be9b-5b14631730fd', '秋夕即事', '秋夕即事', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["永夕坐暝久，蕭蕭猨狖啼。","漏微砧韻隔，月落斗杓低。","危葉無風墜，幽禽並樹栖。","自憐在岐路，不醉亦沈迷。"]', '["永夕坐暝久，蕭蕭猨狖啼。","漏微砧韻隔，月落斗杓低。","危葉無风墜，幽禽並樹栖。","自怜在岐路，不醉亦沈迷。"]', '诗', 'shi', '', NULL, '秋夕即事 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c009334b-4ddb-4e1b-b0da-1fe220b533c9', '晚夏', '晚夏', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["日夕是西風，流光半已空。","山光漸凝碧，樹葉即翻紅。","學淺慙多士，秋成羨老農。","誰憐信公道，不泣路岐中。"]', '["日夕是西风，流光半已空。","山光漸凝碧，樹葉即翻紅。","学淺慙多士，秋成羨老農。","誰怜信公道，不泣路岐中。"]', '诗', 'shi', '', NULL, '晚夏 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b2086b5-58ca-46c2-a2a6-7b6fe5e63cb6', '夏日即事', '夏日即事', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["到曉改詩句，四鄰嫌苦吟。","中宵橫北斗，夏木隱栖禽。","天地先秋肅，軒窗映月深。","幽庭多此景，惟恐曙光侵。"]', '["到晓改诗句，四鄰嫌苦吟。","中宵橫北斗，夏木隐栖禽。","天地先秋肅，軒窗映月深。","幽庭多此景，惟恐曙光侵。"]', '诗', 'shi', '', NULL, '夏日即事 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5945cb07-2e68-4f90-9e85-100588998082', '夏日通濟里居酬諸先輩見訪', '夏日通濟里居酬諸先輩见訪', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["君子遠相尋，聯鑣到敝林。","有詩誰索和，無酒可賒斟。","門列晴峰色，堂開古木陰。","何因駐清聽，惟恐日西沈。"]', '["君子远相尋，聯鑣到敝林。","有诗誰索和，無酒可賒斟。","门列晴峰色，堂开古木陰。","何因駐清听，惟恐日西沈。"]', '诗', 'shi', '', NULL, '夏日通濟里居酬諸先輩見訪 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('898f5b76-d67e-415b-aa29-0dac947fce03', '寄姚諫議', '寄姚諫議', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["鳴鞭靜路塵，籍籍諫垣臣。","函疏封還密，爐香侍立親。","篋多臨水作，窗宿臥雲人。","危坐開寒紙，燈前起草頻。"]', '["鳴鞭静路塵，籍籍諫垣臣。","函疏封還密，爐香侍立親。","篋多臨水作，窗宿臥云人。","危坐开寒紙，灯前起草頻。"]', '诗', 'shi', '', NULL, '寄姚諫議 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c71caa8-2dec-4fc9-abdb-1adcf745f1f4', '和厲玄侍御題戶部相公廬山草堂', '和厲玄侍御題戶部相公廬山草堂', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["白雲居創畢，詔入鳳池年。","林長雙峰樹，潭分並寺泉。","石溪盤鶴外，岳室閉猨前。","柱史題詩後，松前更肅然。"]', '["白云居創畢，詔入鳳池年。","林长雙峰樹，潭分並寺泉。","石溪盤鹤外，岳室閉猨前。","柱史題诗後，松前更肅然。"]', '诗', 'shi', '', NULL, '和厲玄侍御題戶部相公廬山草堂 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e90dab5d-7bd8-4253-97ae-c324cc38a5a1', '題山中故靜禪師', '題山中故静禪師', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["寂滅身何在，門人隔此生。","影懸塵已厚，塔種柏初成。","溪院秋先雪，山堂古有精。","當時挂錫處，樹老幾枝傾。"]', '["寂滅身何在，门人隔此生。","影懸塵已厚，塔種柏初成。","溪院秋先雪，山堂古有精。","當时挂錫处，樹老幾枝傾。"]', '诗', 'shi', '', NULL, '題山中故靜禪師 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3569c89a-b3e9-485f-9d5a-b1797112654d', '夏日遊慈恩寺', '夏日游慈恩寺', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["何處消長日，慈恩精舍頻。","僧高容野客，樹密絕囂塵。","閑上凌虛塔，相逢避暑人。","却愁歸去路，馬迹竝車輪。"]', '["何处消长日，慈恩精舍頻。","僧高容野客，樹密絕囂塵。","闲上凌虛塔，相逢避暑人。","却愁归去路，马迹竝车輪。"]', '诗', 'shi', '', NULL, '夏日遊慈恩寺 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69e6771a-9618-4817-a98b-63bae08e606d', '題終南麻先生寂禪師石室', '題終南麻先生寂禪師石室', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["因居石室貧，五十二迴春。","擁褐冥心客，窮經暮齒人。","翠沈空水定，雨絕片雲新。","危細秋峰徑，相隨到頂頻。"]', '["因居石室貧，五十二迴春。","擁褐冥心客，窮經暮齒人。","翠沈空水定，雨絕片云新。","危細秋峰徑，相隨到頂頻。"]', '诗', 'shi', '', NULL, '題終南麻先生寂禪師石室 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6384393b-fbb2-409d-bcc9-984bde31dcf5', '送靈武朱書記', '送靈武朱书記', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["靈帥與誰善，得君賓幕中。","從容應盡禮，贊畫致元功。","連塞雲長慘，纔秋樹半空。","相如偏自愜，掌記復乘驄。"]', '["靈帥與誰善，得君賓幕中。","從容應尽禮，贊畫致元功。","連塞云长慘，纔秋樹半空。","相如偏自愜，掌記复乘驄。"]', '诗', 'shi', '', NULL, '送靈武朱書記 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ca268d2-c4aa-47b4-ba0c-5ccea08dd431', '弔草堂禪師', '弔草堂禪師', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["杖履疑師在，房關四壁蛩。","貯瓶經臘水，響塔隔山鐘。","乳鴿沿苔井，齋猨散雪峰。","如何不相見，倚徧寺前松。"]', '["杖履疑師在，房关四壁蛩。","貯瓶經臘水，响塔隔山鐘。","乳鴿沿苔井，斋猨散雪峰。","如何不相见，倚徧寺前松。"]', '诗', 'shi', '', NULL, '弔草堂禪師 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ddcfa724-864f-4ae0-ad50-9ae5fbc3b0f1', '早春送湘潭李少府之任', '早春送湘潭李少府之任', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["柳新春水湄，春岸草離離。","祖席觴云盡，離人淚各垂。","業文傳不朽，作尉豈多時。","公退琴堂上，風吹斑竹枝。"]', '["柳新春水湄，春岸草離離。","祖席觴云尽，離人泪各垂。","業文傳不朽，作尉豈多时。","公退琴堂上，风吹斑竹枝。"]', '诗', 'shi', '', NULL, '早春送湘潭李少府之任 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('def9ba93-b443-4807-8332-97c615a371c2', '送越客歸', '送越客归', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["霜薄東南地，江楓落未齊。","衆山離楚上，孤棹宿吳西。","渚客留僧語，籠猨失子啼。","到家冬即是，荷盡若耶溪。"]', '["霜薄东南地，江楓落未齊。","衆山離楚上，孤棹宿吳西。","渚客留僧語，籠猨失子啼。","到家冬即是，荷尽若耶溪。"]', '诗', 'shi', '', NULL, '送越客歸 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b510f3a7-a145-44e6-816f-7a74d676707f', '送周鉞往江夏', '送周鉞往江夏', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["東西南北郡，自說徧曾遊。","人世終多故，皇都不少留。","郢城帆過夜，漢水月方秋。","此謁親知去，聞猨豈解愁。"]', '["东西南北郡，自说徧曾游。","人世終多故，皇都不少留。","郢城帆過夜，漢水月方秋。","此謁親知去，闻猨豈解愁。"]', '诗', 'shi', '', NULL, '送周鉞往江夏 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9624fa0-5afd-4041-8f5b-5811a4af2901', '送河池李明府之任', '送河池李明府之任', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["河池安所理，種柳與彈琴。","自合清時化，仍資白首吟。","程餘行片月，公退入遙林。","想得詢民瘼，方稱單父心。"]', '["河池安所理，種柳與彈琴。","自合清时化，仍資白首吟。","程餘行片月，公退入遙林。","想得詢民瘼，方稱單父心。"]', '诗', 'shi', '', NULL, '送河池李明府之任 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e852287-bccd-4698-9053-d0df2ac6c509', '送蔡京侍御赴大梁幕', '送蔡京侍御赴大梁幕', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["同城各多故，會面亦稀疎。","及道須相別，臨岐恨有餘。","梁園飛楚鳥，汴水走淮魚。","衆說裁軍檄，陳琳遠不如。"]', '["同城各多故，會面亦稀疎。","及道須相別，臨岐恨有餘。","梁园飞楚鸟，汴水走淮鱼。","衆说裁軍檄，陳琳远不如。"]', '诗', 'shi', '', NULL, '送蔡京侍御赴大梁幕 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('109ad1d2-3731-443a-b90d-aa4365c7d15e', '哭鮑溶有感', '哭鲍溶有感', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["寥落故人宅，今來身已亡。","古苔封墨沼，深竹映書堂。","秋色池館靜，雨聲雲水涼。","無因展交道，日暮剖心腸。"]', '["寥落故人宅，今来身已亡。","古苔封墨沼，深竹映书堂。","秋色池館静，雨声云水涼。","無因展交道，日暮剖心腸。"]', '诗', 'shi', '', NULL, '哭鮑溶有感 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('135b439d-b60c-4a42-8d0c-22cc25e42426', '送僧歸玉泉寺', '送僧归玉泉寺', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["玉泉歸故剎，便老是僧期。","亂木孤蟬後，寒山絕鳥時。","若尋流水去，轉出白雲遲。","見說千峰路，溪深復頂危。"]', '["玉泉归故剎，便老是僧期。","亂木孤蟬後，寒山絕鸟时。","若尋流水去，轉出白云遲。","见说千峰路，溪深复頂危。"]', '诗', 'shi', '', NULL, '送僧歸玉泉寺 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78ada3c5-92a7-4de7-ae14-836488679e66', '宣義池上', '宣義池上', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["修篁夾綠池，幽絮此中飛。","何必青山遠，仍將白髮歸。","鳥啼亦有恨，鷗習總無機。","樹起秋風細，西林磬入微。"]', '["修篁夾綠池，幽絮此中飞。","何必青山远，仍將白髮归。","鸟啼亦有恨，鷗習總無機。","樹起秋风細，西林磬入微。"]', '诗', 'shi', '', NULL, '宣義池上 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d828921-91fb-4ada-8631-dfae14941a9b', '回中夜訪獨孤從事', '回中夜訪独孤從事', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["滿庭霜月魄，風靜絕纖聞。","邊境時無事，州城夜訪君。","擁裘聽塞角，酌醴話湘雲。","贊佐元戎美，恩齊十萬軍。"]', '["满庭霜月魄，风静絕纖闻。","邊境时無事，州城夜訪君。","擁裘听塞角，酌醴話湘云。","贊佐元戎美，恩齊十万軍。"]', '诗', 'shi', '', NULL, '回中夜訪獨孤從事 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7cc5d03-dbca-4ec7-9fc3-5c31a33d9bac', '宿宣義池亭', '宿宣義池亭', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["暮色遶柯亭，南山幽竹青。","夜深斜舫月，風定一池星。","島嶼無人跡，菰蒲有鶴翎。","此中足吟眺，何用泛滄溟。"]', '["暮色遶柯亭，南山幽竹青。","夜深斜舫月，风定一池星。","島嶼無人跡，菰蒲有鹤翎。","此中足吟眺，何用泛滄溟。"]', '诗', 'shi', '', NULL, '宿宣義池亭 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa4780fe-f910-470e-bdad-95daf6277090', '送智玄首座歸蜀中舊山', '送智玄首座归蜀中旧山', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["像教得重興，因師說大乘。","從來悟明主，今去證高僧。","蜀國煙霞異，靈山水月澄。","鄉閭諸善友，喜似見南能。"]', '["像教得重兴，因師说大乘。","從来悟明主，今去證高僧。","蜀国煙霞異，靈山水月澄。","乡閭諸善友，喜似见南能。"]', '诗', 'shi', '', NULL, '送智玄首座歸蜀中舊山 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('935bcd90-e68c-48a4-88d6-124bd8c50b8b', '賀顧非熊及第其年內索文章', '賀顧非熊及第其年內索文章', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["愚爲童稚時，已解念君詩。","及得高科晚，須逢聖主知。","花前飜有淚，鬢上却無絲。","從此東歸去，休爲墜葉期。"]', '["愚爲童稚时，已解念君诗。","及得高科晚，須逢聖主知。","花前飜有泪，鬢上却無絲。","從此东归去，休爲墜葉期。"]', '诗', 'shi', '', NULL, '賀顧非熊及第其年內索文章 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('701ddaac-fd35-42ee-88e2-1da8d56e9a62', '冬日駱家亭子', '冬日駱家亭子', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["亭臺臘月時，松竹見貞姿。","林積煙藏日，風吹水合池。","恨無人此住，靜有鶴相窺。","是景吟詩徧，真於野客宜。"]', '["亭台臘月时，松竹见貞姿。","林積煙藏日，风吹水合池。","恨無人此住，静有鹤相窺。","是景吟诗徧，真於野客宜。"]', '诗', 'shi', '', NULL, '冬日駱家亭子 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17cc0659-dfef-47e7-a538-bd689b2b8c2b', '題邵公禪院', '題邵公禪院', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["無事門多掩，陰階竹掃苔。","勁風吹雪聚，渴鳥啄冰開。","樹向寒山得，人從瀑布來。","終期天目老，擎錫逐雲回。"]', '["無事门多掩，陰階竹掃苔。","勁风吹雪聚，渴鸟啄冰开。","樹向寒山得，人從瀑布来。","終期天目老，擎錫逐云回。"]', '诗', 'shi', '', NULL, '題邵公禪院 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a239c65c-e5e0-4463-b314-ce56f0a3fac4', '憶鶴', '憶鹤', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["自爾歸仙後，經秋又過春。","白雲尋不得，紫府去無因。","此地空明月，何山伴羽人。","終期華表上，重見令威身。"]', '["自爾归仙後，經秋又過春。","白云尋不得，紫府去無因。","此地空明月，何山伴羽人。","終期华表上，重见令威身。"]', '诗', 'shi', '', NULL, '憶鶴 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e51c2e4-da56-4b03-a51c-efd01ac12d4e', '聽夜泉', '听夜泉', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["靜裏層層石，潺湲到鶴林。","流迴出幾洞，源遠歷千岑。","寒助空山月，清兼此夜心。","幽人聽達曙，相和蘚牀吟。"]', '["静裏層層石，潺湲到鹤林。","流迴出幾洞，源远歷千岑。","寒助空山月，清兼此夜心。","幽人听達曙，相和蘚牀吟。"]', '诗', 'shi', '', NULL, '聽夜泉 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55514f96-18dc-412d-bdd7-218adfc9c4b8', '樂遊原春望', '乐游原春望', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["樂遊原上望，望盡帝都春。","始覺繁華地，應無不醉人。","雲開雙闕麗，柳映九衢新。","愛此頻來往，多閑逐此身。"]', '["乐游原上望，望尽帝都春。","始覺繁华地，應無不醉人。","云开雙闕丽，柳映九衢新。","愛此頻来往，多闲逐此身。"]', '诗', 'shi', '', NULL, '樂遊原春望 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('671f169b-74f0-4341-9794-b56981663920', '贈雍陶博士', '贈雍陶博士', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["腹是羣書笥，官爲六義師。","情高少塵事，朝下足閑時。","有句同人伏，無私胄子知。","漢庭公議在，正與觸邪宜。"]', '["腹是羣书笥，官爲六義師。","情高少塵事，朝下足闲时。","有句同人伏，無私胄子知。","漢庭公議在，正與觸邪宜。"]', '诗', 'shi', '', NULL, '贈雍陶博士 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be950e41-d288-48fc-ac81-10f672e10e82', '夏日感懷寄所知', '夏日感懷寄所知', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["了了見岐路，欲行難負心。","趨時不圓轉，自古易湮沈。","日正林方合，蜩鳴夏已深。","中郎今遠在，誰識爨桐音。"]', '["了了见岐路，欲行难負心。","趨时不圓轉，自古易湮沈。","日正林方合，蜩鳴夏已深。","中郎今远在，誰識爨桐音。"]', '诗', 'shi', '', NULL, '夏日感懷寄所知 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e0ac513-c652-4631-b893-d23c84b7b059', '陳情上知己', '陳情上知己', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["性與才俱拙，名場迹甚微。","久居顏亦厚，獨立事多非。","刻骨搜新句，無人憫白衣。","明時自堪戀，不是不知機。"]', '["性與才俱拙，名場迹甚微。","久居顏亦厚，独立事多非。","刻骨搜新句，無人憫白衣。","明时自堪戀，不是不知機。"]', '诗', 'shi', '', NULL, '陳情上知己 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d831bfd0-8896-458c-a99d-4caff225b24d', '秋夜寄友人二首 一', '秋夜寄友人二首 一', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["永夜無他慮，長吟畢二更。","暗燈搖碧影，滯雨滴堦聲。","道進愁還淺，年加睡自輕。","如何得深術，相與捨浮名。"]', '["永夜無他慮，长吟畢二更。","暗灯搖碧影，滯雨滴堦声。","道進愁還淺，年加睡自轻。","如何得深術，相與捨浮名。"]', '诗', 'shi', '', NULL, '秋夜寄友人二首 一 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36b8a859-6ad4-4a45-97a2-2ccba295e584', '秋夜寄友人二首 二', '秋夜寄友人二首 二', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["所思同海岱，所夢亦煙波。","默坐看山久，閑行值寺過。","獨吟黃葉亂，相去碧峰多。","我有歸心在，君行竟若何。"]', '["所思同海岱，所梦亦煙波。","默坐看山久，闲行值寺過。","独吟黄葉亂，相去碧峰多。","我有归心在，君行竟若何。"]', '诗', 'shi', '', NULL, '秋夜寄友人二首 二 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c73eb1e-1e2f-40de-90cd-2857e6935596', '寄春坊顧校書', '寄春坊顧校书', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["寧因不得志，寂寞本相宜。","冥目冥心坐，花開花落時。","數畦蔬甲出，半夢鳥聲移。","只恐龍樓吏，歸山又見違。"]', '["寧因不得志，寂寞本相宜。","冥目冥心坐，花开花落时。","數畦蔬甲出，半梦鸟声移。","只恐龙楼吏，归山又见違。"]', '诗', 'shi', '', NULL, '寄春坊顧校書 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74011ffb-7b38-471b-a8ad-b3b0e7c23bd3', '寄雍陶先輩', '寄雍陶先輩', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["久別青雲士，幽人分固然。","愁心不易去，蹇步卒難前。","盡落經霜葉，頻陰欲雪天。","歸山自有限，豈待白頭年。"]', '["久別青云士，幽人分固然。","愁心不易去，蹇步卒难前。","尽落經霜葉，頻陰欲雪天。","归山自有限，豈待白头年。"]', '诗', 'shi', '', NULL, '寄雍陶先輩 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ecebd171-37e0-4cc4-af91-4fdb3cc8b99d', '對月寄雍陶', '对月寄雍陶', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["圓明寒魄上，天地一光中。","臨水通宵坐，知君此興同。","華凝衣有露，靜極樹無風。","若向湘江見，湘江徹底空。"]', '["圓明寒魄上，天地一光中。","臨水通宵坐，知君此兴同。","华凝衣有露，静極樹無风。","若向湘江见，湘江徹底空。"]', '诗', 'shi', '', NULL, '對月寄雍陶 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c700f2d8-70aa-45bb-a629-4c031233965f', '寄謝觀', '寄謝观', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["十五年餘苦，今朝始遇君。","無慙於白日，不枉別孤雲。","得失天難問，稱揚鬼亦聞。","此恩銷鏤骨，吟坐葉紛紛。"]', '["十五年餘苦，今朝始遇君。","無慙於白日，不枉別孤云。","得失天难问，稱揚鬼亦闻。","此恩銷鏤骨，吟坐葉紛紛。"]', '诗', 'shi', '', NULL, '寄謝觀 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c28c1bb-a4bd-47ef-9b8b-948384c0d164', '送鄂州崔大夫赴鎮', '送鄂州崔大夫赴鎮', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["廉問帝難人，朝庭輟重臣。","入山初有雪，登路正無塵。","去國鳴騶緩，經雲住斾頻。","千峰與萬木，清聽雨情新。"]', '["廉问帝难人，朝庭輟重臣。","入山初有雪，登路正無塵。","去国鳴騶緩，經云住斾頻。","千峰與万木，清听雨情新。"]', '诗', 'shi', '', NULL, '送鄂州崔大夫赴鎮 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78ac70fa-70b4-4765-81fd-843396890874', '送錢給事赴虢州', '送錢給事赴虢州', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["帝心憂虢俗，暫庭輟掖垣臣。","疲瘵初承制，鄉閭似得春。","化成應有瑞，位重轉聞貧。","用作鹽梅日，爭迴臥轍人。"]', '["帝心憂虢俗，暫庭輟掖垣臣。","疲瘵初承制，乡閭似得春。","化成應有瑞，位重轉闻貧。","用作鹽梅日，爭迴臥轍人。"]', '诗', 'shi', '', NULL, '送錢給事赴虢州 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d970f1c-e131-416a-a697-f1b808f09e69', '送雍陶侍御赴兖州裴尚書命', '送雍陶侍御赴兖州裴尚书命', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["綸閣知孤直，翻論北巷賢。","且縻蓮幕裏，會致玉堦前。","洙泗秋微動，龜蒙月正圓。","元戎軍務息，清句待君聯。"]', '["綸閣知孤直，翻論北巷賢。","且縻蓮幕裏，會致玉堦前。","洙泗秋微动，龟蒙月正圓。","元戎軍務息，清句待君聯。"]', '诗', 'shi', '', NULL, '送雍陶侍御赴兖州裴尚書命 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6cc338af-cc0a-4023-bef7-ccb1ad77c293', '送新羅人歸本國', '送新羅人归本国', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["雞林隔巨浸，一住一年行。","日近國先曙，風吹海不平。","眼穿鄉井樹，頭白渺瀰程。","到彼星霜換，唐家語却生。"]', '["雞林隔巨浸，一住一年行。","日近国先曙，风吹海不平。","眼穿乡井樹，头白渺瀰程。","到彼星霜換，唐家語却生。"]', '诗', 'shi', '', NULL, '送新羅人歸本國 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb04a1e4-2037-4557-8f64-8ff411d411db', '送車濤罷舉歸山', '送车濤罷舉归山', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["朝是暮還非，人情冷暖移。","浮生只如此，強進欲何爲。","要路知無援，深山必遇師。","憐君明此理，休去不遲疑。"]', '["朝是暮還非，人情冷暖移。","浮生只如此，強進欲何爲。","要路知無援，深山必遇師。","怜君明此理，休去不遲疑。"]', '诗', 'shi', '', NULL, '送車濤罷舉歸山 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca88948a-2217-4e99-aeec-b462b64ed530', '送王書記歸邠州', '送王书記归邠州', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["陳琳輕一別，馬上意超然。","來日行煩暑，歸時聽早蟬。","陰雲翳城郭，細雨紊山川。","從事公劉地，元戎舊禮賢。"]', '["陳琳轻一別，马上意超然。","来日行煩暑，归时听早蟬。","陰云翳城郭，細雨紊山川。","從事公劉地，元戎旧禮賢。"]', '诗', 'shi', '', NULL, '送王書記歸邠州 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1f2f173-b539-4d06-9db6-05e80a615c10', '送謝觀之劒南從事', '送謝观之劒南從事', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["迢遞從知己，他人敢更言。","離京雖未臘，到府已應暄。","飛急奔行鴈，啼酸憶子猨。","江山無限思，君擬共誰論。"]', '["迢遞從知己，他人敢更言。","離京雖未臘，到府已應暄。","飞急奔行鴈，啼酸憶子猨。","江山無限思，君擬共誰論。"]', '诗', 'shi', '', NULL, '送謝觀之劒南從事 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32183dec-fbda-47f9-8dba-2726587dadb8', '送顧非熊作尉盱眙', '送顧非熊作尉盱眙', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["一名兼一尉，未足是君伸。","厲數爲詩者，多來作諫臣。","路翻平楚闊，草帶古淮新。","天下雖云大，同聲有幾人。"]', '["一名兼一尉，未足是君伸。","厲數爲诗者，多来作諫臣。","路翻平楚闊，草带古淮新。","天下雖云大，同声有幾人。"]', '诗', 'shi', '', NULL, '送顧非熊作尉盱眙 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4e11d28-ade6-48af-bc37-a09ed8a0c2e6', '送高湘及第後東歸覲叔', '送高湘及第後东归覲叔', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["此去幾般榮，登科鼎足名。","無慙入南巷，高價聳東京。","窗對嵩山碧，庭來洛水聲。","門前桃李樹，一徑已陰成。"]', '["此去幾般榮，登科鼎足名。","無慙入南巷，高價聳东京。","窗对嵩山碧，庭来洛水声。","门前桃李樹，一徑已陰成。"]', '诗', 'shi', '', NULL, '送高湘及第後東歸覲叔 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54bb20d9-8a85-40a1-9505-c08101ed0aff', '送友人下第歸覲', '送友人下第归覲', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["君此卜行日，高堂應夢歸。","莫將和氏淚，滴著老萊衣。","嶽雨連河細，田禽出麥飛。","到家調膳後，吟苦落蟬暉。"]', '["君此卜行日，高堂應梦归。","莫將和氏泪，滴著老萊衣。","嶽雨連河細，田禽出麦飞。","到家調膳後，吟苦落蟬暉。"]', '诗', 'shi', '', NULL, '送友人下第歸覲 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1cdca0b-584e-424e-9f05-20b263c7c1d3', '送友人下第歸揚州覲省', '送友人下第归揚州覲省', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["新柳間花垂，東西京路岐。","園林知自到，寢食計相思。","雨斷淮山出，帆揚楚樹移。","晨昏心已泰，蟬發是回時。"]', '["新柳间花垂，东西京路岐。","园林知自到，寢食計相思。","雨斷淮山出，帆揚楚樹移。","晨昏心已泰，蟬發是回时。"]', '诗', 'shi', '', NULL, '送友人下第歸揚州覲省 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('190bb6b0-5c3e-46bd-afa7-1aa2f21e2fbf', '早行', '早行', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["萬類半已動，此心寧自安。","月沈平野盡，星隱曙空殘。","馬渡橫流廣，人行湛露寒。","還思猶夢者，不信早行難。"]', '["万類半已动，此心寧自安。","月沈平野尽，星隐曙空殘。","马渡橫流廣，人行湛露寒。","還思猶梦者，不信早行难。"]', '诗', 'shi', '', NULL, '早行 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c3f5026-f29b-4cb4-a5c1-0f6ed8d3d454', '通濟里居酬廬肇見尋不遇', '通濟里居酬廬肇见尋不遇', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["衡門掩綠苔，樹下絕塵埃。","偶赴高僧約，旋知長者來。","雲山堪眺望，車馬必裴回。","問以何爲待，慙無酒一杯。"]', '["衡门掩綠苔，樹下絕塵埃。","偶赴高僧約，旋知长者来。","云山堪眺望，车马必裴回。","问以何爲待，慙無酒一杯。"]', '诗', 'shi', '', NULL, '通濟里居酬廬肇見尋不遇 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4848e67c-4b51-41c4-bd9c-d906e13a2e58', '贈王尊師', '贈王尊師', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["爲道常日損，尊師修此心。","挂肩黃布被，穿髪白蒿簪。","符札靈砂字，弦彈古素琴。","囊中曾有藥，點土亦成金。"]', '["爲道常日損，尊師修此心。","挂肩黄布被，穿髪白蒿簪。","符札靈砂字，弦彈古素琴。","囊中曾有藥，点土亦成金。"]', '诗', 'shi', '', NULL, '贈王尊師 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('785c49d3-7be0-4b4d-a7ea-6175a4d58ea2', '冬夜與蔡校書宿無可上人院', '冬夜與蔡校书宿無可上人院', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["儒釋偶同宿，夜窗寒更清。","忘機於世久，晤語到天明。","月倒高松影，風旋一磬聲。","真門猶是幻，不用覺浮生。"]', '["儒釋偶同宿，夜窗寒更清。","忘機於世久，晤語到天明。","月倒高松影，风旋一磬声。","真门猶是幻，不用覺浮生。"]', '诗', 'shi', '', NULL, '冬夜與蔡校書宿無可上人院 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('316d736f-0f74-4687-baf0-fd3c7cac457e', '冬日喜同志宿', '冬日喜同志宿', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["相逢話清夜，言實轉相知。","共道名雖切，唯論命不疑。","吟身坐霜石，眠鳥握風枝。","別憶天台客，煙霞昔有期。"]', '["相逢話清夜，言實轉相知。","共道名雖切，唯論命不疑。","吟身坐霜石，眠鸟握风枝。","別憶天台客，煙霞昔有期。"]', '诗', 'shi', '', NULL, '冬日喜同志宿 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03a5e7a9-06b6-4d1a-a392-bcf0ca12cda2', '逢呂上山人', '逢呂上山人', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["塵裏正愁老，相逢眼益明。","從前枉多病，此後鮮疎名。","古柏今收子，深山許事兄。","長生如有分，願逐到蓬瀛。"]', '["塵裏正愁老，相逢眼益明。","從前枉多病，此後鲜疎名。","古柏今收子，深山許事兄。","长生如有分，願逐到蓬瀛。"]', '诗', 'shi', '', NULL, '逢呂上山人 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4fb66dc-e8e2-417f-88b3-2df1f0e52fca', '春暮對雨', '春暮对雨', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["春暮雨微微，翻疑墜葉時。","氣蒙楊柳重，寒勒牡丹遲。","未夕鳥先宿，望晴人有期。","何當廓陰閉，新暑竹風吹。"]', '["春暮雨微微，翻疑墜葉时。","氣蒙楊柳重，寒勒牡丹遲。","未夕鸟先宿，望晴人有期。","何當廓陰閉，新暑竹风吹。"]', '诗', 'shi', '', NULL, '春暮對雨 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50397bb4-b68f-43a0-bc2c-b7cfa36f50da', '長信宮', '长信宮', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["簟涼秋氣初，長信恨何如。","拂黛月生指，解鬟雲滿梳。","一從悲畫扇，幾度泣前魚。","坐聽南宮樂，清風搖翠裾。"]', '["簟涼秋氣初，长信恨何如。","拂黛月生指，解鬟云满梳。","一從悲畫扇，幾度泣前鱼。","坐听南宮乐，清风搖翠裾。"]', '诗', 'shi', '', NULL, '長信宮 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1bb6d134-5c32-4b4f-a00d-74fd7bf193ee', '初夏題段郎中修竹里南園', '初夏題段郎中修竹里南园', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["高人遊息處，與此曲池連。","密樹纔春後，深山在目前。","遠峰初絕雨，片石欲生煙。","數有僧來宿，應緣靜好禪。"]', '["高人游息处，與此曲池連。","密樹纔春後，深山在目前。","远峰初絕雨，片石欲生煙。","數有僧来宿，應緣静好禪。"]', '诗', 'shi', '', NULL, '初夏題段郎中修竹里南園 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b42236c0-f015-4bf2-bc4f-c6b407ed3289', '題景玄禪師院', '題景玄禪師院', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["古僧精進者，師復是誰流。","道貴行無我，禪難說到頭。","汲泉羸鶴立，擁褐老猨愁。","曾住深山院，何如此院幽。"]', '["古僧精進者，師复是誰流。","道貴行無我，禪难说到头。","汲泉羸鹤立，擁褐老猨愁。","曾住深山院，何如此院幽。"]', '诗', 'shi', '', NULL, '題景玄禪師院 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe62a52d-e93a-4c54-8962-7641bafc1c57', '夏日樊川別業即事', '夏日樊川別業即事', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["無事稱無才，柴門亦罕開。","脫巾吟永日，著屐步荒臺。","風卷微塵上，霆將暴雨來。","終南雲漸合，咫尺失崔嵬。"]', '["無事稱無才，柴门亦罕开。","脫巾吟永日，著屐步荒台。","风卷微塵上，霆將暴雨来。","終南云漸合，咫尺失崔嵬。"]', '诗', 'shi', '', NULL, '夏日樊川別業即事 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6cc30b55-c750-47ff-af4a-f3d913887862', '寄無可上人', '寄無可上人', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["省學爲詩日，宵吟每達晨。","十年期是夢，一事未成身。","枉別山中客，殊非世上人。","今來已如此，須得桂榮新。"]', '["省学爲诗日，宵吟每達晨。","十年期是梦，一事未成身。","枉別山中客，殊非世上人。","今来已如此，須得桂榮新。"]', '诗', 'shi', '', NULL, '寄無可上人 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae383f81-ff32-431c-95e5-ba280eadc54f', '和范校書贈造微上人', '和范校书贈造微上人', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["得性見微公，何曾執著空。","修心將佛竝，吐論與儒通。","曉漱松杉下，宵禪雪月中。","他生有緣會，君子亦應同。"]', '["得性见微公，何曾執著空。","修心將佛竝，吐論與儒通。","晓漱松杉下，宵禪雪月中。","他生有緣會，君子亦應同。"]', '诗', 'shi', '', NULL, '和范校書贈造微上人 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9c08297-a2e7-4353-85d6-0f92010a165b', '訪曲江胡處士', '訪曲江胡处士', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["何況歸山後，而今已似仙。","卜居天苑畔，閑步禁樓前。","落日明沙岸，微風上紙鳶。","靜還林石下，坐讀養生篇。"]', '["何況归山後，而今已似仙。","卜居天苑畔，闲步禁楼前。","落日明沙岸，微风上紙鳶。","静還林石下，坐读養生篇。"]', '诗', 'shi', '', NULL, '訪曲江胡處士 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d10f711a-b2a1-4f39-8b6a-220594025cb2', '慈恩寺塔下避暑', '慈恩寺塔下避暑', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["古松凌巨塔，脩竹映空廊。","竟日聞虛籟，深山只此涼。","僧真生我靜，水淡發茶香。","坐久東樓望，鐘聲振夕陽。"]', '["古松凌巨塔，脩竹映空廊。","竟日闻虛籟，深山只此涼。","僧真生我静，水淡發茶香。","坐久东楼望，鐘声振夕陽。"]', '诗', 'shi', '', NULL, '慈恩寺塔下避暑 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ee61090-d908-4cd3-9d71-ef302ccbede7', '秋晚與友人遊青龍寺', '秋晚與友人游青龙寺', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["高視終南秀，西風度閣涼。","一生同隙影，幾處好山光。","暮鳥投嬴木，寒鐘送夕陽。","因居話心地，川冥宿僧房。"]', '["高視終南秀，西风度閣涼。","一生同隙影，幾处好山光。","暮鸟投嬴木，寒鐘送夕陽。","因居話心地，川冥宿僧房。"]', '诗', 'shi', '', NULL, '秋晚與友人遊青龍寺 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9d0d1fe-464a-4a4b-b497-2e2e7b8713ae', '春日雨後作', '春日雨後作', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["朝來微有雨，天地爽無塵。","北厥明如晝，南山碧動人。","車輿終日別，草樹一城新。","枉是吾君戚，何門謁紫宸。"]', '["朝来微有雨，天地爽無塵。","北厥明如晝，南山碧动人。","车輿終日別，草樹一城新。","枉是吾君戚，何门謁紫宸。"]', '诗', 'shi', '', NULL, '春日雨後作 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89881aa6-2479-4d76-8bbd-bdb68acab3a6', '別王山人', '別王山人', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["旨甘雖自足，未是祿榮親。","尚逐趨時伴，多離有道人。","山居衣以草，生寄藥隨身。","不食長無疾，年知出十旬。"]', '["旨甘雖自足，未是祿榮親。","尚逐趨时伴，多離有道人。","山居衣以草，生寄藥隨身。","不食长無疾，年知出十旬。"]', '诗', 'shi', '', NULL, '別王山人 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d145d16f-5c47-40d0-9b2e-a8ad34ef40e9', '贈陶山人', '贈陶山人', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["處士例營營，惟君縱此生。","閑能資壽考，健不換公卿。","藥圃妻同耨，山田子共耕。","定知丹熟後，無姓亦無名。"]', '["处士例營營，惟君縱此生。","闲能資壽考，健不換公卿。","藥圃妻同耨，山田子共耕。","定知丹熟後，無姓亦無名。"]', '诗', 'shi', '', NULL, '贈陶山人 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0864c886-51ed-4774-979c-f3503805d74f', '禁署早春晴望', '禁署早春晴望', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["御林聞有早鶯聲，玉檻春香九陌晴。","寒著霽雲歸紫閣，暖浮佳氣動芳城。","宮池日到冰初解，輦路風吹草欲生。","鴛侶此時皆賦詠，商山雪在思尤清。"]', '["御林闻有早鶯声，玉檻春香九陌晴。","寒著霽云归紫閣，暖浮佳氣动芳城。","宮池日到冰初解，輦路风吹草欲生。","鴛侶此时皆賦詠，商山雪在思尤清。"]', '诗', 'shi', '', NULL, '禁署早春晴望 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8281301a-f855-458f-9814-97a2dfca7c51', '山中尋道人不遇', '山中尋道人不遇', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["年過弱冠風塵裏，常擬隨師學鍊形。","石路特來尋道者，雲房空見有仙經。","碁於松底留殘局，鶴向潭邊退數翎。","便欲此居閑到老，先生何日下青冥。"]', '["年過弱冠风塵裏，常擬隨師学鍊形。","石路特来尋道者，云房空见有仙經。","碁於松底留殘局，鹤向潭邊退數翎。","便欲此居闲到老，先生何日下青冥。"]', '诗', 'shi', '', NULL, '山中尋道人不遇 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d99e3bf8-a9bd-418e-b68b-74eb247f4333', '贈敬晊助教二首 一', '贈敬晊助教二首 一', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["到來常聽說清虛，手把玄元七字書。","仙籍不知名姓有，道情惟見往來疎。","已能絕粒無飢色，早晚休官買隱居。","便欲去隨爲弟子，片雲孤鶴可相於。"]', '["到来常听说清虛，手把玄元七字书。","仙籍不知名姓有，道情惟见往来疎。","已能絕粒無飢色，早晚休官買隐居。","便欲去隨爲弟子，片云孤鹤可相於。"]', '诗', 'shi', '', NULL, '贈敬晊助教二首 一 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24382132-0f96-49f4-99bd-cd66f346932d', '贈敬晊助教二首 二', '贈敬晊助教二首 二', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["街西靜觀求居處，不到權門到寺頻。","禁掖人知連狀薦，國庠官滿一家貧。","清儀稱是蓬瀛客，直氣堪爲諫諍臣。","自顧無成年漸長，報恩惟願殺微身。"]', '["街西静观求居处，不到權门到寺頻。","禁掖人知連狀薦，国庠官满一家貧。","清儀稱是蓬瀛客，直氣堪爲諫諍臣。","自顧無成年漸长，報恩惟願殺微身。"]', '诗', 'shi', '', NULL, '贈敬晊助教二首 二 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90e530f9-651e-42f1-a03c-5c5059646b2f', '送祖山人歸山', '送祖山人归山', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["獨來朝市笑浮雲，却憶煙霞出帝城。","不說金丹能點化，空教弟子學長生。","壺中瀉酒看雲影，洞裏逢師下鶴迎。","料得仙家玉牌上，已鐫白日上昇名。"]', '["独来朝市笑浮云，却憶煙霞出帝城。","不说金丹能点化，空教弟子学长生。","壺中瀉酒看云影，洞裏逢師下鹤迎。","料得仙家玉牌上，已鐫白日上昇名。"]', '诗', 'shi', '', NULL, '送祖山人歸山 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('805edd84-2acf-48cb-b45e-313cea835b68', '監試蓮花峰', '監試蓮花峰', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["太華萬餘重，岧嶤只此峰。","當秋倚寥泬，入望似芙蓉。","翠拔千尋直，青危一朵穠。","氣分毛女秀，靈有羽人蹤。","倒影侵官路，流香激廟松。","塵埃終不及，車馬自憧憧。"]', '["太华万餘重，岧嶤只此峰。","當秋倚寥泬，入望似芙蓉。","翠拔千尋直，青危一朵穠。","氣分毛女秀，靈有羽人蹤。","倒影侵官路，流香激廟松。","塵埃終不及，车马自憧憧。"]', '诗', 'shi', '', NULL, '監試蓮花峰 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3162fc3c-6966-4a74-a8dc-d7ff9f823bd5', '京兆府試目極千里', '京兆府試目極千里', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["獻賦多年客，低眉恨不前。","此心常鬱矣，縱目忽超然。","送驥登長路，有鴻入遠天。","古墟煙冪冪，窮野草綿綿。","樹與金城接，山疑桂水連。","何當開霽日，無物翳平川。"]', '["獻賦多年客，低眉恨不前。","此心常鬱矣，縱目忽超然。","送驥登长路，有鴻入远天。","古墟煙冪冪，窮野草綿綿。","樹與金城接，山疑桂水連。","何當开霽日，無物翳平川。"]', '诗', 'shi', '', NULL, '京兆府試目極千里 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b022a966-3974-4005-83f9-3e0fbad78f47', '尋陳處士山堂', '尋陳处士山堂', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["步溪凡幾轉，始得見幽蹤。","路隱千根樹，門開萬仞峰。","片雲生石竇，淺水臥枯松。","窮谷風光冷，深山翠碧濃。","鶴看空裏過，仙向坐中逢。","底露秋潭水，聲微暮觀鐘。","他年來此定，異日願相容。","且喜今歸去，人間事更慵。"]', '["步溪凡幾轉，始得见幽蹤。","路隐千根樹，门开万仞峰。","片云生石竇，淺水臥枯松。","窮谷风光冷，深山翠碧濃。","鹤看空裏過，仙向坐中逢。","底露秋潭水，声微暮观鐘。","他年来此定，異日願相容。","且喜今归去，人间事更慵。"]', '诗', 'shi', '', NULL, '尋陳處士山堂 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0cf3e4fa-5683-4d0f-a788-4d99e9cccb0b', '題從伯舍人道正里南園', '題從伯舍人道正里南园', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["帝里餘新第，朱門面碧岑。","曙堂增爽氣，喬木動清陰。","直去親瑤陛，朝迴在竹林。","風流才子調，好尚古人心。","薜荔遮窗暗，莓苔近井深。","禮無青草隔，詩共白衣吟。","軒靜留孤鶴，庭虛到遠砧。","掩關裁鳳詔，開鏡理瓊簪。","種植今如此，塵埃永不侵。","雲奔投刺者，日日待爲霖。"]', '["帝里餘新第，朱门面碧岑。","曙堂增爽氣，喬木动清陰。","直去親瑤陛，朝迴在竹林。","风流才子調，好尚古人心。","薜荔遮窗暗，莓苔近井深。","禮無青草隔，诗共白衣吟。","軒静留孤鹤，庭虛到远砧。","掩关裁鳳詔，开镜理瓊簪。","種植今如此，塵埃永不侵。","云奔投刺者，日日待爲霖。"]', '诗', 'shi', '', NULL, '題從伯舍人道正里南園 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6777f6f1-7d62-44e7-b785-0fca3e34bb05', '賦得聽松聲', '賦得听松声', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["庭際微風動，高松韻自生。","聽時無物亂，盡日覺神清。","強與幽泉竝，翻嫌細雨幷。","拂空增鶴唳，過牖合琴聲。","況復當秋暮，偏宜在月明。","不知深澗底，蕭瑟有誰聽。"]', '["庭際微风动，高松韻自生。","听时無物亂，尽日覺神清。","強與幽泉竝，翻嫌細雨幷。","拂空增鹤唳，過牖合琴声。","況复當秋暮，偏宜在月明。","不知深澗底，蕭瑟有誰听。"]', '诗', 'shi', '', NULL, '賦得聽松聲 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('972f30a9-b76a-47e1-b075-2816554d79c5', '宿普濟寺', '宿普濟寺', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["京寺數何窮，清幽此不同。","曲江臨閣北，御苑自牆東。","廣陌車音急，危樓夕景通。","亂峰沈暝野，毒暑過秋空。","幡揚虛無裡，星生杳靄中。","月光籠月殿，蓮氣入蓮宮。","綴草涼天露，吹人古木風。","飲茶除假寐，聞磬釋塵蒙。","童子眠苔淨，高僧話漏終。","待鳴曉鐘後，萬井復朣朧。"]', '["京寺數何窮，清幽此不同。","曲江臨閣北，御苑自牆东。","廣陌车音急，危楼夕景通。","亂峰沈暝野，毒暑過秋空。","幡揚虛無裡，星生杳靄中。","月光籠月殿，蓮氣入蓮宮。","綴草涼天露，吹人古木风。","饮茶除假寐，闻磬釋塵蒙。","童子眠苔淨，高僧話漏終。","待鳴晓鐘後，万井复朣朧。"]', '诗', 'shi', '', NULL, '宿普濟寺 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52595d46-a77e-4a59-8a99-22e8845ea56a', '和鄭校書夏日遊鄭泉', '和鄭校书夏日游鄭泉', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["太虛懸畏景，古木蔽清陰。","爰有泉堪挹，閑思日可尋。","來聞鳴滴滴，照竦碧沈沈。","幾脉成溪壑，何人測淺深。","澄時無一物，分處厲千林。","淨溉靈根藥，涼浮玉翅禽。","飲疑蠲宿疾，見自失煩襟。","僧共雲前瀨，龍和月下吟。","疊光輕吹動，徹底曉霞侵。","不用頻遊去，令君少進心。"]', '["太虛懸畏景，古木蔽清陰。","爰有泉堪挹，闲思日可尋。","来闻鳴滴滴，照竦碧沈沈。","幾脉成溪壑，何人測淺深。","澄时無一物，分处厲千林。","淨溉靈根藥，涼浮玉翅禽。","饮疑蠲宿疾，见自失煩襟。","僧共云前瀨，龙和月下吟。","叠光轻吹动，徹底晓霞侵。","不用頻游去，令君少進心。"]', '诗', 'shi', '', NULL, '和鄭校書夏日遊鄭泉 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29ad430b-4f67-43c7-bbd2-0a7020e2a9aa', '和段校書冬夕寄題廬山', '和段校书冬夕寄題廬山', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["名高身未到，此恨蓄多時。","是夕吟因話，他年必去隨。","嘗聞廬嶽頂，半入楚江湄。","幾處懸崖上，千尋瀑布垂。","爐峰松淅瀝，湓浦柳參差。","日色連湖白，鐘聲拂浪遲。","煙梯緣薜荔，嶽寺步欹危。","地本饒靈草，林曾出祖師。","石樓霞耀壁，猨樹鶴分枝。","細徑縈巖末，高窗見海涯。","嵌空寒更極，寂寞夜尤思。","陰谷冰埋朮，仙田雪覆芝。","亂泉禪客瀨，異迹逸人知。","蘚室新開竈，檉潭末了棋。","如何遂閑放，長得在希夷。","空務漁樵事，方無道路悲。","謝公臺尚在，陶令柳潛衰。","塵外難相許，人間貴迹遺。","雖懷丹桂影，不忘白雲期。","仁者終攜手，今朝預賦詩。"]', '["名高身未到，此恨蓄多时。","是夕吟因話，他年必去隨。","嘗闻廬嶽頂，半入楚江湄。","幾处懸崖上，千尋瀑布垂。","爐峰松淅瀝，湓浦柳參差。","日色連湖白，鐘声拂浪遲。","煙梯緣薜荔，嶽寺步欹危。","地本饒靈草，林曾出祖師。","石楼霞耀壁，猨樹鹤分枝。","細徑縈巖末，高窗见海涯。","嵌空寒更極，寂寞夜尤思。","陰谷冰埋朮，仙田雪覆芝。","亂泉禪客瀨，異迹逸人知。","蘚室新开竈，檉潭末了棋。","如何遂闲放，长得在希夷。","空務漁樵事，方無道路悲。","謝公台尚在，陶令柳潛衰。","塵外难相許，人间貴迹遺。","雖懷丹桂影，不忘白云期。","仁者終携手，今朝預賦诗。"]', '诗', 'shi', '', NULL, '和段校書冬夕寄題廬山 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9db9b28-6597-4bf5-a1da-1e7831c91184', '書事寄萬年厲員外', '书事寄万年厲員外', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["帝城皆劇縣，令尹美居東。","遂拜趙張下，蹔離星象中。","擁歸從北闕，送上動南宮。","紫禁黃山遶，滄溟素滻通。","封疆親日月，邑里出王公。","賦稅充天府，歌謠入聖聰。","土膏寒麥覆，人海晝塵蒙。","廨宇松連翠，朝街火散紅。","文場新桂茂，粉署舊蘭崇。","留客揮盈爵，抽毫詠早鴻。","前騶潘岳貴，故里邵平窮。","勸隱蓮峰久，期耕樹谷同。","鳧飛將去葉，劒氣尚埋豐。","何必華陰土，方垂拂拭功。"]', '["帝城皆劇縣，令尹美居东。","遂拜趙張下，蹔離星象中。","擁归從北闕，送上动南宮。","紫禁黄山遶，滄溟素滻通。","封疆親日月，邑里出王公。","賦稅充天府，歌謠入聖聰。","土膏寒麦覆，人海晝塵蒙。","廨宇松連翠，朝街火散紅。","文場新桂茂，粉署旧蘭崇。","留客揮盈爵，抽毫詠早鴻。","前騶潘岳貴，故里邵平窮。","勸隐蓮峰久，期耕樹谷同。","鳧飞將去葉，劒氣尚埋豐。","何必华陰土，方垂拂拭功。"]', '诗', 'shi', '', NULL, '書事寄萬年厲員外 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('905c8101-f5d9-4b47-95c1-3102068dba4b', '上姚諫議', '上姚諫議', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["高文與盛德，皆謂古無倫。","聖代生才子，明庭有諫臣。","已瞻龍衮近，漸向鳳池新。","却憶波濤郡，來時島嶼春。","名因詩句大，家似布衣貧。","曾暗投新軸，頻聞獎滯身。","照吟清夕月，送藥紫霞人。","終計依門館，何疑不化鱗。"]', '["高文與盛德，皆謂古無倫。","聖代生才子，明庭有諫臣。","已瞻龙衮近，漸向鳳池新。","却憶波濤郡，来时島嶼春。","名因诗句大，家似布衣貧。","曾暗投新軸，頻闻獎滯身。","照吟清夕月，送藥紫霞人。","終計依门館，何疑不化鱗。"]', '诗', 'shi', '', NULL, '上姚諫議 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7aaf13e-81c3-4327-8477-d365443f8e03', '上翰林丁學士', '上翰林丁学士', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["今代如堯代，徵賢察衆情。","久聆推行寔，然後佐聰明。","官自文華重，恩因顧問生。","詞人求作稱，天子許和羹。","御柳凋霜晚，宮泉滴月清。","直廬寒漏近，秋燭白麻成。","玉殿移時對，金輿數侍行。","賜衣香未散，借馬色難名。","時輩何偏羨，儒流此最榮。","終當聞夑理，寰宇永昇平。"]', '["今代如堯代，徵賢察衆情。","久聆推行寔，然後佐聰明。","官自文华重，恩因顧问生。","词人求作稱，天子許和羹。","御柳凋霜晚，宮泉滴月清。","直廬寒漏近，秋燭白麻成。","玉殿移时对，金輿數侍行。","賜衣香未散，借马色难名。","时輩何偏羨，儒流此最榮。","終當闻夑理，寰宇永昇平。"]', '诗', 'shi', '', NULL, '上翰林丁學士 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('317e4d45-6475-4905-bab3-56fde484c321', '二', '二', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["何處訪岐路，青雲但憶歸。","風塵數年限，門館一生依。","外族帝王是，中朝親舊稀。","翻令浮議者，不許九霄飛。"]', '["何处訪岐路，青云但憶归。","风塵數年限，门館一生依。","外族帝王是，中朝親旧稀。","翻令浮議者，不許九霄飞。"]', '诗', 'shi', '', NULL, '二 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d940c14b-44e3-4fa1-b3ae-7690fc7e97d9', '山中舒懷寄上丁學士', '山中舒懷寄上丁学士', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["五字投精鑒，慙非大雅詞。","本求閑賜覽，豈料便蒙知。","幽拙欣殊幸，提攜更不疑。","弱苗須雨長，懶翼在風吹。","礪鏃端楊葉，光門待桂枝。","計聞塵裏譽，因和禁中詩。"]', '["五字投精鑒，慙非大雅词。","本求闲賜覽，豈料便蒙知。","幽拙欣殊幸，提携更不疑。","弱苗須雨长，懶翼在风吹。","礪鏃端楊葉，光门待桂枝。","計闻塵裏譽，因和禁中诗。"]', '诗', 'shi', '', NULL, '山中舒懷寄上丁學士 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('334f9b36-52a5-4240-b83c-12755ffe5d86', '鶯出谷', '鶯出谷', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["東風潛啓物，動息意皆新。","此鳥從幽谷，依林報早春。","出寒雖未及，振羽漸能頻。","稍類沖天鶴，多隨折桂人。","尊前喧有語，花裏晝藏身。","若向穠華處，餘禽不見親。"]', '["东风潛啓物，动息意皆新。","此鸟從幽谷，依林報早春。","出寒雖未及，振羽漸能頻。","稍類沖天鹤，多隨折桂人。","尊前喧有語，花裏晝藏身。","若向穠华处，餘禽不见親。"]', '诗', 'shi', '', NULL, '鶯出谷 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b0c00e0-5f71-46a7-8733-8b1abed9354f', '哭翰林丁侍郎', '哭翰林丁侍郎', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["相知出肺腑，非舊亦非親。","每見雲霄侶，多陽鄙拙身。","即期扶泰運，豈料哭賢人。","應是隨先帝，依前作近臣。","平生任公直，愛弟尚風塵。","宅閉青松古，墳臨赤水新。","官清仍齒壯，兒小復家貧。","惆悵天難問，空流淚滿巾。"]', '["相知出肺腑，非旧亦非親。","每见云霄侶，多陽鄙拙身。","即期扶泰運，豈料哭賢人。","應是隨先帝，依前作近臣。","平生任公直，愛弟尚风塵。","宅閉青松古，墳臨赤水新。","官清仍齒壯，兒小复家貧。","惆悵天难问，空流泪满巾。"]', '诗', 'shi', '', NULL, '哭翰林丁侍郎 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0681f1f-81d3-478f-98c2-39bbd6a5657a', '陳情上李景讓大夫', '陳情上李景讓大夫', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["一被浮名誤，旋遭白髮侵。","裴回戀明主，夢寐在秋岑。","遇物唯多感，居常只是吟。","待時鉗定口，經事壓低心。","辛苦文場久，因緣戚里深。","老迷新道路，貧賣舊園林。","晴賞行聞水，宵棊坐見參。","龜留閑去問，僧約偶來尋。","望喜潛憑鵲，娛情願有琴。","此生如遂意，誓死報知音。","上德憐孤直，唯公拔陸沈。","丘山恩忽被，螻蟻力難任。","作鑒明同日，聽言重若金。","從茲更無限，翹足俟爲霖。"]', '["一被浮名誤，旋遭白髮侵。","裴回戀明主，梦寐在秋岑。","遇物唯多感，居常只是吟。","待时鉗定口，經事壓低心。","辛苦文場久，因緣戚里深。","老迷新道路，貧賣旧园林。","晴賞行闻水，宵棊坐见參。","龟留闲去问，僧約偶来尋。","望喜潛憑鵲，娛情願有琴。","此生如遂意，誓死報知音。","上德怜孤直，唯公拔陸沈。","丘山恩忽被，螻蟻力难任。","作鑒明同日，听言重若金。","從茲更無限，翹足俟爲霖。"]', '诗', 'shi', '', NULL, '陳情上李景讓大夫 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16114419-f06b-44b5-af56-4af8fed1658e', '和鄭先輩謝秩閑居寓書所懷', '和鄭先輩謝秩闲居寓书所懷', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["西風日夜吹，萬木共離披。","近甸新晴後，高人得意時。","暫閑心亦泰，論道面難欺。","把筆還詩債，將琴當酒資。","藍衫懸竹桁，烏帽挂松枝。","名占文章重，官歸諫憲遲。","生涯貧帝里，公議到台司。","室冷沾苔蘚，門清絕路岐。","莫言鄰白屋，即賀立丹墀。","豈慮塵埃久，雲霄故有期。"]', '["西风日夜吹，万木共離披。","近甸新晴後，高人得意时。","暫闲心亦泰，論道面难欺。","把笔還诗債，將琴當酒資。","藍衫懸竹桁，烏帽挂松枝。","名占文章重，官归諫憲遲。","生涯貧帝里，公議到台司。","室冷沾苔蘚，门清絕路岐。","莫言鄰白屋，即賀立丹墀。","豈慮塵埃久，云霄故有期。"]', '诗', 'shi', '', NULL, '和鄭先輩謝秩閑居寓書所懷 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b18e6e00-7c44-484c-9197-f4cacdda35ca', '病中晨起即事寄場中往還', '病中晨起即事寄場中往還', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["昨日離塵裏，今朝懶已成。","豈能爲久隱，更欲泥浮名。","虛牖晨光白，幽園曉氣清。","戴沙尋水去，披霧入林行。","疊葉孤禽在，初陽半樹明。","桑麻新雨潤，蘆荻古波聲。","易向田家熟，元于世路生。","病多三徑塞，吟苦四鄰驚。"]', '["昨日離塵裏，今朝懶已成。","豈能爲久隐，更欲泥浮名。","虛牖晨光白，幽园晓氣清。","戴沙尋水去，披霧入林行。","叠葉孤禽在，初陽半樹明。","桑麻新雨潤，蘆荻古波声。","易向田家熟，元于世路生。","病多三徑塞，吟苦四鄰驚。"]', '诗', 'shi', '', NULL, '病中晨起即事寄場中往還 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd989d0a-b616-40a4-acda-574811deb1d6', '悲老宮人', '悲老宮人', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["白髮宮娃不解悲，滿頭猶自插花枝。","曾緣玉貌君王寵，準擬人看似舊時。"]', '["白髮宮娃不解悲，满头猶自插花枝。","曾緣玉貌君王寵，準擬人看似旧时。"]', '诗', 'shi', '', NULL, '悲老宮人 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4e71f6b-3ac3-4563-8a7f-23fb8edd286d', '村中閑步', '村中闲步', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["閑共野人臨野水，新秋高樹挂清暉。","不知塵里無窮事，白鳥雙飛入翠微。"]', '["闲共野人臨野水，新秋高樹挂清暉。","不知塵里無窮事，白鸟雙飞入翠微。"]', '诗', 'shi', '', NULL, '村中閑步 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('081391b5-bb6c-4fc0-89da-c68e67061117', '上巳日', '上巳日', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["未敢分明賞物華，十年如見夢中花。","遊人過盡衡門掩，獨自凭欄到日斜。"]', '["未敢分明賞物华，十年如见梦中花。","游人過尽衡门掩，独自凭欄到日斜。"]', '诗', 'shi', '', NULL, '上巳日 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb6cae31-a706-4a2b-af71-f62dca8c9875', '省試日上崔侍郎四首 一', '省試日上崔侍郎四首 一', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["衣上年年淚血痕，只將懷抱訴乾坤。","如今主聖臣賢日，豈致人間一物冤。"]', '["衣上年年泪血痕，只將懷抱訴乾坤。","如今主聖臣賢日，豈致人间一物冤。"]', '诗', 'shi', '', NULL, '省試日上崔侍郎四首 一 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4283ce43-ec9c-4b01-8986-93f7b261b55d', '省試日上崔侍郎四首 二', '省試日上崔侍郎四首 二', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["如病如癡二十秋，求名難得又難休。","回看骨肉須堪恥，一著麻衣便白頭。"]', '["如病如癡二十秋，求名难得又难休。","回看骨肉須堪恥，一著麻衣便白头。"]', '诗', 'shi', '', NULL, '省試日上崔侍郎四首 二 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27ad0030-f8e6-4193-8ead-5cb8709856d6', '省試日上崔侍郎四首 三', '省試日上崔侍郎四首 三', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["戚里稱儒媿小才，禮闈公道此時開。","他人何事虛相指，明主無私不是媒。"]', '["戚里稱儒媿小才，禮闈公道此时开。","他人何事虛相指，明主無私不是媒。"]', '诗', 'shi', '', NULL, '省試日上崔侍郎四首 三 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('007a18ee-6f67-4323-84ef-db707f098030', '省試日上崔侍郎四首 四', '省試日上崔侍郎四首 四', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["方寸終朝似火然，爲求白日上青天。","自嗟辜負平生眼，不識春光二十年。"]', '["方寸終朝似火然，爲求白日上青天。","自嗟辜負平生眼，不識春光二十年。"]', '诗', 'shi', '', NULL, '省試日上崔侍郎四首 四 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('720cddd2-8fb9-4c3b-9ab6-48843d9dc70d', '秋夜', '秋夜', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["秋氣滿堂孤燭冷，清宵無寐憶山歸。","窗前月過三更後，細竹吟風似雨微。"]', '["秋氣满堂孤燭冷，清宵無寐憶山归。","窗前月過三更後，細竹吟风似雨微。"]', '诗', 'shi', '', NULL, '秋夜 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d95be93-4b1d-477d-9e26-773a89fb8588', '長門怨', '长门怨', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["爭得一人聞此怨，長門深夜有妍姝。","早知雨露翻相悞，只插荆釵嫁匹夫。"]', '["爭得一人闻此怨，长门深夜有妍姝。","早知雨露翻相悞，只插荆釵嫁匹夫。"]', '诗', 'shi', '', NULL, '長門怨 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d773f4b-7e6e-41be-8d98-6961f29ac814', '賈婦怨', '賈婦怨', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["嫁與商人頭欲白，未曾一日得雙行。","任君逐利輕江海，莫把風濤似妾輕。"]', '["嫁與商人头欲白，未曾一日得雙行。","任君逐利轻江海，莫把风濤似妾轻。"]', '诗', 'shi', '', NULL, '賈婦怨 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ae6c860-b5be-4270-ad3b-a57fcf7be7b0', '寄友人', '寄友人', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["風颯沈思眼忽開，塵埃污得是庸才。","那堪更見巢松鶴，飛入青雲不下來。"]', '["风颯沈思眼忽开，塵埃污得是庸才。","那堪更见巢松鹤，飞入青云不下来。"]', '诗', 'shi', '', NULL, '寄友人 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('470ffb4c-de73-46fa-8aeb-f773da19e394', '晏起', '晏起', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["日過辰時猶在夢，客來應笑也求名。","浮生自得長高枕，不向人間與命爭。"]', '["日過辰时猶在梦，客来應笑也求名。","浮生自得长高枕，不向人间與命爭。"]', '诗', 'shi', '', NULL, '晏起 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22a7a7f5-8476-44da-9918-ccec79c42898', '馬上別單于劉評事', '马上別單于劉評事', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["廟謀宏遠人難測，公主生還帝感深。","天下底平須共喜，一時閑事莫驚心。"]', '["廟謀宏远人难測，公主生還帝感深。","天下底平須共喜，一时闲事莫驚心。"]', '诗', 'shi', '', NULL, '馬上別單于劉評事 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('917638b9-f60e-4f06-adba-4b2564f8657c', '贈從弟谷', '贈從弟谷', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["此世榮枯豈足驚，相逢惟要眼長青。","從來不愛三閭死，今日憑君莫獨醒。"]', '["此世榮枯豈足驚，相逢惟要眼长青。","從来不愛三閭死，今日憑君莫独醒。"]', '诗', 'shi', '', NULL, '贈從弟谷 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c776f78-a13c-49a8-bba2-68cbb50a7a83', '別山居', '別山居', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["萬壑千巖景象開，登臨未足又須回。","憑師莫斷松間路，秋月圓時弟子來。"]', '["万壑千巖景象开，登臨未足又須回。","憑師莫斷松间路，秋月圓时弟子来。"]', '诗', 'shi', '', NULL, '別山居 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b745136-cb59-40fb-a44f-0db2dbd983fd', '贈道人', '贈道人', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["長在城中無定業，賣丹磨鏡兩途貧。","三山來往尋常事，不省曾驚市井人。"]', '["长在城中無定業，賣丹磨镜兩途貧。","三山来往尋常事，不省曾驚市井人。"]', '诗', 'shi', '', NULL, '贈道人 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60425d83-727c-4642-b19c-c7198a84d101', '對月寄同志', '对月寄同志', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["霜滿中庭月在林，塞鴻頻過又更深。","支頤不語相思坐，料得君心似我心。"]', '["霜满中庭月在林，塞鴻頻過又更深。","支頤不語相思坐，料得君心似我心。"]', '诗', 'shi', '', NULL, '對月寄同志 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71afe261-2093-41ab-8b68-59d0bd4b91c3', '憶鶴', '憶鹤', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["白絲翎羽丹砂頂，曉度秋煙出翠微。","來向孤松枝上立，見人吟苦却高飛。"]', '["白絲翎羽丹砂頂，晓度秋煙出翠微。","来向孤松枝上立，见人吟苦却高飞。"]', '诗', 'shi', '', NULL, '憶鶴 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b720a3be-ffef-4606-9884-129d27af9b6b', '雲門寺', '云门寺', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["上方僧又起，清磬出林初。","吟苦曉燈暗，露零秋草疎。","舊山多夢到，流水送愁餘。","寄寺欲經歲，慚無親故書。"]', '["上方僧又起，清磬出林初。","吟苦晓灯暗，露零秋草疎。","旧山多梦到，流水送愁餘。","寄寺欲經歲，慚無親故书。"]', '诗', 'shi', '', NULL, '雲門寺 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d446a0c0-81f4-42df-ab74-26a4575dd893', '中秋宿鄧逸人居', '中秋宿鄧逸人居', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["偶與山僧宿，吟詩坐到明。","夜涼耽月色，秋渴漱泉聲。","磵木如竿聳，窗雲作片生。","白衣閑自貴，不揖漢公卿。"]', '["偶與山僧宿，吟诗坐到明。","夜涼耽月色，秋渴漱泉声。","磵木如竿聳，窗云作片生。","白衣闲自貴，不揖漢公卿。"]', '诗', 'shi', '', NULL, '中秋宿鄧逸人居 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dace2ed2-8258-4d6e-9f0e-917be68a2012', '句', '句', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["外家雖是帝，當路且無親。","白日只如哭，黃泉免恨無。","身閑甘旨下，白髮太平人。","同遊芳草寺，見示白雲詩。","猶祈啓金口，一爲動文權。","深山寺路千層石，竹杖椶鞋便可登。"]', '["外家雖是帝，當路且無親。","白日只如哭，黄泉免恨無。","身闲甘旨下，白髮太平人。","同游芳草寺，见示白云诗。","猶祈啓金口，一爲动文權。","深山寺路千層石，竹杖椶鞋便可登。"]', '诗', 'shi', '', NULL, '句 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c64bb3c-68fd-4dc0-8830-3c319892b3a2', '題山院', '題山院', '5e5bc1f8-aec5-4a2c-a8f8-b09e895b9899', '唐', '["萬葉風聲利，一山秋氣寒。","曉霜浮碧瓦，落日度朱欄。"]', '["万葉风声利，一山秋氣寒。","晓霜浮碧瓦，落日度朱欄。"]', '诗', 'shi', '', NULL, '題山院 權審 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43199678-079e-4d21-8f2f-811c906c1d34', '絕句', '絕句', '5e5bc1f8-aec5-4a2c-a8f8-b09e895b9899', '唐', '["得即高歌失即休，多悲多恨謾悠悠。","今朝有酒今朝醉，明日愁來明日愁。"]', '["得即高歌失即休，多悲多恨謾悠悠。","今朝有酒今朝醉，明日愁来明日愁。"]', '诗', 'shi', '', NULL, '絕句 權審 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a3ea083-2e71-4035-b46c-dedd73ed924b', '郡中有懷寄上睦州員外杜十三兄', '郡中有懷寄上睦州員外杜十三兄', '8e62fc14-bb91-4b61-a144-4a32ad0cde04', '唐', '["城枕溪流更淺斜，麗譙連帶邑人家。","經冬野菜青青色，未臘山梅處處花。","雖免嶂雲生嶺上，永無音信到天涯。","如今歲[晏]從羈滯，心喜彈冠事不賒。"]', '["城枕溪流更淺斜，丽譙連带邑人家。","經冬野菜青青色，未臘山梅处处花。","雖免嶂云生嶺上，永無音信到天涯。","如今歲[晏]從羈滯，心喜彈冠事不賒。"]', '诗', 'shi', '', NULL, '郡中有懷寄上睦州員外杜十三兄 邢羣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22730452-aa1a-4986-99d7-68ea1b0a5eaa', '早發靈芝望九華寄杜員外使君', '早發靈芝望九华寄杜員外使君', '7b3922a5-baa6-4f35-bbef-c1ab60449feb', '唐', '["戴月早辭三秀館，遲明初識久華峰。","嵯嵯玉劒寒鋩利，褭褭青蓮翠葉重。","奇狀却疑人畫出，嵐光如爲客添濃。","行春若到五溪上，此處褰帷正面逢。"]', '["戴月早辞三秀館，遲明初識久华峰。","嵯嵯玉劒寒鋩利，褭褭青蓮翠葉重。","奇狀却疑人畫出，嵐光如爲客添濃。","行春若到五溪上，此处褰帷正面逢。"]', '诗', 'shi', '', NULL, '早發靈芝望九華寄杜員外使君 曹汾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('efdd2828-7392-4516-921c-6060a4e02842', '落花', '落花', '2644ad8a-8290-4cd8-bfb7-cb76d3f44c99', '唐', '["春光冉冉歸何處，更向花前把一杯。","盡日問花花不語，爲誰零落爲誰開。"]', '["春光冉冉归何处，更向花前把一杯。","尽日问花花不語，爲誰零落爲誰开。"]', '诗', 'shi', '', NULL, '落花 嚴惲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6aec2d8-b762-419f-905f-8e2029dfc90f', '題籌筆驛', '題籌笔驛', '19a7345c-08ef-45a2-b3c2-a7351427a69b', '唐', '["江東矜割據，鄴下奪孤嫠。","霸畧非匡漢，宏圖欲佐誰。","奏書辭後主，仗劒出全師。","重襲襃斜路，懸開反正旗。","欲將苞有截，必使舉無遺。","沈慮經謀際，揮毫決勝時。","圜觚當分畫，前箸此操持。","山秀扶英氣，川流入妙思。","算成功在彀，運去事終虧。","命屈天方厭，人亡國自隨。","艱難推舊姓，開創極初基。","總歎曾過地，寧探作教資。","若歸新曆數，誰復顧衰危。","報德兼明道，長留識者知。"]', '["江东矜割據，鄴下奪孤嫠。","霸畧非匡漢，宏圖欲佐誰。","奏书辞後主，仗劒出全師。","重襲襃斜路，懸开反正旗。","欲將苞有截，必使舉無遺。","沈慮經謀際，揮毫決勝时。","圜觚當分畫，前箸此操持。","山秀扶英氣，川流入妙思。","算成功在彀，運去事終虧。","命屈天方厭，人亡国自隨。","艱难推旧姓，开創極初基。","總歎曾過地，寧探作教資。","若归新曆數，誰复顧衰危。","報德兼明道，长留識者知。"]', '诗', 'shi', '', NULL, '題籌筆驛 殷潛之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('480467a5-65ca-4ff9-8a00-c3d2a2727f91', '送高遂赴舉', '送高遂赴舉', '9bced07a-90e1-45b4-ae54-6b949fdf22d9', '唐', '["句曲舊宅真，自產日月英。","既涵嶽瀆氣，安無神仙名。","松桂邐迤色，與君相送情。"]', '["句曲旧宅真，自產日月英。","既涵嶽瀆氣，安無神仙名。","松桂邐迤色，與君相送情。"]', '诗', 'shi', '', NULL, '送高遂赴舉 祝元膺 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8150221-6eed-4041-b2f2-c81c2a549452', '寄道友', '寄道友', '9bced07a-90e1-45b4-ae54-6b949fdf22d9', '唐', '["兩頷凝清霜，玉爐焚天香。","爲我延歲華，得入不死鄉。"]', '["兩頷凝清霜，玉爐焚天香。","爲我延歲华，得入不死乡。"]', '诗', 'shi', '', NULL, '寄道友 祝元膺 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('338e07c8-8635-4582-b65d-d2e188a1ca37', '夢仙謠', '梦仙謠', '9bced07a-90e1-45b4-ae54-6b949fdf22d9', '唐', '["蟾蜍夜作青冥燭，螮蝀晴爲碧落梯。","好箇分明天上路，誰教深入武陵溪。"]', '["蟾蜍夜作青冥燭，螮蝀晴爲碧落梯。","好箇分明天上路，誰教深入武陵溪。"]', '诗', 'shi', '', NULL, '夢仙謠 祝元膺 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d18a1dad-aa6d-4f2b-a423-615147b25135', '句', '句', '9bced07a-90e1-45b4-ae54-6b949fdf22d9', '唐', '["霧紋斑似豹，水力健如龍。"]', '["霧紋斑似豹，水力健如龙。"]', '诗', 'shi', '', NULL, '句 祝元膺 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9852645a-b113-4fe7-bf47-1041aeea01a2', '賀鄧璠使君正拜袁州', '賀鄧璠使君正拜袁州', '81129a38-9c50-44de-ba37-d433c5ad962a', '唐', '["六年惠愛及黎甿，大府論功俟陟明。","尺一詔書天上降，二千石祿世間榮。","新添畫戟門增峻，舊躡青雲路轉平。","更待皇恩醒善政，碧油幢到郡齋迎。"]', '["六年惠愛及黎甿，大府論功俟陟明。","尺一詔书天上降，二千石祿世间榮。","新添畫戟门增峻，旧躡青云路轉平。","更待皇恩醒善政，碧油幢到郡斋迎。"]', '诗', 'shi', '', NULL, '賀鄧璠使君正拜袁州 彭蟾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4a38f84-7941-4773-8bd3-e9cd34fc754b', '和嚴惲落花詩', '和嚴惲落花诗', '9e19a8f1-217e-4716-99f8-e40078b1e57f', '唐', '["花落花開人世夢，衰榮閑事且持杯。","春風底事輕搖落，何似從來不要開。"]', '["花落花开人世梦，衰榮闲事且持杯。","春风底事轻搖落，何似從来不要开。"]', '诗', 'shi', '', NULL, '和嚴惲落花詩 王樞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05e59e1f-fd53-47a0-a83c-1fce7862686a', '詠宣律和尚袈裟', '詠宣律和尚袈裟', 'b34fe56e-43e8-4b97-9f4a-e2595e92f67d', '唐', '["共覆三衣中夜寒，披時不鎮尼師壇。","無因蓋得龍宮地，畦裏塵飛葉相殘。"]', '["共覆三衣中夜寒，披时不鎮尼師壇。","無因蓋得龙宮地，畦裏塵飞葉相殘。"]', '诗', 'shi', '', NULL, '詠宣律和尚袈裟 張希復 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf7c54f7-8454-4621-bafd-e6096ae38434', '鶯出谷', '鶯出谷', '94b55e67-d4c6-41a6-9f58-61716b647661', '唐', '["玉律陽和變，時禽羽翮新。","載飛初出谷，一囀已驚人。","拂柳宜煙暖，衝花覺露春。","摶風翻翰疾，向日弄吭頻。","求友心何切，遷喬幸有因。","華林高玉樹，棲託及芳晨。"]', '["玉律陽和变，时禽羽翮新。","載飞初出谷，一囀已驚人。","拂柳宜煙暖，衝花覺露春。","摶风翻翰疾，向日弄吭頻。","求友心何切，遷喬幸有因。","华林高玉樹，棲託及芳晨。"]', '诗', 'shi', '', NULL, '鶯出谷 錢可復 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6cdeee1-e60f-46d3-800c-aa308b59f6f0', '鶯出谷', '鶯出谷', '91574b37-a6ba-4d1a-97a8-a309e759d391', '唐', '["弱柳隨儔匹，遷鶯正及春。","乘風音響遠，映日羽毛新。","已得辭幽谷，還將脫俗塵。","鴛鸞方可慕，燕雀迥無鄰。","遊止知難屈，飜飛在此伸。","一枝如借便，終冀託深仁。"]', '["弱柳隨儔匹，遷鶯正及春。","乘风音响远，映日羽毛新。","已得辞幽谷，還將脫俗塵。","鴛鸾方可慕，燕雀迥無鄰。","游止知难屈，飜飞在此伸。","一枝如借便，終冀託深仁。"]', '诗', 'shi', '', NULL, '鶯出谷 張鷺 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('953d4fe0-ceeb-4707-92dd-3473f0d26424', '鶯出谷', '鶯出谷', 'a4105817-51e8-481a-a551-433523d9f5fb', '唐', '["幸因辭舊谷，從此及芳晨。","欲語如調舌，初飛似畏人。","風調歸影便，日煖吐聲頻。","翔集知無阻，聯綿貴有因。","喜遷喬木近，寧厭對花新。","堪念微禽意，關關也愛春。"]', '["幸因辞旧谷，從此及芳晨。","欲語如調舌，初飞似畏人。","风調归影便，日煖吐声頻。","翔集知無阻，聯綿貴有因。","喜遷喬木近，寧厭对花新。","堪念微禽意，关关也愛春。"]', '诗', 'shi', '', NULL, '鶯出谷 劉莊物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e82ec8c2-9986-4696-946c-13abe1987f04', '題呂食新水閣兼寄南商州郎中', '題呂食新水閣兼寄南商州郎中', 'a123599a-f84c-4f6e-9dba-e14ca9af644f', '唐', '["丹檻初結構，孤高冠清川。","庭臨谷中樹，簷落山上泉。","曉色挂殘月，夜聲雜繁絃。","青春去如水，康樂歸何年。"]', '["丹檻初結構，孤高冠清川。","庭臨谷中樹，簷落山上泉。","晓色挂殘月，夜声杂繁絃。","青春去如水，康乐归何年。"]', '诗', 'shi', '', NULL, '題呂食新水閣兼寄南商州郎中 朱景玄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bcdfe5f3-ba4d-4692-8931-709895dcf1a0', '華山南望春', '华山南望春', 'a123599a-f84c-4f6e-9dba-e14ca9af644f', '唐', '["靈嶽多異狀，巉巉出虛空。","閑雲戀巖壑，起滅蒼翠中。","皓氣澄野水，神光秘瓊宮。","鶴巢前林雪，瀑落滿澗風。","春盡花未發，川迴路難窮。","何因著山屐，鹿跡尋羊公。"]', '["靈嶽多異狀，巉巉出虛空。","闲云戀巖壑，起滅蒼翠中。","皓氣澄野水，神光秘瓊宮。","鹤巢前林雪，瀑落满澗风。","春尽花未發，川迴路难窮。","何因著山屐，鹿跡尋羊公。"]', '诗', 'shi', '', NULL, '華山南望春 朱景玄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0227fccd-0a08-4a4b-a2de-aa9d2969c1b2', '水閣', '水閣', 'a123599a-f84c-4f6e-9dba-e14ca9af644f', '唐', '["樓居半池上，澄影共相空。","謝守題詩處，蓮開淨碧中。"]', '["楼居半池上，澄影共相空。","謝守題诗处，蓮开淨碧中。"]', '诗', 'shi', '', NULL, '水閣 朱景玄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('094c422e-ea03-42cd-baad-1da58efc0397', '迎風亭', '迎风亭', 'a123599a-f84c-4f6e-9dba-e14ca9af644f', '唐', '["山雨留清氣，溪飆送早涼。","時回石門步，階下碧雲光。"]', '["山雨留清氣，溪飆送早涼。","时回石门步，階下碧云光。"]', '诗', 'shi', '', NULL, '迎風亭 朱景玄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b1ef4ca-410a-4f20-b758-33faf4faf334', '雙櫧亭', '雙櫧亭', 'a123599a-f84c-4f6e-9dba-e14ca9af644f', '唐', '["連簷對雙樹，冬翠夏無塵。","未肯慙桃李，成陰不待春。"]', '["連簷对雙樹，冬翠夏無塵。","未肯慙桃李，成陰不待春。"]', '诗', 'shi', '', NULL, '雙櫧亭 朱景玄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6b6c7d1-b222-4235-bb67-f75ac04393a6', '蓮亭', '蓮亭', 'a123599a-f84c-4f6e-9dba-e14ca9af644f', '唐', '["回塘最幽處，拍水小亭開。","莫怪闌干溼，鵁鶄夜宿來。"]', '["回塘最幽处，拍水小亭开。","莫怪闌干溼，鵁鶄夜宿来。"]', '诗', 'shi', '', NULL, '蓮亭 朱景玄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51ad6094-adc2-4a1d-b5cd-986bb04e2032', '中峯亭', '中峯亭', 'a123599a-f84c-4f6e-9dba-e14ca9af644f', '唐', '["中峯上翠微，窗曉早霞飛。","幾引登山屐，春風踏雪歸。"]', '["中峯上翠微，窗晓早霞飞。","幾引登山屐，春风踏雪归。"]', '诗', 'shi', '', NULL, '中峯亭 朱景玄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c27bf3c-f7c5-41ec-a0f8-86dc7739bfdd', '飛雲亭', '飞云亭', 'a123599a-f84c-4f6e-9dba-e14ca9af644f', '唐', '["上結孤圓頂，飛軒出泰清。","有時迷處所，梁棟曉雲生。"]', '["上結孤圓頂，飞軒出泰清。","有时迷处所，梁棟晓云生。"]', '诗', 'shi', '', NULL, '飛雲亭 朱景玄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('efd5b98e-0945-4545-8249-c0e0e10a89e4', '四望亭', '四望亭', 'a123599a-f84c-4f6e-9dba-e14ca9af644f', '唐', '["高亭羣峰首，四面俯晴川。","每見晨光曉，階前萬井煙。"]', '["高亭羣峰首，四面俯晴川。","每见晨光晓，階前万井煙。"]', '诗', 'shi', '', NULL, '四望亭 朱景玄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('403c8ada-4a05-4ffc-9b9d-be7f2077f8fb', '望蓮臺', '望蓮台', 'a123599a-f84c-4f6e-9dba-e14ca9af644f', '唐', '["秋臺好登望，菡萏發清池。","半似紅顏醉，凌波欲暮時。"]', '["秋台好登望，菡萏發清池。","半似紅顏醉，凌波欲暮时。"]', '诗', 'shi', '', NULL, '望蓮臺 朱景玄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e932f96f-0c1b-4526-a14b-420a3368969c', '茶亭', '茶亭', 'a123599a-f84c-4f6e-9dba-e14ca9af644f', '唐', '["靜得塵埃外，茶芳小華山。","此亭真寂寞，世路少人閑。"]', '["静得塵埃外，茶芳小华山。","此亭真寂寞，世路少人闲。"]', '诗', 'shi', '', NULL, '茶亭 朱景玄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b18f9cc2-c00f-4360-be22-5239aaf9350a', '宿新安村步', '宿新安村步', 'a123599a-f84c-4f6e-9dba-e14ca9af644f', '唐', '["淅淅寒流漲淺沙，月明空渚徧蘆花。","離人偶宿孤村下，永夜聞砧一兩家。"]', '["淅淅寒流漲淺沙，月明空渚徧蘆花。","離人偶宿孤村下，永夜闻砧一兩家。"]', '诗', 'shi', '', NULL, '宿新安村步 朱景玄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7dfaefcc-d03b-49a3-81a1-a4b338a3f06a', '遠聞本郡行春到舊山二首 一', '远闻本郡行春到旧山二首 一', 'a123599a-f84c-4f6e-9dba-e14ca9af644f', '唐', '["一身從宦留京邑，五馬遙聞到舊山。","已領煙霞光野徑，深慚老幼候柴關。"]', '["一身從宦留京邑，五马遙闻到旧山。","已領煙霞光野徑，深慚老幼候柴关。"]', '诗', 'shi', '', NULL, '遠聞本郡行春到舊山二首 一 朱景玄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a889c4f3-38d2-45f9-8c7a-29931e72d844', '遠聞本郡行春到舊山二首 二', '远闻本郡行春到旧山二首 二', 'a123599a-f84c-4f6e-9dba-e14ca9af644f', '唐', '["清風借響松筠外，畫隼停暉水石間。","定掩溪名在圖傳，共知軒蓋此登攀。"]', '["清风借响松筠外，畫隼停暉水石间。","定掩溪名在圖傳，共知軒蓋此登攀。"]', '诗', 'shi', '', NULL, '遠聞本郡行春到舊山二首 二 朱景玄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3efca3db-0930-42db-8ec5-f3006eb41351', '和崔使君臨發不得觀積雪', '和崔使君臨發不得观積雪', 'a123599a-f84c-4f6e-9dba-e14ca9af644f', '唐', '["貧居稍與池塘近，旬日軒車不降來。","一樹瓊花空有待，曉風看落滿青苔。"]', '["貧居稍與池塘近，旬日軒车不降来。","一樹瓊花空有待，晓风看落满青苔。"]', '诗', 'shi', '', NULL, '和崔使君臨發不得觀積雪 朱景玄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79e71022-c513-4c45-91af-bcebd74af647', '句', '句', 'a123599a-f84c-4f6e-9dba-e14ca9af644f', '唐', '["塞鴻先秋去，邊草入夏生。"]', '["塞鴻先秋去，邊草入夏生。"]', '诗', 'shi', '', NULL, '句 朱景玄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de245af8-9524-42fd-b981-25f5751f55ea', '別青州妓段東美 一', '別青州妓段东美 一', '8a30382a-ecf3-408c-8686-34d634386671', '唐', '["經年郵驛許安棲，一會他鄉別恨迷。","今日海帆飄萬里，不堪腸斷對含啼。"]', '["經年郵驛許安棲，一會他乡別恨迷。","今日海帆飄万里，不堪腸斷对含啼。"]', '诗', 'shi', '', NULL, '別青州妓段東美 一 薛宜僚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c6b2b9c-7570-4a5a-8635-1857e0a01c9b', '別青州妓段東美 二', '別青州妓段东美 二', '8a30382a-ecf3-408c-8686-34d634386671', '唐', '["阿母桃花方似錦，王孫草色正如煙。","不須更向滄溟望，惆悵歡情恰一年。"]', '["阿母桃花方似錦，王孫草色正如煙。","不須更向滄溟望，惆悵歡情恰一年。"]', '诗', 'shi', '', NULL, '別青州妓段東美 二 薛宜僚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08bbde96-16df-418c-a1be-cbf73918bd37', '詠韋臯', '詠韋臯', '4a4caeae-ec4c-4ce9-9cf3-136a1ee50695', '唐', '["宣父從周又適秦，昔賢誰少出風塵。","當時甚訝張延賞，不識韋臯是貴人。"]', '["宣父從周又適秦，昔賢誰少出风塵。","當时甚訝張延賞，不識韋臯是貴人。"]', '诗', 'shi', '', NULL, '詠韋臯 郭圓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f0946e8-326e-4554-8826-8ecbc07bcc86', '進宣宗收復河湟詩', '進宣宗收复河湟诗', 'd94febf1-b085-44a1-bb53-7fd763a83007', '唐', '["邊陲萬里注恩波，宇宙羣芳洽凱歌。","右地名王爭解辮，遠方戎壘盡投戈。","煙塵永息三秋戍，瑞氣遙清九折河。","共遇聖明千載運，更觀俗阜與時和。"]', '["邊陲万里注恩波，宇宙羣芳洽凱歌。","右地名王爭解辮，远方戎壘尽投戈。","煙塵永息三秋戍，瑞氣遙清九折河。","共遇聖明千載運，更观俗阜與时和。"]', '诗', 'shi', '', NULL, '進宣宗收復河湟詩 崔鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13e56361-c239-4005-9b7b-fd2ee27aa334', '詠架上鷹', '詠架上鷹', 'd94febf1-b085-44a1-bb53-7fd763a83007', '唐', '["天邊心膽架頭身，欲擬飛騰未有因。","萬里碧霄終一去，不知誰是解絛人。"]', '["天邊心膽架头身，欲擬飞腾未有因。","万里碧霄終一去，不知誰是解絛人。"]', '诗', 'shi', '', NULL, '詠架上鷹 崔鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13045d25-13a5-44a7-a4e9-be6d53718f6e', '越亭二十韻', '越亭二十韻', '7360fd02-a344-471d-b835-852bd81e2098', '唐', '["乏才叨八使，徇祿非三顧。","南服頒詔條，東林證迷誤。","未聞述職效，偶脫囂煩趣。","激水濬㘭塘，緣崖欹磴步。","西巖煥朝旭，深壑囊宿霧。","影氣爽衣巾，涼颸輕杖履。","臨高神慮寂，遠眺川原布。","孤帆逗汀煙，飜鵶集江樹。","獨探洞府靜，怳若偓佺遇。","一瞬契真宗，百年成妄故。","孱顏石戶啓，杳靄溪雲度。","松籟韻宮商，鴛甍勢翔遡。","津梁危彴架，濟物虛舟渡。","環流馳羽觴，金英妬妝嫮。","笳吟寒壘迥，鳥噪空山暮。","悵望麋鹿心，低迴車馬路。","懸冠謝陶令，褫珮懷疏傅。","遐想蛻纓緌，徒慙卹襦袴。","福盈禍之倚，權勝道所惡。","何必棲禪關，無言自冥悟。"]', '["乏才叨八使，徇祿非三顧。","南服頒詔條，东林證迷誤。","未闻述職效，偶脫囂煩趣。","激水濬㘭塘，緣崖欹磴步。","西巖煥朝旭，深壑囊宿霧。","影氣爽衣巾，涼颸轻杖履。","臨高神慮寂，远眺川原布。","孤帆逗汀煙，飜鵶集江樹。","独探洞府静，怳若偓佺遇。","一瞬契真宗，百年成妄故。","孱顏石戶啓，杳靄溪云度。","松籟韻宮商，鴛甍勢翔遡。","津梁危彴架，濟物虛舟渡。","环流驰羽觴，金英妬妝嫮。","笳吟寒壘迥，鸟噪空山暮。","悵望麋鹿心，低迴车马路。","懸冠謝陶令，褫珮懷疏傅。","遐想蛻纓緌，徒慙卹襦袴。","福盈禍之倚，權勝道所惡。","何必棲禪关，無言自冥悟。"]', '诗', 'shi', '', NULL, '越亭二十韻 元晦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2c7731d-02ac-411c-859b-173c3e270460', '除浙東留題桂郡林亭', '除浙东留題桂郡林亭', '7360fd02-a344-471d-b835-852bd81e2098', '唐', '["紫泥遠自金鑾降，朱斾翻馳鏡水頭。","陶令風光偏畏夜，子牟衰鬢暗驚秋。","西隣月色何時見，南國春光豈再游。","莫遣豔歌催客醉，不堪回首翠蛾愁。"]', '["紫泥远自金鑾降，朱斾翻驰镜水头。","陶令风光偏畏夜，子牟衰鬢暗驚秋。","西隣月色何时见，南国春光豈再游。","莫遣豔歌催客醉，不堪回首翠蛾愁。"]', '诗', 'shi', '', NULL, '除浙東留題桂郡林亭 元晦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7645f905-1a7f-4770-90cc-b8e49bf15d60', '句', '句', '7360fd02-a344-471d-b835-852bd81e2098', '唐', '["石靜如開鏡，山高若聳蓮。","筍竿抽玉管，花蔓綴金鈿。"]', '["石静如开镜，山高若聳蓮。","筍竿抽玉管，花蔓綴金鈿。"]', '诗', 'shi', '', NULL, '句 元晦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88a09882-7ba0-4d96-9527-f72370b41839', '和元常侍除浙東留題', '和元常侍除浙东留題', '61f7eae4-a0db-484e-89b9-72fafbb477e5', '唐', '["謝安致理逾三載，黃霸清聲徹九重。","猶輟珮環歸鳳闕，且將仁政到稽峯。","林間立馬羅千騎，池上開筵醉一鍾。","共喜甘棠有新詠，獨慚霜鬢又攀龍。"]', '["謝安致理逾三載，黄霸清声徹九重。","猶輟珮环归鳳闕，且將仁政到稽峯。","林间立马羅千騎，池上开筵醉一鍾。","共喜甘棠有新詠，独慚霜鬢又攀龙。"]', '诗', 'shi', '', NULL, '和元常侍除浙東留題 路貫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33a668cd-706d-4c0d-9228-64c0c7aa533a', '贈鞏疇', '贈鞏疇', '76eb2f1a-1acc-4ffd-a0a1-5d194f5be1c5', '唐', '["密雪松桂寒，書窗導餘清。","風憾冰玉碎，階前琴磬聲。","榻靜几硯潔，帙散縑緗明。","高論展僧肇，精言資鞏生。","立意加玄虛，析理分縱橫。","萬化悉在我，一物安能驚。","江海何所動，丘山常自平。","遲速不相閡，後先徒起爭。","鏡照分妍醜，秤稱分重輕。","顏容寧入鑑，銖兩豈關衡。","蘊微道超忽，剖鐙音泠泠。","紙上掣牢鍵，舌端搖利兵。","圓澈保直性，客塵排妄情。","有住即非住，無行即是行。","疏越捨朱絃，哇淫鄙秦箏。","淡薄貴無味，羊斟慙大羹。","洪遠包乾坤，幽窅潛沈冥。","罔煩跬步舉，頓達萬里程。","廬遠尚莫曉，隱留曾誤聽。","直須持妙說，共詣毗耶城。"]', '["密雪松桂寒，书窗導餘清。","风憾冰玉碎，階前琴磬声。","榻静几硯潔，帙散縑緗明。","高論展僧肇，精言資鞏生。","立意加玄虛，析理分縱橫。","万化悉在我，一物安能驚。","江海何所动，丘山常自平。","遲速不相閡，後先徒起爭。","镜照分妍醜，秤稱分重轻。","顏容寧入鑑，銖兩豈关衡。","蘊微道超忽，剖鐙音泠泠。","紙上掣牢鍵，舌端搖利兵。","圓澈保直性，客塵排妄情。","有住即非住，無行即是行。","疏越捨朱絃，哇淫鄙秦箏。","淡薄貴無味，羊斟慙大羹。","洪远包乾坤，幽窅潛沈冥。","罔煩跬步舉，頓達万里程。","廬远尚莫晓，隐留曾誤听。","直須持妙说，共詣毗耶城。"]', '诗', 'shi', '', NULL, '贈鞏疇 鄭薰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('772ad2f8-114d-4124-bc6b-b2f2bf7b1832', '句', '句', '76eb2f1a-1acc-4ffd-a0a1-5d194f5be1c5', '唐', '["項斯逢水部，誰道不關情。"]', '["項斯逢水部，誰道不关情。"]', '诗', 'shi', '', NULL, '句 鄭薰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39d6c425-ebb3-4d3a-9d6b-e6e3b06f4faa', '鑷白曲', '鑷白曲', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["去年鑷白鬢，境裏猶堪認年少。","今年鑷白髮，兩眼昏昏手戰跳。","滿酌濃酹假顏色，顏色不揚翻自笑。","少年曾讀古人書，本期獨善安有餘。","雖蓋長安一片瓦，未遑卒歲容寧居。","前年依亞成都府，月請俸緍六十五。","妻兒骨肉愁欲來，偏梁閣道歸得否。","長安六月塵亙天，池塘鼎沸林欲燃。","合家慟哭出門送，獨驅匹馬陵山巔。","到官只是推誠信，終日兢兢幸無恡。","丞相知憐爲小心，忽然奏佩專城印。","專城俸入一倍多，況兼職祿霜峨峨。","山妻稚女悉迎到，時列綠罇酣酒歌。","醉來便向罇前倒，風月滿頭絲皓皓。","雖然減得闔門憂，又加去國五年老。","五年老，知奈何，來日少，去日多。","金鎚鎚碎黃金鑷，更唱罇前老去歌。"]', '["去年鑷白鬢，境裏猶堪認年少。","今年鑷白髮，兩眼昏昏手戰跳。","满酌濃酹假顏色，顏色不揚翻自笑。","少年曾读古人书，本期独善安有餘。","雖蓋长安一片瓦，未遑卒歲容寧居。","前年依亞成都府，月請俸緍六十五。","妻兒骨肉愁欲来，偏梁閣道归得否。","长安六月塵亙天，池塘鼎沸林欲燃。","合家慟哭出门送，独驱匹马陵山巔。","到官只是推誠信，終日兢兢幸無恡。","丞相知怜爲小心，忽然奏佩專城印。","專城俸入一倍多，況兼職祿霜峨峨。","山妻稚女悉迎到，时列綠罇酣酒歌。","醉来便向罇前倒，风月满头絲皓皓。","雖然減得闔门憂，又加去国五年老。","五年老，知奈何，来日少，去日多。","金鎚鎚碎黄金鑷，更唱罇前老去歌。"]', '诗', 'shi', '', NULL, '鑷白曲 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41200c91-3236-48c1-b23b-84b0695b0bc9', '君不見', '君不见', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["君不見，馬侍中，氣吞河朔稱英雄。","君不見，韋太尉，二十年前鎮蜀地。","一朝冥漠歸下泉，功業勝名兩憔悴。","奉誠園裏篙棘生，長興街南沙路平。","當時帶礪在何處，今日子孫無地耕。","或聞羈旅甘常調，簿尉文參各天表。","清明縱便天使來，一把紙錢風樹杪。","碑文半缺碑堂摧，祁連塚象狐兔開。","野花似雪落何處，棠棃樹下香風來。","馬侍中，韋太尉，盛去衰來片時事。","人生倏忽一夢中，何必深深固權位。"]', '["君不见，马侍中，氣吞河朔稱英雄。","君不见，韋太尉，二十年前鎮蜀地。","一朝冥漠归下泉，功業勝名兩憔悴。","奉誠园裏篙棘生，长兴街南沙路平。","當时带礪在何处，今日子孫無地耕。","或闻羈旅甘常調，簿尉文參各天表。","清明縱便天使来，一把紙錢风樹杪。","碑文半缺碑堂摧，祁連塚象狐兔开。","野花似雪落何处，棠棃樹下香风来。","马侍中，韋太尉，盛去衰来片时事。","人生倏忽一梦中，何必深深固權位。"]', '诗', 'shi', '', NULL, '君不見 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b56332c5-ea25-4e78-8f08-489da70fb0df', '老去也', '老去也', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["惆悵人生不滿百，一事無成頭雪白。","迴看幼累與老妻，俱是途中遠行客。","匣中舊鏡照膽明，昔曾見我髭未生。","朝巾暮櫛不自省，老皮皴皺文縱橫。","合掌髻子蒜許大，此日方知非是我。","暗數七旬能幾何，不覺中腸熱如火。","老去也，爭奈何，敲酒盞，唱短歌。","短歌未竟日已沒，月映西南庭樹柯。"]', '["惆悵人生不满百，一事無成头雪白。","迴看幼累與老妻，俱是途中远行客。","匣中旧镜照膽明，昔曾见我髭未生。","朝巾暮櫛不自省，老皮皴皺文縱橫。","合掌髻子蒜許大，此日方知非是我。","暗數七旬能幾何，不覺中腸熱如火。","老去也，爭奈何，敲酒盞，唱短歌。","短歌未竟日已沒，月映西南庭樹柯。"]', '诗', 'shi', '', NULL, '老去也 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06df66db-1a03-4b81-8be2-f0ab109bc66e', '追昔行', '追昔行', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["朝光如飛猶尚可，暮更如箭不容臥。","犍爲穿城更漏頻，一一皆從枕邊過。","一夕凡幾更，一更凡幾聲。","青春枉向鏡中老，白髮虛從愁裏生。","曾窺帝里東鄰女，自比桃花鏡中許。","一朝嫁得征戌兒，荷戈千里防秋去。","去時只作旦暮期，別後生死俱不知。","風驚粉色入蟬鬢，愁送鏡花潛墮枝。","前年因出長安陌，見一女人頭雪白。","日中扶杖憇樹陰，髣髴形容認相識。","向予吁嗟還獨語，曾與君家鄰舍住。","當時妾嫁與征人，幾向牆頭誚夫主。","花開葉洛何推遷，屈指數當三十年。","眉頭薤葉同枯葉，琴上朱弦成斷弦。","嫁時寶鏡依然在，鵲影菱花滿光彩。","夢裏長嗟離別多，愁中不覺顏容改。","歎息人生能幾何，喜君顏貌未蹉跎。","因君下馬重相顧，請奏青門腸斷歌。"]', '["朝光如飞猶尚可，暮更如箭不容臥。","犍爲穿城更漏頻，一一皆從枕邊過。","一夕凡幾更，一更凡幾声。","青春枉向镜中老，白髮虛從愁裏生。","曾窺帝里东鄰女，自比桃花镜中許。","一朝嫁得征戌兒，荷戈千里防秋去。","去时只作旦暮期，別後生死俱不知。","风驚粉色入蟬鬢，愁送镜花潛墮枝。","前年因出长安陌，见一女人头雪白。","日中扶杖憇樹陰，髣髴形容認相識。","向予吁嗟還独語，曾與君家鄰舍住。","當时妾嫁與征人，幾向牆头誚夫主。","花开葉洛何推遷，屈指數當三十年。","眉头薤葉同枯葉，琴上朱弦成斷弦。","嫁时寶镜依然在，鵲影菱花满光彩。","梦裏长嗟離別多，愁中不覺顏容改。","歎息人生能幾何，喜君顏貌未蹉跎。","因君下马重相顧，請奏青门腸斷歌。"]', '诗', 'shi', '', NULL, '追昔行 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45775c39-7411-4d7d-bbb5-3355b6176989', '醉春風', '醉春风', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["去年春似今年春，依舊野花愁殺人。","犍爲縣裏古城上，開是好花飛是塵。","戲蝶狂蜂相往返，一枝花上聲千萬。","時節先從暖處開，北枝未發南枝晚。","江城太守鬚髯蒼，忽然置酒開華堂。","歌兒舞女亦隨後，暫醉始知天地長。","頃年曾作東周掾，同舍尋春屢開宴。","斗門亭上柳如絲，洛水橋邊月如練。","洛陽風俗不禁街，騎馬夜歸香滿懷。","坐客爭吟雲碧句，美人醉贈珊瑚釵。","日往月來何草草，今年又校三年老。","槽中駿馬不能騎，惆悵落花開滿道。","爲報時人知不知，看花對酒定無疑。","君看野外孤墳下，石羊石馬是誰家。"]', '["去年春似今年春，依旧野花愁殺人。","犍爲縣裏古城上，开是好花飞是塵。","戲蝶狂蜂相往返，一枝花上声千万。","时節先從暖处开，北枝未發南枝晚。","江城太守鬚髯蒼，忽然置酒开华堂。","歌兒舞女亦隨後，暫醉始知天地长。","頃年曾作东周掾，同舍尋春屢开宴。","斗门亭上柳如絲，洛水橋邊月如練。","洛陽风俗不禁街，騎马夜归香满懷。","坐客爭吟云碧句，美人醉贈珊瑚釵。","日往月来何草草，今年又校三年老。","槽中駿马不能騎，惆悵落花开满道。","爲報时人知不知，看花对酒定無疑。","君看野外孤墳下，石羊石马是誰家。"]', '诗', 'shi', '', NULL, '醉春風 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74f58e76-5109-410a-b85f-6c03da624eba', '鄰相反行', '鄰相反行', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["東家有兒年十五，只向田園獨辛苦。","夜開溝水遶稻田，曉叱耕牛墾塉土。","西家有兒纔弱齡，儀容清峭雲鶴形。","涉書獵史無早暮，坐期朱紫如拾青。","東家西家兩相誚，西兒笑東東又笑。","西云養志與榮名，彼此相非不同調。","東家自云雖辛苦，躬耕早暮及所親。","男舂女爨二十載，堂上未爲衰老人。","朝機暮織還充體，餘者到兄還及弟。","春秋伏臘長在家，不許妻奴暫違禮。","爾今二十方讀書，十年取第三十餘。","往來途路長離別，幾人便得昇公車。","縱令得官身須老，銜恤終天向誰道。","百年骨肉歸下泉，萬里枌榆長秋草。","我今躬耕奉所天，耘鋤刈獲當少年。","面上笑添今日喜，肩頭薪續廚中煙。","縱使此身頭雪白，又有兒孫還稼穡。","家藏一卷古孝經，世世相傳皆得力。","爲報西家知不知，何須謾笑東家兒。","生前不得供甘滑，歿後揚名徒爾爲。"]', '["东家有兒年十五，只向田园独辛苦。","夜开溝水遶稻田，晓叱耕牛墾塉土。","西家有兒纔弱齡，儀容清峭云鹤形。","涉书獵史無早暮，坐期朱紫如拾青。","东家西家兩相誚，西兒笑东东又笑。","西云養志與榮名，彼此相非不同調。","东家自云雖辛苦，躬耕早暮及所親。","男舂女爨二十載，堂上未爲衰老人。","朝機暮织還充體，餘者到兄還及弟。","春秋伏臘长在家，不許妻奴暫違禮。","爾今二十方读书，十年取第三十餘。","往来途路长離別，幾人便得昇公车。","縱令得官身須老，銜恤終天向誰道。","百年骨肉归下泉，万里枌榆长秋草。","我今躬耕奉所天，耘鋤刈獲當少年。","面上笑添今日喜，肩头薪續廚中煙。","縱使此身头雪白，又有兒孫還稼穡。","家藏一卷古孝經，世世相傳皆得力。","爲報西家知不知，何須謾笑东家兒。","生前不得供甘滑，歿後揚名徒爾爲。"]', '诗', 'shi', '', NULL, '鄰相反行 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9a971df-d466-4eb4-8dd6-c0ca17104ceb', '靈臺家兄古鏡歌', '靈台家兄古镜歌', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["一尺圓潭深黑色，篆文如絲人不識。","耕夫云住赫連城，赫連城下親耕得。","鏡上磨瑩一月餘，日中漸見菱花舒。","金膏洗拭鉎澀盡，黑雲吐出新蟾蜍。","人言此是千年物，百鬼聞之形暗慄。","玉匣曾經龍照來，豈宜更鑒農夫質。","有時霹靂半夜驚，窗中飛電如晦明。","盤龍鱗脹玉匣溢，牙爪觸風時有聲。","耕夫不解珍靈異，翻懼赫連神作祟。","十千賣與靈臺兄，百丈靈湫坐中至。","溢匣水色如玉傾，兒童不敢窺泓澄。","寒光照人近不得，坐愁雷電湫中生。","吾兄吾兄須愛惜，將來慎勿虛拋擲。","興雲致雨會有時，莫譴紅牀穢靈跡。"]', '["一尺圓潭深黑色，篆文如絲人不識。","耕夫云住赫連城，赫連城下親耕得。","镜上磨瑩一月餘，日中漸见菱花舒。","金膏洗拭鉎澀尽，黑云吐出新蟾蜍。","人言此是千年物，百鬼闻之形暗慄。","玉匣曾經龙照来，豈宜更鑒農夫質。","有时霹靂半夜驚，窗中飞電如晦明。","盤龙鱗脹玉匣溢，牙爪觸风时有声。","耕夫不解珍靈異，翻懼赫連神作祟。","十千賣與靈台兄，百丈靈湫坐中至。","溢匣水色如玉傾，兒童不敢窺泓澄。","寒光照人近不得，坐愁雷電湫中生。","吾兄吾兄須愛惜，將来慎勿虛拋擲。","兴云致雨會有时，莫譴紅牀穢靈跡。"]', '诗', 'shi', '', NULL, '靈臺家兄古鏡歌 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0944f9f-23d3-4187-9968-bf7a253903dd', '觀競渡', '观競渡', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["三月三日天清明，楊花繞江啼曉鶯。","使君未出郡齋內，江上已聞齊和聲。","使君出時皆有引，馬前已被紅旗陣。","兩岸羅衣破鼻香，銀釵照日如霜刃。","鼓聲三下紅旗開，兩龍躍出浮水來。","擢影斡波飛萬劒，鼓聲劈浪鳴千雷。","雷聲衝急波相近，兩龍望標目如瞬。","江上人呼霹靂聲，竿頭綵挂虹霓暈。","前船搶水已得標，後船失勢空揮橈。","瘡眉血首爭不定，輸岸一朋心似燒。","只將標示輸贏賞，兩岸十舟五來往。","須臾戲罷各東西，競脫文身請書上。","吾今細觀競渡兒，何殊當路權相持。","不思得所各休去，會到摧舟折楫時。"]', '["三月三日天清明，楊花繞江啼晓鶯。","使君未出郡斋內，江上已闻齊和声。","使君出时皆有引，马前已被紅旗陣。","兩岸羅衣破鼻香，銀釵照日如霜刃。","鼓声三下紅旗开，兩龙躍出浮水来。","擢影斡波飞万劒，鼓声劈浪鳴千雷。","雷声衝急波相近，兩龙望標目如瞬。","江上人呼霹靂声，竿头綵挂虹霓暈。","前船搶水已得標，後船失勢空揮橈。","瘡眉血首爭不定，輸岸一朋心似燒。","只將標示輸贏賞，兩岸十舟五来往。","須臾戲罷各东西，競脫文身請书上。","吾今細观競渡兒，何殊當路權相持。","不思得所各休去，會到摧舟折楫时。"]', '诗', 'shi', '', NULL, '觀競渡 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5dffd51-debc-40e9-88ca-3289eda3e328', '酬牛秀才登樓見示', '酬牛秀才登楼见示', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["旅館再經秋，心煩嬾上樓。","年光同過隙，人事且隨流。","骨肉憑書問，鄉關託夢遊。","所嗟山郡酒，傾盡只添憂。"]', '["旅館再經秋，心煩嬾上楼。","年光同過隙，人事且隨流。","骨肉憑书问，乡关託梦游。","所嗟山郡酒，傾尽只添憂。"]', '诗', 'shi', '', NULL, '酬牛秀才登樓見示 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83b107b3-f528-4431-9517-98be25067597', '夏夜宴明月湖', '夏夜宴明月湖', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["夏夜宴南湖，琴觴興不孤。","月搖天上桂，星泛浦中珠。","助照螢隨舫，添盤筍迸廚。","聖朝思靜默，堪守谷中愚。"]', '["夏夜宴南湖，琴觴兴不孤。","月搖天上桂，星泛浦中珠。","助照螢隨舫，添盤筍迸廚。","聖朝思静默，堪守谷中愚。"]', '诗', 'shi', '', NULL, '夏夜宴明月湖 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c717d4bc-574c-4c04-a9a0-5292fad95c82', '大水', '大水', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["暴雨逐驚雷，從風忽驟來。","浪驅三島至，江拆二儀開。","勢恐圓樞折，聲疑厚軸摧。","冥心問元化，天眼幾時回。"]', '["暴雨逐驚雷，從风忽驟来。","浪驱三島至，江拆二儀开。","勢恐圓樞折，声疑厚軸摧。","冥心问元化，天眼幾时回。"]', '诗', 'shi', '', NULL, '大水 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d297092f-106d-4103-b3b2-32ffaca6ea56', '席上酬東川嚴中丞敘舊見贈', '席上酬东川嚴中丞敘旧见贈', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["昔記披雲日，今逾二十年。","聲名俱是夢，恩舊半歸泉。","朱紱慙衰齒，紅妝慘別筵。","離歌正淒切，休更促危弦。"]', '["昔記披云日，今逾二十年。","声名俱是梦，恩旧半归泉。","朱紱慙衰齒，紅妝慘別筵。","離歌正淒切，休更促危弦。"]', '诗', 'shi', '', NULL, '席上酬東川嚴中丞敘舊見贈 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d7985f7-339f-44be-843e-e5f422fbd804', '禁火', '禁火', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["日日冒煙塵，忽忽禁火辰。","塞榆關水濕，邊草賊迴春。","歲月傷風邁，瘡痍念苦辛。","沙中看白骨，腸斷故鄉人。"]', '["日日冒煙塵，忽忽禁火辰。","塞榆关水濕，邊草賊迴春。","歲月傷风邁，瘡痍念苦辛。","沙中看白骨，腸斷故乡人。"]', '诗', 'shi', '', NULL, '禁火 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5799fb7-6f39-47fc-977c-1fb96fd2692e', '詠柳', '詠柳', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["弱植驚風急自傷，暮來翻遣思悠揚。","曾飄紫陌隨高下，敢拂朱闌競短長。","縈砌乍飛還乍舞，撲池如雪又如霜。","莫令歧路頻攀折，漸擬垂陰到畫堂。"]', '["弱植驚风急自傷，暮来翻遣思悠揚。","曾飄紫陌隨高下，敢拂朱闌競短长。","縈砌乍飞還乍舞，撲池如雪又如霜。","莫令歧路頻攀折，漸擬垂陰到畫堂。"]', '诗', 'shi', '', NULL, '詠柳 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8d102c4-b25b-412f-afce-35db35c339d9', '宮詞', '宮词', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["十二樓中盡曉妝，望仙樓上望君王。","鎖銜金獸連環冷，水滴銅龍晝漏長。","雲髻罷梳還對鏡，羅衣欲換更添香。","遙窺正殿簾開處，袍袴宮人掃御牀。"]', '["十二楼中尽晓妝，望仙楼上望君王。","鎖銜金獸連环冷，水滴銅龙晝漏长。","云髻罷梳還对镜，羅衣欲換更添香。","遙窺正殿簾开处，袍袴宮人掃御牀。"]', '诗', 'shi', '', NULL, '宮詞 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84754054-2454-4cd3-9e91-ca20bf4f857a', '長安春日', '长安春日', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["窮途日日困泥沙，上苑年年好物華。","荆棘不當車馬道，管弦長奏綺羅家。","王孫草上悠揚蝶，少女風前爛熳花。","嬾出任從遊子笑，入門還是舊生涯。"]', '["窮途日日困泥沙，上苑年年好物华。","荆棘不當车马道，管弦长奏綺羅家。","王孫草上悠揚蝶，少女风前爛熳花。","嬾出任從游子笑，入门還是旧生涯。"]', '诗', 'shi', '', NULL, '長安春日 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80277dbc-3144-475e-a8ec-e73c55eb0620', '韋壽博書齋', '韋壽博书斋', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["玄晏先生已白頭，不隨鵷鷺狎羣鷗。","元卿謝免開三逕，平仲朝歸臥一裘。","醉後獨知殷甲子，病來猶作晉春秋。","塵纓未濯今如此，野水無情處處流。"]', '["玄晏先生已白头，不隨鵷鷺狎羣鷗。","元卿謝免开三逕，平仲朝归臥一裘。","醉後独知殷甲子，病来猶作晉春秋。","塵纓未濯今如此，野水無情处处流。"]', '诗', 'shi', '', NULL, '韋壽博書齋 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db6aea33-c0f0-48f2-bf57-45378d3ed956', '潼關河亭', '潼关河亭', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["重岡如抱嶽如蹲，屈曲秦川勢自尊。","天地併功開帝宅，山河相湊束龍門。","櫓聲嘔軋中流渡，柳色微茫遠岸村。","滿眼波濤終古事，年來惆悵與誰論。"]', '["重岡如抱嶽如蹲，屈曲秦川勢自尊。","天地併功开帝宅，山河相湊束龙门。","櫓声嘔軋中流渡，柳色微茫远岸村。","满眼波濤終古事，年来惆悵與誰論。"]', '诗', 'shi', '', NULL, '潼關河亭 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6890770d-3fbf-4b79-95c6-7d34f4557fc5', '送衢州崔員外', '送衢州崔員外', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["笑分銅虎別京師，嶺下山川想到時。","紅樹暗藏殷浩宅，綠蘿深覆偃王祠。","風茅向暖抽書帶，露竹迎風舞釣絲。","休指巖西數歸日，知君已負白雲期。"]', '["笑分銅虎別京師，嶺下山川想到时。","紅樹暗藏殷浩宅，綠蘿深覆偃王祠。","风茅向暖抽书带，露竹迎风舞釣絲。","休指巖西數归日，知君已負白云期。"]', '诗', 'shi', '', NULL, '送衢州崔員外 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74b46808-0fd0-4887-85d7-a1a7e9a4ba9e', '開元後樂', '开元後乐', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["莫奏開元舊樂章，樂中歌曲斷人腸。","鄶王玉笛三更咽，虢國金車十里香。","一自犬戎生蘇北，便從征戰老汾陽。","中原駿馬搜求盡，沙苑年來草又芳。"]', '["莫奏开元旧乐章，乐中歌曲斷人腸。","鄶王玉笛三更咽，虢国金车十里香。","一自犬戎生蘇北，便從征戰老汾陽。","中原駿马搜求尽，沙苑年来草又芳。"]', '诗', 'shi', '', NULL, '開元後樂 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('137b41ce-9cd7-4095-9c7d-d975f8e44d2f', '漢武宮辭', '漢武宮辞', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["漢武清齋夜築壇，自斟明水醮仙官。","殿前玉女移香案，雲際金人捧露盤。","絳節幾時還入夢，碧桃何處更驂鸞？","茂陵煙雨埋弓劒，石馬無聲蔓草寒。"]', '["漢武清斋夜築壇，自斟明水醮仙官。","殿前玉女移香案，云際金人捧露盤。","絳節幾时還入梦，碧桃何处更驂鸾？","茂陵煙雨埋弓劒，石马無声蔓草寒。"]', '诗', 'shi', '', NULL, '漢武宮辭 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58a5a604-ed17-4c12-96b0-a4bec56c35e4', '潼關驛亭', '潼关驛亭', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["河上關門日日開，古今名利旋堪哀。","終軍壯節埋黃土，楊震豐碑翳綠苔。","寸祿應知霑有分，一官常懼處非才。","猶驚往歲同袍者，尚逐江東計吏來。"]', '["河上关门日日开，古今名利旋堪哀。","終軍壯節埋黄土，楊震豐碑翳綠苔。","寸祿應知霑有分，一官常懼处非才。","猶驚往歲同袍者，尚逐江东計吏来。"]', '诗', 'shi', '', NULL, '潼關驛亭 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e965659f-a5b3-4a5d-991d-8c24b35d23e3', '五峯隠者', '五峯隠者', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["煙霞壁立水溶溶，路轉崖回旦暮中。","鸂鶒畏人沈澗月，山羊投石挂巖松。","高齋既許陪雲宿，晚稻何妨爲客舂。","今日見君嘉遯處，悔將名利役疎慵。"]', '["煙霞壁立水溶溶，路轉崖回旦暮中。","鸂鶒畏人沈澗月，山羊投石挂巖松。","高斋既許陪云宿，晚稻何妨爲客舂。","今日见君嘉遯处，悔將名利役疎慵。"]', '诗', 'shi', '', NULL, '五峯隠者 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1784cb92-b5fb-4807-9534-e4e1bef1bed1', '上吏部崔相公', '上吏部崔相公', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["龍門曾共戰驚瀾，雷電浮雲出濬湍。","紫府有名同羽化，碧霄無路却泥蟠。","公車未結王生襪，客路虛彈貢禹冠。","今日罏錘任真宰，暫回風水不應難。"]', '["龙门曾共戰驚瀾，雷電浮云出濬湍。","紫府有名同羽化，碧霄無路却泥蟠。","公车未結王生襪，客路虛彈貢禹冠。","今日罏錘任真宰，暫回风水不應难。"]', '诗', 'shi', '', NULL, '上吏部崔相公 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('761e760f-4273-498e-a16b-db8103063604', '送劉郎中牧杭州', '送劉郎中牧杭州', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["一州橫制浙江灣，臺榭參差積翠間。","樓下潮回滄海浪，枕邊雲起剡溪山。","吳江水色連隄闊，越俗舂聲隔岸還。","聖代牧人無遠近，好將能事濟清閑。"]', '["一州橫制浙江灣，台榭參差積翠间。","楼下潮回滄海浪，枕邊云起剡溪山。","吳江水色連隄闊，越俗舂声隔岸還。","聖代牧人無远近，好將能事濟清闲。"]', '诗', 'shi', '', NULL, '送劉郎中牧杭州 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4bfc547e-9d40-41b7-8657-732438d3a94a', '貧女吟', '貧女吟', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["殘妝滿面淚闌干，幾許幽情欲話難。","雲髻嬾梳愁拆鳳，翠蛾羞照恐驚鸞。","南鄰送女初鳴珮，北里迎妻已夢蘭。","惟有深閨顦顇質，年年長凭繡牀看。"]', '["殘妝满面泪闌干，幾許幽情欲話难。","云髻嬾梳愁拆鳳，翠蛾羞照恐驚鸾。","南鄰送女初鳴珮，北里迎妻已梦蘭。","惟有深閨顦顇質，年年长凭繡牀看。"]', '诗', 'shi', '', NULL, '貧女吟 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea79dd90-e7c9-4670-8b12-b719b6017adc', '夜宴觀妓', '夜宴观妓', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["燈火熒煌醉客豪，捲簾羅綺豔仙桃。","纖腰怕束金蟬斷，鬢髪宜簪白燕高。","愁傍翠蛾深八字，笑回丹臉利雙刀。","無因得薦陽臺夢，願拂餘香到緼袍。"]', '["灯火熒煌醉客豪，捲簾羅綺豔仙桃。","纖腰怕束金蟬斷，鬢髪宜簪白燕高。","愁傍翠蛾深八字，笑回丹臉利雙刀。","無因得薦陽台梦，願拂餘香到緼袍。"]', '诗', 'shi', '', NULL, '夜宴觀妓 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d0b8eb1-c46c-4712-a990-58dac6e315aa', '送西川杜司空赴鎮', '送西川杜司空赴鎮', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["黑眉玄髪尚依然，紫綬金章五十年。","三入鳳池操國柄，八分龍節付兵權。","東周城闕中天外，西蜀樓臺落日邊。","莫遣洪罏曠真宰，九流人物待陶甄。"]', '["黑眉玄髪尚依然，紫綬金章五十年。","三入鳳池操国柄，八分龙節付兵權。","东周城闕中天外，西蜀楼台落日邊。","莫遣洪罏曠真宰，九流人物待陶甄。"]', '诗', 'shi', '', NULL, '送西川杜司空赴鎮 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83a43f0f-fe2b-43fa-aa38-dfcef972561f', '長安夜雨', '长安夜雨', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["滯雨通宵又徹明，百憂如草雨中生。","心關桂玉天難曉，運落風波夢亦驚。","壓樹早鴉飛不散，到窗寒鼓濕無聲。","當年志氣俱消盡，白髮新添四五莖。"]', '["滯雨通宵又徹明，百憂如草雨中生。","心关桂玉天难晓，運落风波梦亦驚。","壓樹早鴉飞不散，到窗寒鼓濕無声。","當年志氣俱消尽，白髮新添四五莖。"]', '诗', 'shi', '', NULL, '長安夜雨 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('262b4f83-7832-4869-b1ca-b9e976b516c6', '獵騎', '獵騎', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["兵印對封入衛稀，碧空雲盡早霜微。","滻川桑落鵰初下，渭曲禾收兔正肥。","陌上管弦清似語，草頭弓馬疾如飛。","豈知萬里黃雲戍，血迸金瘡臥鐵衣。"]', '["兵印对封入衛稀，碧空云尽早霜微。","滻川桑落鵰初下，渭曲禾收兔正肥。","陌上管弦清似語，草头弓马疾如飞。","豈知万里黄云戍，血迸金瘡臥鐵衣。"]', '诗', 'shi', '', NULL, '獵騎 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9f1da0e-55fc-4cb7-b93f-f001875badd7', '金城宮', '金城宮', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["憶昔明皇初御天，玉輿頻此駐神仙。","龍盤藻井噴紅豔，獸坐金牀吐碧煙。","雲外笙歌岐薛醉，月中臺榭后妃眠。","自從戎馬生河雒，深鎖篷萊一百年。"]', '["憶昔明皇初御天，玉輿頻此駐神仙。","龙盤藻井噴紅豔，獸坐金牀吐碧煙。","云外笙歌岐薛醉，月中台榭后妃眠。","自從戎马生河雒，深鎖篷萊一百年。"]', '诗', 'shi', '', NULL, '金城宮 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('844f3fbc-a8b3-4e49-8913-d47695aa2a56', '驚秋', '驚秋', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["露竹風蟬昨夜秋，百年心事付東流。","明霜義分成虛話，阜俗文章惜暗投。","長笑李斯稱溷鼠，每多莊叟喻犧牛。","五湖煙水盈歸夢，蘆荻花中一釣舟。"]', '["露竹风蟬昨夜秋，百年心事付东流。","明霜義分成虛話，阜俗文章惜暗投。","长笑李斯稱溷鼠，每多莊叟喻犧牛。","五湖煙水盈归梦，蘆荻花中一釣舟。"]', '诗', 'shi', '', NULL, '驚秋 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dea0c397-51f7-4b44-ae9a-b641b0921b64', '六街塵', '六街塵', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["六街塵起鼓鼕鼕，馬足車輸在處通。","百役並驅衣食內，四民長走路岐中。","年光與物隨流水，世事如花落曉風。","名利到身無了日，不知今古旋成空。"]', '["六街塵起鼓鼕鼕，马足车輸在处通。","百役並驱衣食內，四民长走路岐中。","年光與物隨流水，世事如花落晓风。","名利到身無了日，不知今古旋成空。"]', '诗', 'shi', '', NULL, '六街塵 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1282111-bc60-450c-991d-21cda510cb5b', '悼古', '悼古', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["細推今古事堪愁，貴賤同歸土一丘。","漢武玉堂人豈在，石家金谷水空流。","光陰自旦還將暮，草木從春又到秋。","閑事與時俱不了，且將身暫醉鄉遊。"]', '["細推今古事堪愁，貴賤同归土一丘。","漢武玉堂人豈在，石家金谷水空流。","光陰自旦還將暮，草木從春又到秋。","闲事與时俱不了，且將身暫醉乡游。"]', '诗', 'shi', '', NULL, '悼古 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f35d619-7910-4914-82cc-1ee193b68b2e', '九華觀廢月池', '九华观廢月池', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["曾發簫聲水檻前，夜蟾寒沼兩嬋娟。","微波有恨終歸海，明月無情却上天。","白鳥帶將林外雪，綠荷枯盡渚中蓮。","榮華不肯人間住，須讀莊生第一篇。"]', '["曾發簫声水檻前，夜蟾寒沼兩嬋娟。","微波有恨終归海，明月無情却上天。","白鸟带將林外雪，綠荷枯尽渚中蓮。","榮华不肯人间住，須读莊生第一篇。"]', '诗', 'shi', '', NULL, '九華觀廢月池 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9b924bc-a4be-4698-bfc1-09490ec8208a', '社日遊開元觀', '社日游开元观', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["松栢當軒蔓桂籬，古壇衰草暮風吹。","荒涼院宇無人到，寂寞煙霞只自知。","浪漬法堂餘像設，水存虛殿半科儀。","因求天寶年中夢，故事分明載折碑。"]', '["松栢當軒蔓桂籬，古壇衰草暮风吹。","荒涼院宇無人到，寂寞煙霞只自知。","浪漬法堂餘像設，水存虛殿半科儀。","因求天寶年中梦，故事分明載折碑。"]', '诗', 'shi', '', NULL, '社日遊開元觀 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4122ca02-e173-4081-9cd7-4e9ddb0eaddd', '九日曲池遊眺', '九日曲池游眺', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["陌上秋風動酒旗，江頭絲竹競相追。","正當海晏河清日，便是修文偃武時。","繡轂盡爲行樂伴，豔歌皆屬太平詩。","微臣辛忝頒堯曆，一望郊原愜所思。"]', '["陌上秋风动酒旗，江头絲竹競相追。","正當海晏河清日，便是修文偃武时。","繡轂尽爲行乐伴，豔歌皆屬太平诗。","微臣辛忝頒堯曆，一望郊原愜所思。"]', '诗', 'shi', '', NULL, '九日曲池遊眺 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d655fe8d-a977-4a12-8eb4-59a7e9107929', '九日郡齋有感', '九日郡斋有感', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["白日貪長夜更長，百般無意更思量。","三冬不見秦中雪，九日惟添鬢畔霜。","霞泛水文沈暮色，樹凌金氣發秋光。","樓前野菊無多少，一雨重開一番黃。"]', '["白日貪长夜更长，百般無意更思量。","三冬不见秦中雪，九日惟添鬢畔霜。","霞泛水文沈暮色，樹凌金氣發秋光。","楼前野菊無多少，一雨重开一番黄。"]', '诗', 'shi', '', NULL, '九日郡齋有感 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41dd47a5-48d2-43b0-a7d0-0af96d204781', '九日嘉州發軍亭即事', '九日嘉州發軍亭即事', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["三江分注界平沙，何處雲山是我家？","無鶴洲中翻白浪，掬金灘上折黃花。","不愁故國歸無日，却恨浮名苦有涯。","向暮灑酣賓客散，水天狼籍變餘霞。"]', '["三江分注界平沙，何处云山是我家？","無鹤洲中翻白浪，掬金灘上折黄花。","不愁故国归無日，却恨浮名苦有涯。","向暮灑酣賓客散，水天狼籍变餘霞。"]', '诗', 'shi', '', NULL, '九日嘉州發軍亭即事 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7d3d061-240d-4a68-926c-940f6cad8ab6', '九日雨中言懷', '九日雨中言懷', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["餻果盈前益自愁，那堪風雨滯刀州。","單牀冷席他鄉夢，紫榝黃花故國秋。","萬里音書何寂寂，百年生計甚悠悠。","潛將滿眼思家淚，灑寄長江東北流。"]', '["餻果盈前益自愁，那堪风雨滯刀州。","單牀冷席他乡梦，紫榝黄花故国秋。","万里音书何寂寂，百年生計甚悠悠。","潛將满眼思家泪，灑寄长江东北流。"]', '诗', 'shi', '', NULL, '九日雨中言懷 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('892c452f-6c23-4f2f-a23e-26c2fe94e268', '題劒門先寄上西蜀杜司徒', '題劒门先寄上西蜀杜司徒', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["峭壁橫空限一隅，劃開元氣建洪樞。","梯航百貨通邦計，鍵閉諸蠻屏帝都。","西蹙犬戎威北狄，南吞荆郢制東吳。","千年管鑰誰熔範，只自先天造化爐。"]', '["峭壁橫空限一隅，劃开元氣建洪樞。","梯航百貨通邦計，鍵閉諸蠻屏帝都。","西蹙犬戎威北狄，南吞荆郢制东吳。","千年管鑰誰熔範，只自先天造化爐。"]', '诗', 'shi', '', NULL, '題劒門先寄上西蜀杜司徒 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fda76f96-b6f7-4f89-8a63-0c769a123c95', '八月初一駕幸延喜樓看冠帶降戎', '八月初一駕幸延喜楼看冠带降戎', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["城頭旭日照闌干，城下降戎綵仗攢。","九陌塵埃千騎合，萬方臣妾一聲歡。","樓臺乍仰中天易，衣服初迴左袵難。","清水莫教波浪濁，從今赤嶺屬長安。"]', '["城头旭日照闌干，城下降戎綵仗攢。","九陌塵埃千騎合，万方臣妾一声歡。","楼台乍仰中天易，衣服初迴左袵难。","清水莫教波浪濁，從今赤嶺屬长安。"]', '诗', 'shi', '', NULL, '八月初一駕幸延喜樓看冠帶降戎 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7956dc78-719c-467f-952d-66d722286cc2', '送司徒相公赴闕', '送司徒相公赴闕', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["丞相銜恩赴闕時，錦城寒菊始離披。","龍媒舊識朝天路，雞樹長虛入夢枝。","十載殿廷連步武，雨來庸蜀撫疲羸。","莫愁中土無人識，自有明明聖主知。"]', '["丞相銜恩赴闕时，錦城寒菊始離披。","龙媒旧識朝天路，雞樹长虛入梦枝。","十載殿廷連步武，雨来庸蜀撫疲羸。","莫愁中土無人識，自有明明聖主知。"]', '诗', 'shi', '', NULL, '送司徒相公赴闕 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99eb076d-def1-4ef2-a55f-3ff3b29e12d3', '送靈州田尚書', '送靈州田尚书', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["陰風獵獵滿旗竿，白草颼颼劒氣攢。","九姓羌渾隨漢節，六州蕃落從戎鞍。","霜中入塞琱弓硬，月下翻營玉帳寒。","今曰路傍誰不指，穰苴門戶慣登壇。"]', '["陰风獵獵满旗竿，白草颼颼劒氣攢。","九姓羌渾隨漢節，六州蕃落從戎鞍。","霜中入塞琱弓硬，月下翻營玉帳寒。","今曰路傍誰不指，穰苴门戶慣登壇。"]', '诗', 'shi', '', NULL, '送靈州田尚書 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa45e9c6-4aff-400b-ba98-83b47165def2', '座中走筆送前蕭使君', '座中走笔送前蕭使君', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["笙歌慘慘咽離筵，槐柳陰陰五月天。","未學蘇秦榮佩印，却思平子賦歸田。","芙蓉欲綻溪邊蘂，楊柳初迷渡口煙。","自笑無成今老大，送君垂淚郭門前。"]', '["笙歌慘慘咽離筵，槐柳陰陰五月天。","未学蘇秦榮佩印，却思平子賦归田。","芙蓉欲綻溪邊蘂，楊柳初迷渡口煙。","自笑無成今老大，送君垂泪郭门前。"]', '诗', 'shi', '', NULL, '座中走筆送前蕭使君 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2cd547fa-bda2-4ac3-abf5-e8d7d0c2f952', '重送徐州李從事商隠', '重送徐州李從事商隠', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["曉乘征騎帶犀渠，醉別都門慘袂初。","蓮府望高秦御史，柳營官重漢尚書。","斬蛇澤畔人煙曉，戲馬臺前樹影疎。","尺組挂身何用處，古來名利盡丘墟。"]', '["晓乘征騎带犀渠，醉別都门慘袂初。","蓮府望高秦御史，柳營官重漢尚书。","斬蛇澤畔人煙晓，戲马台前樹影疎。","尺組挂身何用处，古来名利尽丘墟。"]', '诗', 'shi', '', NULL, '重送徐州李從事商隠 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3397705d-20b5-4616-b211-351595710999', '醉中聞甘州', '醉中闻甘州', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["老聽笙歌亦解愁，醉中因遣合甘州。","行追赤嶺千山外，坐想黃河一曲流。","日暮豈堪征婦怨，路傍能結旅人愁。","左綿刺史心先死，淚滿朱弦催白頭。"]', '["老听笙歌亦解愁，醉中因遣合甘州。","行追赤嶺千山外，坐想黄河一曲流。","日暮豈堪征婦怨，路傍能結旅人愁。","左綿刺史心先死，泪满朱弦催白头。"]', '诗', 'shi', '', NULL, '醉中聞甘州 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1b268ab-3f09-4a31-ad7f-8d2dc7c0c463', '北亭醉後敘舊贈東川陳書記', '北亭醉後敘旧贈东川陳书記', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["二十年前事盡空，半隨波浪半隨風。","謀身喜斷韓雞尾，辱命羞攜楚鵲籠。","符竹謬分錦水外，妻孥猶隔散關東。","臨岐莫怪朱弦絕，曾是君家入爨桐。"]', '["二十年前事尽空，半隨波浪半隨风。","謀身喜斷韓雞尾，辱命羞携楚鵲籠。","符竹謬分錦水外，妻孥猶隔散关东。","臨岐莫怪朱弦絕，曾是君家入爨桐。"]', '诗', 'shi', '', NULL, '北亭醉後敘舊贈東川陳書記 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0fb739a-d8c0-4a6c-8c83-0b3db4d16f1c', '宣政殿前陪位觀冊順宗憲宗皇帝尊號', '宣政殿前陪位观冊順宗憲宗皇帝尊號', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["樓頭鐘鼓遰相催，曙色當衙曉仗開。","孔雀扇分香案出，兖龍衣動冊函來。","金泥照耀傳中旨，玉節從容引上台。","盛禮永尊徽號畢，聖慈南面不勝哀。"]', '["楼头鐘鼓遰相催，曙色當衙晓仗开。","孔雀扇分香案出，兖龙衣动冊函来。","金泥照耀傳中旨，玉節從容引上台。","盛禮永尊徽號畢，聖慈南面不勝哀。"]', '诗', 'shi', '', NULL, '宣政殿前陪位觀冊順宗憲宗皇帝尊號 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef00ac2c-afcc-400c-817f-bbbe94cf5349', '元日樓前觀仗 一', '元日楼前观仗 一', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["千門曙色鏁寒梅，五夜疎鐘曉箭催。","寶馬占隄朝闕去，香車爭路進名來。","天臨玉几班初合，日照金雞仗欲迴。","更傍紫微瞻北斗，上林佳氣滿樓臺。"]', '["千门曙色鏁寒梅，五夜疎鐘晓箭催。","寶马占隄朝闕去，香车爭路進名来。","天臨玉几班初合，日照金雞仗欲迴。","更傍紫微瞻北斗，上林佳氣满楼台。"]', '诗', 'shi', '', NULL, '元日樓前觀仗 一 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('295f8a4c-3034-4df6-b4f4-fb1de6c6aeaf', '元日樓前觀仗 二', '元日楼前观仗 二', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["曈曈初日照樓臺，漠漠祥雲雉扇開。","星駐冕旒三殿曉，雲翻珠翠六宮來。","山呼聖壽煙霞動，風轉金章鳥獸迴。","欲識普恩無遠近，萬方歡忭一聲雷。"]', '["曈曈初日照楼台，漠漠祥云雉扇开。","星駐冕旒三殿晓，云翻珠翠六宮来。","山呼聖壽煙霞动，风轉金章鸟獸迴。","欲識普恩無远近，万方歡忭一声雷。"]', '诗', 'shi', '', NULL, '元日樓前觀仗 二 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9d762c8-8e3d-48b1-ace5-4181634c2be3', '醉中看花因思去歲之任', '醉中看花因思去歲之任', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["去歲乘軺出上京，軍機旦暮促前程。","狂花野草途中恨，春月秋風劒外情。","愁見瘴煙遮路色，厭聞溪水下灘聲。","不辭醉伴諸年少，羞對紅妝白髮生。"]', '["去歲乘軺出上京，軍機旦暮促前程。","狂花野草途中恨，春月秋风劒外情。","愁见瘴煙遮路色，厭闻溪水下灘声。","不辞醉伴諸年少，羞对紅妝白髮生。"]', '诗', 'shi', '', NULL, '醉中看花因思去歲之任 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96108962-a252-499d-b7ff-146a354f6c09', '題白馬驛', '題白马驛', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["晚麥芒乾風似秋，旅人方作蜀門遊。","家林漸隔梁山遠，客路長依漢水流。","滿壁存亡俱是夢，百年榮辱盡堪愁。","胸中憤氣文難遣，強指豐碑哭武侯。"]', '["晚麦芒乾风似秋，旅人方作蜀门游。","家林漸隔梁山远，客路长依漢水流。","满壁存亡俱是梦，百年榮辱尽堪愁。","胸中憤氣文难遣，強指豐碑哭武侯。"]', '诗', 'shi', '', NULL, '題白馬驛 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7aa9d8cf-dbf6-46bb-9ed1-48b489a8625d', '題籌筆驛', '題籌笔驛', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["天地三分魏蜀吳，武侯倔起贊訐謨。","身依豪杰傾心術，目對雲山演陣圖。","赤伏運衰功莫就，皇綱力振命先徂。","出師表上留遺懇，猶自千年激壯夫。"]', '["天地三分魏蜀吳，武侯倔起贊訐謨。","身依豪杰傾心術，目对云山演陣圖。","赤伏運衰功莫就，皇綱力振命先徂。","出師表上留遺懇，猶自千年激壯夫。"]', '诗', 'shi', '', NULL, '題籌筆驛 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94ac5ef8-fa10-465b-a629-939653523713', '賀楊收作相', '賀楊收作相', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["闕下憧憧車馬塵，沈浮相次宦遊身。","須知金印朝天客，同是沙隄避路人。","威鳳偶時因瑞聖，應龍無水謾通神。","立門不是趨時客，始向窮途學問津。"]', '["闕下憧憧车马塵，沈浮相次宦游身。","須知金印朝天客，同是沙隄避路人。","威鳳偶时因瑞聖，應龙無水謾通神。","立门不是趨时客，始向窮途学问津。"]', '诗', 'shi', '', NULL, '賀楊收作相 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd70acae-5721-4c7b-ae07-e13eea441f49', '元日田家', '元日田家', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["南村晴雪北村梅，樹裏茅簷曉盡開。","蠻榼出門兒婦去，烏龍迎路女郎來。","相逢但祝新正壽，對舉那愁暮景催。","長笑士林因宦別，一官輕是十年迴。"]', '["南村晴雪北村梅，樹裏茅簷晓尽开。","蠻榼出门兒婦去，烏龙迎路女郎来。","相逢但祝新正壽，对舉那愁暮景催。","长笑士林因宦別，一官轻是十年迴。"]', '诗', 'shi', '', NULL, '元日田家 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d7fa106-862f-43a4-96ae-0a2f9ae8d066', '送慶上人歸湖州因寄道儒座主', '送慶上人归湖州因寄道儒座主', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["上人今去白蘋洲，霅水苕溪我舊遊。","夜雨暗江漁火出，夕陽沈浦鴈花收。","閑聽別鳥啼紅樹，醉看歸僧櫂碧流。","若見儒公憑寄語，數莖霜鬢已驚秋。"]', '["上人今去白蘋洲，霅水苕溪我旧游。","夜雨暗江漁火出，夕陽沈浦鴈花收。","闲听別鸟啼紅樹，醉看归僧櫂碧流。","若见儒公憑寄語，數莖霜鬢已驚秋。"]', '诗', 'shi', '', NULL, '送慶上人歸湖州因寄道儒座主 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57c68237-4db2-4b29-b7b9-939975ff9171', '早發剡山', '早發剡山', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["正懷何謝俯長流，更覽餘封識嵊州。","樹色老依官舍晚，溪聲涼傍客衣秋。","南巖氣爽橫郛郭，天姥雲晴拂寺樓。","日暮不堪還上馬，蓼花風起路悠悠。"]', '["正懷何謝俯长流，更覽餘封識嵊州。","樹色老依官舍晚，溪声涼傍客衣秋。","南巖氣爽橫郛郭，天姥云晴拂寺楼。","日暮不堪還上马，蓼花风起路悠悠。"]', '诗', 'shi', '', NULL, '早發剡山 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24ca27ef-6e52-446c-9685-0d82b9098910', '題春臺觀', '題春台观', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["殿前松柏晦蒼蒼，杏遶仙壇水遶廊。","垂露額題精思院，博山爐褭降真香。","苔侵古碣迷陳事，雲到中峯失上方。","便擬尋溪弄花去，洞天誰更待劉郎。"]', '["殿前松柏晦蒼蒼，杏遶仙壇水遶廊。","垂露額題精思院，博山爐褭降真香。","苔侵古碣迷陳事，云到中峯失上方。","便擬尋溪弄花去，洞天誰更待劉郎。"]', '诗', 'shi', '', NULL, '題春臺觀 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5dc7a7a3-27ed-4b56-b96d-1167b1279057', '春晚東園曉思', '春晚东园晓思', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["劒外春餘日更長，東園留醉樂高張。","松杉露滴無情淚，桃杏風飄不語香。","鶯戀葉深啼綠樹，燕窺巢穩坐彫梁。","也知留滯年華晚，爭那罇前樂未央。"]', '["劒外春餘日更长，东园留醉乐高張。","松杉露滴無情泪，桃杏风飄不語香。","鶯戀葉深啼綠樹，燕窺巢穩坐彫梁。","也知留滯年华晚，爭那罇前乐未央。"]', '诗', 'shi', '', NULL, '春晚東園曉思 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c17fd378-8147-4a0f-971a-26f6be7d1963', '芙蓉溪送前資州裴使君歸京寧拜戶部裴侍郎', '芙蓉溪送前資州裴使君归京寧拜戶部裴侍郎', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["桑柘林枯𪍷麥乾，欲分離袂百憂攢。","臨溪莫話前途遠，舉酒須歌後會難。","薄宦未甘霜髪改，夾衣猶耐水風寒。","遙知阮巷歸寧日，幾院兒童候馬看。"]', '["桑柘林枯𪍷麦乾，欲分離袂百憂攢。","臨溪莫話前途远，舉酒須歌後會难。","薄宦未甘霜髪改，夾衣猶耐水风寒。","遙知阮巷归寧日，幾院兒童候马看。"]', '诗', 'shi', '', NULL, '芙蓉溪送前資州裴使君歸京寧拜戶部裴侍郎 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0f26ab9-6bb2-4715-98b7-5d5db8e6c99e', '伏聞令公疾愈對見延英因有賀詩遠封投獻', '伏闻令公疾愈对见延英因有賀诗远封投獻', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["吉語云云海外傳，令公疾愈起朝天。","皇風再扇寰區內，人鏡重開日月邊。","光啓四門通壽域，深疏萬頃溉情田。","陪臣自訝迷津久，願識方舟濟巨川。"]', '["吉語云云海外傳，令公疾愈起朝天。","皇风再扇寰區內，人镜重开日月邊。","光啓四门通壽域，深疏万頃溉情田。","陪臣自訝迷津久，願識方舟濟巨川。"]', '诗', 'shi', '', NULL, '伏聞令公疾愈對見延英因有賀詩遠封投獻 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4655da21-244c-4436-8345-7373bba1c0f1', '題獨孤處士村居', '題独孤处士村居', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["江上園盧荆作扉，男驅耕犢婦鳴機。","林巒當戶蔦蘿暗，桑柘繞村薑芋肥。","幾畝稻田還謂業，兩間茆舍亦言歸。","何如一被風塵染，到老云云相是非。"]', '["江上园盧荆作扉，男驱耕犢婦鳴機。","林巒當戶蔦蘿暗，桑柘繞村薑芋肥。","幾畝稻田還謂業，兩间茆舍亦言归。","何如一被风塵染，到老云云相是非。"]', '诗', 'shi', '', NULL, '題獨孤處士村居 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7ed0761-f51d-4b84-9869-2110ce293502', '題上皇觀', '題上皇观', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["狂寇窮兵犯帝畿，上皇曾此振戎衣。","門前衛士傳清警，砌下奚官掃翠微。","雲駐壽宮三洞啓，日迴仙仗六龍歸。","當時丹鳳銜書處，老柏蒼蒼已合圍。"]', '["狂寇窮兵犯帝畿，上皇曾此振戎衣。","门前衛士傳清警，砌下奚官掃翠微。","云駐壽宮三洞啓，日迴仙仗六龙归。","當时丹鳳銜书处，老柏蒼蒼已合圍。"]', '诗', 'shi', '', NULL, '題上皇觀 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35efc93b-b880-4dd2-9414-0e33c08ea56f', '奉和僕射相公送東川李支使歸使府夏侯相公', '奉和僕射相公送东川李支使归使府夏侯相公', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["兩地交通布政和，上台深喜使星過。","歡留白日千鐘酒，調入青雲一曲歌。","寒柳翠添微雨重，臘梅香綻細枝多。","平津萬一言卑散，莫忘高松寄女蘿。"]', '["兩地交通布政和，上台深喜使星過。","歡留白日千鐘酒，調入青云一曲歌。","寒柳翠添微雨重，臘梅香綻細枝多。","平津万一言卑散，莫忘高松寄女蘿。"]', '诗', 'shi', '', NULL, '奉和僕射相公送東川李支使歸使府夏侯相公 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f04518b-de2d-482e-a487-9384dcee97a0', '送封尚書節制興元', '送封尚书節制兴元', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["大封茅土鎮襃中，醉出都門殺氣雄。","陌上晚花迎虎節，馬前新月學彎弓。","珂臨響澗聲先合，斾到春山色更紅。","欲識真心報天子，滿旗全是發生風。"]', '["大封茅土鎮襃中，醉出都门殺氣雄。","陌上晚花迎虎節，马前新月学彎弓。","珂臨响澗声先合，斾到春山色更紅。","欲識真心報天子，满旗全是發生风。"]', '诗', 'shi', '', NULL, '送封尚書節制興元 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('717c4918-44a8-43a3-9d6b-7ac1185e16ab', '送西川梁常侍之新築龍山城幷錫賚兩州刺史及部落酋長等', '送西川梁常侍之新築龙山城幷錫賚兩州刺史及部落酋长等', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["聖主憂夷貊，屯師翦束欽。","皇家思眷祐，星使忽登臨。","用命期開國，違天必釁碪。","化須均草樹，恩不間飛沈。","束馬凌蒼壁，捫蘿上碧岑。","瘴川風自熱，劒閣氣長陰。","迅瀨從天急，喬松入地深。","仰觀唯一逕，俯瞰即千尋。","水作新城帶，山爲故壘襟。","東開洞君聽，南闢納蠻心。","渥澤濡三部，衣冠化雨林。","帶文雕白玉，符理篆黃金。","鳥道經邛𤏡，星纏過觜參。","迴軒如睿獎，休作苦辛吟。"]', '["聖主憂夷貊，屯師翦束欽。","皇家思眷祐，星使忽登臨。","用命期开国，違天必釁碪。","化須均草樹，恩不间飞沈。","束马凌蒼壁，捫蘿上碧岑。","瘴川风自熱，劒閣氣长陰。","迅瀨從天急，喬松入地深。","仰观唯一逕，俯瞰即千尋。","水作新城带，山爲故壘襟。","东开洞君听，南闢納蠻心。","渥澤濡三部，衣冠化雨林。","带文雕白玉，符理篆黄金。","鸟道經邛𤏡，星纏過觜參。","迴軒如睿獎，休作苦辛吟。"]', '诗', 'shi', '', NULL, '送西川梁常侍之新築龍山城幷錫賚兩州刺史及部落酋長等 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1651595-e5a0-4960-a1ce-3373f5e3726b', '河滿子', '河满子', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["繫馬宮槐老，持杯店菊黃。","故交今不見，流恨滿川光。"]', '["繫马宮槐老，持杯店菊黄。","故交今不见，流恨满川光。"]', '诗', 'shi', '', NULL, '河滿子 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3ea1c9d-0de9-4738-97fb-034154b7b740', '題黃花驛', '題黄花驛', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["孤戍迢迢蜀路長，鳥鳴山館客思鄉。","更看絕頂煙霞外，數樹巖花照夕陽。"]', '["孤戍迢迢蜀路长，鸟鳴山館客思乡。","更看絕頂煙霞外，數樹巖花照夕陽。"]', '诗', 'shi', '', NULL, '題黃花驛 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8f5de04-887e-48ca-93f6-693c7b50cb66', '涼州詞', '涼州词', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["昨夜蕃兵報國讐，沙州都護破涼州。","黃河九曲今歸漢，塞外縱橫戰血流。"]', '["昨夜蕃兵報国讐，沙州都護破涼州。","黄河九曲今归漢，塞外縱橫戰血流。"]', '诗', 'shi', '', NULL, '涼州詞 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d2a89fa-22d5-4234-9887-3fbf2d63f419', '嘉陵江', '嘉陵江', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["備問嘉陵江水湄，百川東去爾西之。","但教清淺源流在，天路朝宗會有期。"]', '["備问嘉陵江水湄，百川东去爾西之。","但教清淺源流在，天路朝宗會有期。"]', '诗', 'shi', '', NULL, '嘉陵江 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba6b993b-d939-4323-8fde-af6076038270', '觀獵', '观獵', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["馬縮寒毛鷹落臕，角弓初暖箭新調。","平原踏盡無禽出，竟日翻身望碧霄。"]', '["马縮寒毛鷹落臕，角弓初暖箭新調。","平原踏尽無禽出，竟日翻身望碧霄。"]', '诗', 'shi', '', NULL, '觀獵 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b5e2faf-1985-40a5-9ef0-2ee294ff10dc', '狼煙', '狼煙', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["三道狼煙過磧來，受降城上探旗開。","傳聲却報邊無事，自是官軍入抄回。"]', '["三道狼煙過磧来，受降城上探旗开。","傳声却報邊無事，自是官軍入抄回。"]', '诗', 'shi', '', NULL, '狼煙 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c8b8c1d-335d-42e2-90ff-550d3e636427', '俠少年', '俠少年', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["綠眼胡鷹踏錦韝，五花騘馬白貂裘。","往來三市無人識，倒把金鞭上酒樓。"]', '["綠眼胡鷹踏錦韝，五花騘马白貂裘。","往来三市無人識，倒把金鞭上酒楼。"]', '诗', 'shi', '', NULL, '俠少年 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce7aafb9-dee8-4ab8-9235-5883ad901200', '感塞', '感塞', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["滿塞旌旗鎮上遊，各分天子一方憂。","無因得見哥舒翰，可惜西山十八州。"]', '["满塞旌旗鎮上游，各分天子一方憂。","無因得见哥舒翰，可惜西山十八州。"]', '诗', 'shi', '', NULL, '感塞 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c283ce18-2602-4c05-817f-cab9beb010fc', '聽曹剛彈琵琶', '听曹剛彈琵琶', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["禁曲新翻下玉都，四弦掁觸五音殊。","不知天上彈多少，金鳳銜花尾半無。"]', '["禁曲新翻下玉都，四弦掁觸五音殊。","不知天上彈多少，金鳳銜花尾半無。"]', '诗', 'shi', '', NULL, '聽曹剛彈琵琶 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea58bf4b-57a5-4ba4-8036-5d0ee013a3e9', '定山寺', '定山寺', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["十里松蘿映碧苔，一川晴色鏡中開。","遙聞上界翻經處，片片香雲出院來。"]', '["十里松蘿映碧苔，一川晴色镜中开。","遙闻上界翻經处，片片香云出院来。"]', '诗', 'shi', '', NULL, '定山寺 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf86bb4d-bbf3-42ce-9bcf-de6a79a451f5', '越王樓送高梓州入朝', '越王楼送高梓州入朝', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["乘遞初登建外州，傾心喜事富人侯。","方當游藝依仁日，便到攀轅臥轍秋。","容聽巴歌消子夜，許陪仙躅上危樓。","欲知恨戀情深處，聽取長江旦暮流。"]', '["乘遞初登建外州，傾心喜事富人侯。","方當游藝依仁日，便到攀轅臥轍秋。","容听巴歌消子夜，許陪仙躅上危楼。","欲知恨戀情深处，听取长江旦暮流。"]', '诗', 'shi', '', NULL, '越王樓送高梓州入朝 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f660fabc-1b8d-44f5-b403-b8089a3e538e', '送李蘊赴鄭州因獻盧郎中', '送李蘊赴鄭州因獻盧郎中', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["僕射陂西想到時，滿川晴色見旌旗。","馬融閑臥笛聲遠，王粲醉吟樓影移。","幾日賦詩秋水寺，經年草詔白雲司。","唯君此去人多羨，却是恩深自不知。"]', '["僕射陂西想到时，满川晴色见旌旗。","马融闲臥笛声远，王粲醉吟楼影移。","幾日賦诗秋水寺，經年草詔白云司。","唯君此去人多羨，却是恩深自不知。"]', '诗', 'shi', '', NULL, '送李蘊赴鄭州因獻盧郎中 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('068fe2b7-df0f-4f4d-af57-9b88d02f9373', '送裴評事', '送裴評事', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["塞垣從事識兵機，只擬平戎不擬歸。","入夜茄聲含白髪，報秋榆葉落征衣。","城臨戰壘黃雲晚，馬渡寒沙夕照微。","此別不應書斷絕，滿天霜雪有鴻飛。"]', '["塞垣從事識兵機，只擬平戎不擬归。","入夜茄声含白髪，報秋榆葉落征衣。","城臨戰壘黄云晚，马渡寒沙夕照微。","此別不應书斷絕，满天霜雪有鴻飞。"]', '诗', 'shi', '', NULL, '送裴評事 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e608ce8-b69e-4a37-bf82-766b0eb22432', '送沈單作尉江都', '送沈單作尉江都', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["煬帝都城春水邊，笙歌夜上木蘭船。","三千宮女自塗地，十萬人家如洞天。","焰焰花枝官舍晚，重重雲影寺牆連。","少年作尉須矜慎，莫向樓前墜馬鞭。"]', '["煬帝都城春水邊，笙歌夜上木蘭船。","三千宮女自塗地，十万人家如洞天。","焰焰花枝官舍晚，重重云影寺牆連。","少年作尉須矜慎，莫向楼前墜马鞭。"]', '诗', 'shi', '', NULL, '送沈單作尉江都 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db3b36f8-1dee-48d3-9cd3-03a379d57661', '送薛耽先輩歸謁漢南', '送薛耽先輩归謁漢南', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["雲繞千峰驛路長，謝家聯句待檀郎。","手持碧落新攀桂，月在東軒舊選牀。","幾日旌幢延駿馬，到時冰玉動華堂。","孔門多少風流處，不遣顏回識醉鄉。"]', '["云繞千峰驛路长，謝家聯句待檀郎。","手持碧落新攀桂，月在东軒旧選牀。","幾日旌幢延駿马，到时冰玉动华堂。","孔门多少风流处，不遣顏回識醉乡。"]', '诗', 'shi', '', NULL, '送薛耽先輩歸謁漢南 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0d46b44-5cb0-4329-9502-3a9d0d38066e', '送同年鄭祥先輩歸漢南', '送同年鄭祥先輩归漢南', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["年來驚喜兩心知，高處同攀次第枝。","人倚繡屏閑賞夜，馬嘶花徑醉歸時。","聲名本自文章得，藩溷曾勞筆硯隨。","家去恩門四千里，只應從此夢旌旗。"]', '["年来驚喜兩心知，高处同攀次第枝。","人倚繡屏闲賞夜，马嘶花徑醉归时。","声名本自文章得，藩溷曾勞笔硯隨。","家去恩门四千里，只應從此梦旌旗。"]', '诗', 'shi', '', NULL, '送同年鄭祥先輩歸漢南 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8129e38c-8c5e-4dc3-ba35-996a33fce0cf', '李先輩擢第東歸有贈送', '李先輩擢第东归有贈送', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["金榜前頭無是非，平人分得一枝歸。","正憐日暖雲飄路，何處宴迴風滿衣？","門掩長淮心更遠，渡連芳草馬如飛。","茂陵自笑猶多病，空有書齋在翠微。"]', '["金榜前头無是非，平人分得一枝归。","正怜日暖云飄路，何处宴迴风满衣？","门掩长淮心更远，渡連芳草马如飞。","茂陵自笑猶多病，空有书斋在翠微。"]', '诗', 'shi', '', NULL, '李先輩擢第東歸有贈送 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5261ef8d-9fc4-46ca-8883-dd41faf375db', '送韓絳歸淮南寄韓綽先輩', '送韓絳归淮南寄韓綽先輩', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["島上花枝繫釣船，隋家宮畔水連天。","江帆自落鳥飛外，月觀靜依春色邊。","門巷草生車轍在，朝廷恩及鴈行聯。","相逢且問昭州事，曾鼓莊盆對逝川。"]', '["島上花枝繫釣船，隋家宮畔水連天。","江帆自落鸟飞外，月观静依春色邊。","门巷草生车轍在，朝廷恩及鴈行聯。","相逢且问昭州事，曾鼓莊盆对逝川。"]', '诗', 'shi', '', NULL, '送韓絳歸淮南寄韓綽先輩 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5001bf44-e94e-4a2b-a2b9-cbc65005f72a', '送盧緘歸揚州', '送盧緘归揚州', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["曾向雷塘寄掩扉，荀家燈火有餘輝。","關河日暮望空極，楊柳渡頭人獨歸。","隋苑荒臺風褭褭，灞陵殘雨夢依依。","今年春色還相悞，爲我江邊謝釣磯。"]', '["曾向雷塘寄掩扉，荀家灯火有餘輝。","关河日暮望空極，楊柳渡头人独归。","隋苑荒台风褭褭，灞陵殘雨梦依依。","今年春色還相悞，爲我江邊謝釣磯。"]', '诗', 'shi', '', NULL, '送盧緘歸揚州 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67df2e07-66ce-47f6-95e0-75181be40d17', '送剡客', '送剡客', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["兩重江外片帆斜，數里林塘遶一家。","門掩右軍餘水石，路橫諸謝舊煙霞。","扁舟幾處逢溪雪，長笛何人怨柳花。","若到天台洞陽觀，葛洪丹井在雲涯。"]', '["兩重江外片帆斜，數里林塘遶一家。","门掩右軍餘水石，路橫諸謝旧煙霞。","扁舟幾处逢溪雪，长笛何人怨柳花。","若到天台洞陽观，葛洪丹井在云涯。"]', '诗', 'shi', '', NULL, '送剡客 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf8ff989-88db-4ccd-a094-c86bb3257a80', '涼州詞 一', '涼州词 一', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["千里東歸客，無心憶舊遊。","挂帆遊□水，高枕到青州。"]', '["千里东归客，無心憶旧游。","挂帆游□水，高枕到青州。"]', '诗', 'shi', '', NULL, '涼州詞 一 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29ba8d42-de85-4626-bf54-5046c009b325', '涼州詞 二', '涼州词 二', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["君住孤山下，煙深夜徑長。","轅門渡綠水，遊苑遶垂楊。"]', '["君住孤山下，煙深夜徑长。","轅门渡綠水，游苑遶垂楊。"]', '诗', 'shi', '', NULL, '涼州詞 二 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('731ea082-111e-490a-80eb-dbd4fd75edad', '涼州詞 三', '涼州词 三', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["樹發花如錦，鶯啼柳若絲。","更遊懽宴地，愁見別離時。"]', '["樹發花如錦，鶯啼柳若絲。","更游懽宴地，愁见別離时。"]', '诗', 'shi', '', NULL, '涼州詞 三 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb779100-51f8-4314-ac06-5993764d9462', '送蕭俛相公歸山', '送蕭俛相公归山', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["眼前軒冕是鴻毛，天上人情謾自勞。","脫却朝衣便東去，青雲不及白雲高。"]', '["眼前軒冕是鴻毛，天上人情謾自勞。","脫却朝衣便东去，青云不及白云高。"]', '诗', 'shi', '', NULL, '送蕭俛相公歸山 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9160e6a2-5837-44ec-b796-1800b90b3274', '石膏枕', '石膏枕', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["表裏通明不假彫，冷於春雪白於瑤。","朝來送在涼牀上，只怕風吹日炙銷。"]', '["表裏通明不假彫，冷於春雪白於瑤。","朝来送在涼牀上，只怕风吹日炙銷。"]', '诗', 'shi', '', NULL, '石膏枕 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b0d6ae4-1064-4928-9530-ba4af4bc4023', '句', '句', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["草荒留客院，泥臥餵生臺。","碧碎鴛鴦瓦，香埋菡萏罏。","初日暉暉上彩旄。","金鞍俯鞚塵開處，銀鏑離弦中處聲。","昨日鴻毛萬鈞重，今朝山岳一朝輕。"]', '["草荒留客院，泥臥餵生台。","碧碎鴛鴦瓦，香埋菡萏罏。","初日暉暉上彩旄。","金鞍俯鞚塵开处，銀鏑離弦中处声。","昨日鴻毛万鈞重，今朝山岳一朝轻。"]', '诗', 'shi', '', NULL, '句 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('750af26d-4d14-4e58-a736-8efcfd9dc01b', '汾上宴別', '汾上宴別', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["雲物如故鄉，山川知異路。","年來未歸客，馬上春色暮。","一尊花下酒，殘日水西樹。","不待管弦終，搖鞭背花去。"]', '["云物如故乡，山川知異路。","年来未归客，马上春色暮。","一尊花下酒，殘日水西樹。","不待管弦終，搖鞭背花去。"]', '诗', 'shi', '', NULL, '汾上宴別 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c20a6e02-376a-4edb-9891-99f728e54cae', '書齋雪後', '书斋雪後', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["擁褐坐茅簷，春晴喜初日。","微風入桃徑，爽氣歸縹帙。","頻時苦風雪，就景理巾櫛。","樹暖高鳥來，窗閑曙雲出。","鄉遙路難越，道蹇時易失。","欲靜又不能，東山負芝朮。"]', '["擁褐坐茅簷，春晴喜初日。","微风入桃徑，爽氣归縹帙。","頻时苦风雪，就景理巾櫛。","樹暖高鸟来，窗闲曙云出。","乡遙路难越，道蹇时易失。","欲静又不能，东山負芝朮。"]', '诗', 'shi', '', NULL, '書齋雪後 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0b26d34-d1b8-42a9-99b4-d911b5365c17', '寄道者', '寄道者', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["洞庭先生歸路長，海雲望極春茫茫。","別來幾度向蓬島，自傍瑤臺折靈草。"]', '["洞庭先生归路长，海云望極春茫茫。","別来幾度向蓬島，自傍瑤台折靈草。"]', '诗', 'shi', '', NULL, '寄道者 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9191631-5a5a-40b4-b7fc-a24dc25e1fb5', '虎丘寺贈漁處士', '虎丘寺贈漁处士', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["蘭若雲深處，前年客重過。","巖空秋色動，水闊夕陽多。","早負江湖志，今如鬢髮何。","唯思閑勝我，釣艇在煙波。"]', '["蘭若云深处，前年客重過。","巖空秋色动，水闊夕陽多。","早負江湖志，今如鬢髮何。","唯思闲勝我，釣艇在煙波。"]', '诗', 'shi', '', NULL, '虎丘寺贈漁處士 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c9ce09e-61c1-4826-9528-ed1635445f9d', '陪崔璞侍御和崔㻂春日有懷', '陪崔璞侍御和崔㻂春日有懷', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["詩家本多感，況值廣陵春。","暖駐含窗日，香餘醉袖塵。","浮名皆有分，一笑最關身。","自此容依託，清才兩故人。"]', '["诗家本多感，況值廣陵春。","暖駐含窗日，香餘醉袖塵。","浮名皆有分，一笑最关身。","自此容依託，清才兩故人。"]', '诗', 'shi', '', NULL, '陪崔璞侍御和崔㻂春日有懷 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9c71dec-c57a-4933-b5d1-034692239055', '昔昔鹽二十首 垂柳覆金堤', '昔昔鹽二十首 垂柳覆金堤', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["新年垂柳色，嫋嫋對空閨。","不畏芳菲好，自緣離別啼。","因風飄玉戶，向日映金堤。","驛使何時度，還將贈隴西。"]', '["新年垂柳色，嫋嫋对空閨。","不畏芳菲好，自緣離別啼。","因风飄玉戶，向日映金堤。","驛使何时度，還將贈隴西。"]', '诗', 'shi', '', NULL, '昔昔鹽二十首 垂柳覆金堤 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('984a653c-4bf1-4110-8fda-66ddccb1d8f6', '昔昔鹽二十首 蘼蕪葉復齊', '昔昔鹽二十首 蘼蕪葉复齊', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["提筐紅葉下，度日採蘼蕪。","掬翠香盈袖，看花憶故夫。","葉齊誰復見，風暖恨偏孤。","一被春光累，容顏與昔殊。"]', '["提筐紅葉下，度日採蘼蕪。","掬翠香盈袖，看花憶故夫。","葉齊誰复见，风暖恨偏孤。","一被春光累，容顏與昔殊。"]', '诗', 'shi', '', NULL, '昔昔鹽二十首 蘼蕪葉復齊 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('941c324b-08d0-4ecf-9ee7-62d71dd86afd', '昔昔鹽二十首 水溢芙蓉沼', '昔昔鹽二十首 水溢芙蓉沼', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["淥沼春光後，青青草色濃。","綺羅驚翡翠，暗粉妬芙蓉。","雲遍窗前見，荷翻鏡裏逢。","將心託流水，終日渺無從。"]', '["淥沼春光後，青青草色濃。","綺羅驚翡翠，暗粉妬芙蓉。","云遍窗前见，荷翻镜裏逢。","將心託流水，終日渺無從。"]', '诗', 'shi', '', NULL, '昔昔鹽二十首 水溢芙蓉沼 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c6cf3ab-1dcb-445f-b3b2-300ff32f67ae', '昔昔鹽二十首 花飛桃李蹊', '昔昔鹽二十首 花飞桃李蹊', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["遠期難可託，桃李自依依。","花徑無容跡，戎裘未下機。","隨風開又落，度日掃還飛。","欲折枝枝贈，那知歸不歸。"]', '["远期难可託，桃李自依依。","花徑無容跡，戎裘未下機。","隨风开又落，度日掃還飞。","欲折枝枝贈，那知归不归。"]', '诗', 'shi', '', NULL, '昔昔鹽二十首 花飛桃李蹊 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09972a8e-d749-4d05-b29a-571d09882c43', '昔昔鹽二十首 採桑秦氏女', '昔昔鹽二十首 採桑秦氏女', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["南陌採桑出，誰知妾姓秦。","獨憐傾國貌，不負早鶯春。","珠履盪花濕，龍鉤折桂新。","使君那駐馬，自有侍中人。"]', '["南陌採桑出，誰知妾姓秦。","独怜傾国貌，不負早鶯春。","珠履盪花濕，龙鉤折桂新。","使君那駐马，自有侍中人。"]', '诗', 'shi', '', NULL, '昔昔鹽二十首 採桑秦氏女 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6fb2cf8f-61e7-41a3-a169-ddff2b7ec09a', '昔昔鹽二十首 織錦竇家妻', '昔昔鹽二十首 织錦竇家妻', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["當年誰不羨，分作竇家妻。","錦字行行苦，羅幃日日啼。","豈知登隴遠，秪恨下機迷。","直候陽關使，殷勤寄海西。"]', '["當年誰不羨，分作竇家妻。","錦字行行苦，羅幃日日啼。","豈知登隴远，秪恨下機迷。","直候陽关使，殷勤寄海西。"]', '诗', 'shi', '', NULL, '昔昔鹽二十首 織錦竇家妻 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('666459a4-0a5a-4b67-a33b-b6c85e1ea9f6', '昔昔鹽二十首 關山別蕩子', '昔昔鹽二十首 关山別蕩子', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["那堪聞蕩子，迢遞涉關山。","腸爲馬嘶斷，衣從淚滴斑。","愁看塞上路，詎惜鏡中顏。","儻見征西雁，應傳一字還。"]', '["那堪闻蕩子，迢遞涉关山。","腸爲马嘶斷，衣從泪滴斑。","愁看塞上路，詎惜镜中顏。","儻见征西雁，應傳一字還。"]', '诗', 'shi', '', NULL, '昔昔鹽二十首 關山別蕩子 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb77eb12-7a8f-42eb-8549-4146401ca024', '昔昔鹽二十首 風月守空閨', '昔昔鹽二十首 风月守空閨', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["良人猶遠戍，耿耿夜閨空。","繡戶流宵月，羅幃坐晚風。","魂飛沙帳北，腸斷玉關中。","尚自無消息，錦衾那得同。"]', '["良人猶远戍，耿耿夜閨空。","繡戶流宵月，羅幃坐晚风。","魂飞沙帳北，腸斷玉关中。","尚自無消息，錦衾那得同。"]', '诗', 'shi', '', NULL, '昔昔鹽二十首 風月守空閨 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6b50da8-c9e3-4606-9053-44c1cb81e657', '昔昔鹽二十首 恆歛千金笑', '昔昔鹽二十首 恆歛千金笑', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["玉顏恆自歛，羞出鏡臺前。","早惑陽城客，今悲華錦筵。","從軍人更遠，投喜鵲空傳。","夫壻交河北，迢迢路幾千。"]', '["玉顏恆自歛，羞出镜台前。","早惑陽城客，今悲华錦筵。","從軍人更远，投喜鵲空傳。","夫壻交河北，迢迢路幾千。"]', '诗', 'shi', '', NULL, '昔昔鹽二十首 恆歛千金笑 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('686b0d8b-be2b-4a99-a6e9-878c755414dc', '昔昔鹽二十首 長垂雙玉啼', '昔昔鹽二十首 长垂雙玉啼', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["雙雙紅淚墮，度日暗中啼。","雁出居延北，人猶遼海西。","向燈垂玉枕，對月灑金閨。","不惜羅衣濕，惟愁歸意迷。"]', '["雙雙紅泪墮，度日暗中啼。","雁出居延北，人猶遼海西。","向灯垂玉枕，对月灑金閨。","不惜羅衣濕，惟愁归意迷。"]', '诗', 'shi', '', NULL, '昔昔鹽二十首 長垂雙玉啼 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1719bc8-c733-478c-bbd8-cf58722747cd', '昔昔鹽二十首 蟠龍隨鏡隱', '昔昔鹽二十首 蟠龙隨镜隐', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["鸞鏡無由照，蛾眉豈忍看。","不知愁髮換，空見隱龍蟠。","那愜紅顏改，偏傷白日殘。","今朝窺玉匣，雙淚落闌干。"]', '["鸾镜無由照，蛾眉豈忍看。","不知愁髮換，空见隐龙蟠。","那愜紅顏改，偏傷白日殘。","今朝窺玉匣，雙泪落闌干。"]', '诗', 'shi', '', NULL, '昔昔鹽二十首 蟠龍隨鏡隱 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1fc4fd2c-09bd-43cc-82a0-72e173fbfacb', '昔昔鹽二十首 彩鳳逐帷低', '昔昔鹽二十首 彩鳳逐帷低', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["巧繡雙飛鳳，朝朝伴下帷。","春花那見照，暮色已頻欺。","欲卷思君處，將啼裛淚時。","何年征戍客，傳語報佳期。"]', '["巧繡雙飞鳳，朝朝伴下帷。","春花那见照，暮色已頻欺。","欲卷思君处，將啼裛泪时。","何年征戍客，傳語報佳期。"]', '诗', 'shi', '', NULL, '昔昔鹽二十首 彩鳳逐帷低 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f336f2a5-6bad-4246-a5b7-dd65e0288b07', '昔昔鹽二十首 驚魂同夜鵲', '昔昔鹽二十首 驚魂同夜鵲', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["萬里無人見，衆情難與論。","思君常入夢，同鵲屢驚魂。","孤寢紅羅帳，雙啼玉筯痕。","妾心甘自保，豈復暫忘恩。"]', '["万里無人见，衆情难與論。","思君常入梦，同鵲屢驚魂。","孤寢紅羅帳，雙啼玉筯痕。","妾心甘自保，豈复暫忘恩。"]', '诗', 'shi', '', NULL, '昔昔鹽二十首 驚魂同夜鵲 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f93ea6e-2b5d-48e4-b706-2dcc35a74b0c', '昔昔鹽二十首 倦寢聽晨雞', '昔昔鹽二十首 倦寢听晨雞', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["去去邊城騎，愁眠掩夜閨。","披衣窺落月，拭淚待鳴雞。","不憤連年別，那看長夜啼。","功成應自恨，早晚發遼西。"]', '["去去邊城騎，愁眠掩夜閨。","披衣窺落月，拭泪待鳴雞。","不憤連年別，那看长夜啼。","功成應自恨，早晚發遼西。"]', '诗', 'shi', '', NULL, '昔昔鹽二十首 倦寢聽晨雞 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8cdfada8-4a2b-473a-8a0c-5ff207a989dc', '昔昔鹽二十首 暗牑懸蛛網', '昔昔鹽二十首 暗牑懸蛛網', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["暗中蛛網織，歷亂綺窗前。","萬里終無信，一條徒自懸。","分從珠露滴，愁見隟風牽。","妾意何聊賴，看看劇斷絃。"]', '["暗中蛛網织，歷亂綺窗前。","万里終無信，一條徒自懸。","分從珠露滴，愁见隟风牽。","妾意何聊賴，看看劇斷絃。"]', '诗', 'shi', '', NULL, '昔昔鹽二十首 暗牑懸蛛網 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2ac50d7-24ae-48a7-9750-ce28e41d0f7b', '昔昔鹽二十首 空梁落燕泥', '昔昔鹽二十首 空梁落燕泥', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["春至今朝燕，花時伴獨啼。","飛斜珠箔隔，語近畫梁低。","帷卷閑窺戶，牀空暗落泥。","誰能長對此，雙去復雙栖。"]', '["春至今朝燕，花时伴独啼。","飞斜珠箔隔，語近畫梁低。","帷卷闲窺戶，牀空暗落泥。","誰能长对此，雙去复雙栖。"]', '诗', 'shi', '', NULL, '昔昔鹽二十首 空梁落燕泥 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58dfc7b8-98f9-480c-8a1c-36352ddbece5', '昔昔鹽二十首 前年過代北', '昔昔鹽二十首 前年過代北', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["代北幾千里，前年又復經。","燕山雲自合，胡塞草應青。","鐵馬喧鼙鼓，蛾眉怨錦屏。","不知羌笛曲，掩淚若爲聽。"]', '["代北幾千里，前年又复經。","燕山云自合，胡塞草應青。","鐵马喧鼙鼓，蛾眉怨錦屏。","不知羌笛曲，掩泪若爲听。"]', '诗', 'shi', '', NULL, '昔昔鹽二十首 前年過代北 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec27579f-94f1-45a2-a179-43b20f8ec354', '昔昔鹽二十首 今歲往遼西', '昔昔鹽二十首 今歲往遼西', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["萬里飛書至，聞君已渡遼。","秪諳新別苦，忘却舊時嬌。","烽戍年將老，紅顏日向彫。","胡沙兼漢苑，相望幾迢迢。"]', '["万里飞书至，闻君已渡遼。","秪諳新別苦，忘却旧时嬌。","烽戍年將老，紅顏日向彫。","胡沙兼漢苑，相望幾迢迢。"]', '诗', 'shi', '', NULL, '昔昔鹽二十首 今歲往遼西 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03fd9418-5670-4794-b5f0-562a90cbcaa4', '昔昔鹽二十首 一去無還意', '昔昔鹽二十首 一去無還意', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["良人征絕域，一去不言還。","百戰攻胡虜，三冬阻玉關。","蕭蕭邊馬思，獵獵戍旗閑。","獨抱千重恨，連年未解顏。"]', '["良人征絕域，一去不言還。","百戰攻胡虜，三冬阻玉关。","蕭蕭邊马思，獵獵戍旗闲。","独抱千重恨，連年未解顏。"]', '诗', 'shi', '', NULL, '昔昔鹽二十首 一去無還意 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2bbe4d4-f485-4424-be34-83249854b040', '昔昔鹽二十首 那能惜馬蹄', '昔昔鹽二十首 那能惜马蹄', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["雲中路杳杳，江畔草淒淒。","妾久垂珠淚，君何惜馬蹄。","邊風悲曉角，營月怨春鼙。","未道休征戰，愁眉又復低。"]', '["云中路杳杳，江畔草淒淒。","妾久垂珠泪，君何惜马蹄。","邊风悲晓角，營月怨春鼙。","未道休征戰，愁眉又复低。"]', '诗', 'shi', '', NULL, '昔昔鹽二十首 那能惜馬蹄 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d7a2c8f-8fd7-498d-aa4c-764a7435f121', '送韋處士歸省朔方', '送韋处士归省朔方', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["映柳見行色，故山當落暉。","青雲知已歿，白首一身歸。","滿袖蕭關雨，連沙塞雁飛。","到家翻有喜，借取老萊衣。"]', '["映柳见行色，故山當落暉。","青云知已歿，白首一身归。","满袖蕭关雨，連沙塞雁飞。","到家翻有喜，借取老萊衣。"]', '诗', 'shi', '', NULL, '送韋處士歸省朔方 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28a80f28-64e4-4523-87a2-73557f3d2650', '送權先輩歸覲信安', '送權先輩归覲信安', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["衣綵獨歸去，一枝蘭更香。","馬嘶芳草渡，門掩百花塘。","野色亭臺晚，灘聲枕簟涼。","小齋松島上，重葉覆書堂。"]', '["衣綵独归去，一枝蘭更香。","马嘶芳草渡，门掩百花塘。","野色亭台晚，灘声枕簟涼。","小斋松島上，重葉覆书堂。"]', '诗', 'shi', '', NULL, '送權先輩歸覲信安 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b8f05b1-60cf-446c-bedf-c0304d8f8239', '風蟬', '风蟬', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["風蟬旦夕鳴，伴夜送秋聲。","故里客歸盡，水邊身獨行。","噪軒高樹合，驚枕暮山橫。","聽處無人見，塵埃滿甑生。"]', '["风蟬旦夕鳴，伴夜送秋声。","故里客归尽，水邊身独行。","噪軒高樹合，驚枕暮山橫。","听处無人见，塵埃满甑生。"]', '诗', 'shi', '', NULL, '風蟬 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95470506-477b-4e96-bf9b-0925265e2b10', '重寄盧中丞', '重寄盧中丞', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["賤子來還去，何人伴使君。","放歌迎晚醉，指路上高雲。","此夜雁初至，空山雨獨聞。","別多頭欲白，惆悵惜餘醺。"]', '["賤子来還去，何人伴使君。","放歌迎晚醉，指路上高云。","此夜雁初至，空山雨独闻。","別多头欲白，惆悵惜餘醺。"]', '诗', 'shi', '', NULL, '重寄盧中丞 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('477002e1-7de4-489f-ba72-592956c84f56', '曉發', '晓發', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["旅行宜蚤發，況復是南歸。","月影緣山盡，鐘聲隔浦微。","星殘螢共映，葉落鳥驚飛。","去去渡南渚，樹深人出稀。"]', '["旅行宜蚤發，況复是南归。","月影緣山尽，鐘声隔浦微。","星殘螢共映，葉落鸟驚飞。","去去渡南渚，樹深人出稀。"]', '诗', 'shi', '', NULL, '曉發 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49647d41-0df8-4022-a289-37fcf8e34c9d', '送友人鄭州歸覲', '送友人鄭州归覲', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["爲有趨庭戀，應忘道路賒。","風消滎澤凍，雨靜圃田沙。","古陌人來遠，遙天雁勢斜。","園林新到日，春酒酌梨花。"]', '["爲有趨庭戀，應忘道路賒。","风消滎澤凍，雨静圃田沙。","古陌人来远，遙天雁勢斜。","园林新到日，春酒酌梨花。"]', '诗', 'shi', '', NULL, '送友人鄭州歸覲 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('213266f4-ff87-4322-be24-26dd6832d75c', '洛中逢盧郢石歸覲', '洛中逢盧郢石归覲', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["不堪俱失意，相送出東周。","緣切倚門戀，倍添爲客愁。","春山和雪靜，寒水帶冰流。","別後期君處，靈源紫閣秋。"]', '["不堪俱失意，相送出东周。","緣切倚门戀，倍添爲客愁。","春山和雪静，寒水带冰流。","別後期君处，靈源紫閣秋。"]', '诗', 'shi', '', NULL, '洛中逢盧郢石歸覲 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50e5ef86-c74f-46ff-9adf-c27b7b2e4c8c', '贈越客', '贈越客', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["故國波濤隔，明時心久留。","獻書雙闕晚，看月五陵秋。","南棹何當返，長江憶共遊。","定知釣魚伴，相望在汀州。"]', '["故国波濤隔，明时心久留。","獻书雙闕晚，看月五陵秋。","南棹何當返，长江憶共游。","定知釣鱼伴，相望在汀州。"]', '诗', 'shi', '', NULL, '贈越客 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5684ca6d-deb6-4095-8c06-82a92e2bd47a', '經無錫縣醉後吟', '經無錫縣醉後吟', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["客過無名姓，扁舟繫柳陰。","窮秋南國淚，殘日故鄉心。","京洛衣塵在，江湖酒病深。","何須覓陶令，乘醉自橫琴。"]', '["客過無名姓，扁舟繫柳陰。","窮秋南国泪，殘日故乡心。","京洛衣塵在，江湖酒病深。","何須覓陶令，乘醉自橫琴。"]', '诗', 'shi', '', NULL, '經無錫縣醉後吟 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea4cf60d-9597-42d1-86e4-5fd02035666f', '東歸道中二首 一', '东归道中二首 一', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["平生事行役，今日始知非。","歲月老將至，江湖春未歸。","傳家有天爵，主祭用儒衣。","何必勞知己，無名亦息機。"]', '["平生事行役，今日始知非。","歲月老將至，江湖春未归。","傳家有天爵，主祭用儒衣。","何必勞知己，無名亦息機。"]', '诗', 'shi', '', NULL, '東歸道中二首 一 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2deb36e1-2d84-4980-8e79-99e1a24d5a56', '東歸道中二首 二', '东归道中二首 二', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["未明喚僮僕，江上憶殘春。","風雨落花夜，山川驅馬人。","星星一鏡髮，草草百年身。","此日念前事，滄洲情更親。"]', '["未明喚僮僕，江上憶殘春。","风雨落花夜，山川驱马人。","星星一镜髮，草草百年身。","此日念前事，滄洲情更親。"]', '诗', 'shi', '', NULL, '東歸道中二首 二 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4522bb34-84f7-4f12-8d09-38b25e245d0a', '旅次商山', '旅次商山', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["役役依山水，何曾似問津。","斷崖如避馬，芳樹欲留人。","日夕猿鳥伴，古今京洛塵。","一枝甘已失，辜負故園春。"]', '["役役依山水，何曾似问津。","斷崖如避马，芳樹欲留人。","日夕猿鸟伴，古今京洛塵。","一枝甘已失，辜負故园春。"]', '诗', 'shi', '', NULL, '旅次商山 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46e2a51b-8282-4c12-97b7-1ab20147d9cb', '長洲', '长洲', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["扁舟殊不繫，浩蕩路纔分。","范蠡湖中樹，吳王苑外雲。","悲心人望月，獨夜雁離羣。","明發還驅馬，關城見日曛。"]', '["扁舟殊不繫，浩蕩路纔分。","范蠡湖中樹，吳王苑外云。","悲心人望月，独夜雁離羣。","明發還驱马，关城见日曛。"]', '诗', 'shi', '', NULL, '長洲 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fafdd7ec-8783-4d1f-89b7-4eede7db4601', '江邊', '江邊', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["終日勞車馬，江邊款竹扉。","殘花春浪闊，小酒故人稀。","戍鼓客帆遠，津雲夕照微。","何由兄與弟，俱及暮春歸。"]', '["終日勞车马，江邊款竹扉。","殘花春浪闊，小酒故人稀。","戍鼓客帆远，津云夕照微。","何由兄與弟，俱及暮春归。"]', '诗', 'shi', '', NULL, '江邊 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae61e80c-ef5d-48c9-bd7e-3be34251fbd0', '宿靈巖寺', '宿靈巖寺', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["明月溪頭寺，蟲聲滿橘洲。","倚欄香徑晚，移石太湖秋。","古樹雲歸盡，荒臺水更流。","無人見惆悵，獨上最高樓。"]', '["明月溪头寺，蟲声满橘洲。","倚欄香徑晚，移石太湖秋。","古樹云归尽，荒台水更流。","無人见惆悵，独上最高楼。"]', '诗', 'shi', '', NULL, '宿靈巖寺 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ccc71df-4c60-40d5-ae79-ff570ff78bc2', '越中寺居', '越中寺居', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["遲客疎林下，斜溪小艇通。","野橋連寺月，高竹半樓風。","水靜魚吹浪，枝閑鳥下空。","數峰相向綠，日夕郡城東。"]', '["遲客疎林下，斜溪小艇通。","野橋連寺月，高竹半楼风。","水静鱼吹浪，枝闲鸟下空。","數峰相向綠，日夕郡城东。"]', '诗', 'shi', '', NULL, '越中寺居 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('690b8a03-5007-48c1-8640-5855bd14081e', '贈金剛三藏', '贈金剛三藏', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["心法云無住，流沙歸復來。","錫隨山鳥動，經附海船回。","洗足柳遮寺，坐禪花委苔。","惟將一童子，又欲過天台。"]', '["心法云無住，流沙归复来。","錫隨山鸟动，經附海船回。","洗足柳遮寺，坐禪花委苔。","惟將一童子，又欲過天台。"]', '诗', 'shi', '', NULL, '贈金剛三藏 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c00b5eb-220d-47e6-8a06-74d057ef8365', '長安晚秋', '长安晚秋', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["雲物淒涼拂曙流，漢家宮闕動高秋。","殘星幾點雁橫塞，長笛一聲人倚樓。","紫豔半開籬菊靜，紅衣落盡渚蓮愁。","鱸魚正美不歸去，空戴南冠學楚囚。"]', '["云物淒涼拂曙流，漢家宮闕动高秋。","殘星幾点雁橫塞，长笛一声人倚楼。","紫豔半开籬菊静，紅衣落尽渚蓮愁。","鱸鱼正美不归去，空戴南冠学楚囚。"]', '诗', 'shi', '', NULL, '長安晚秋 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f78bdf71-ee02-4c13-8713-4f62d3c748fd', '齊安早秋', '齊安早秋', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["流年堪惜又堪驚，砧杵風來滿郡城。","高鳥過時秋色動，征帆落處暮雲平。","思家正歎江南景，聽角仍含塞北情。"]', '["流年堪惜又堪驚，砧杵风来满郡城。","高鸟過时秋色动，征帆落处暮云平。","思家正歎江南景，听角仍含塞北情。"]', '诗', 'shi', '', NULL, '齊安早秋 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9cf809e1-2947-4d06-804b-27c4a01583e3', '東望', '东望', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["楚江橫在草堂前，楊柳洲西載酒船。","兩見梨花歸不得，每逢寒食一潸然。","斜陽映閣山當寺，微綠含風月滿川。","同郡故人攀桂盡，把詩吟向泬寥天。"]', '["楚江橫在草堂前，楊柳洲西載酒船。","兩见梨花归不得，每逢寒食一潸然。","斜陽映閣山當寺，微綠含风月满川。","同郡故人攀桂尽，把诗吟向泬寥天。"]', '诗', 'shi', '', NULL, '東望 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea115d6a-234e-4d04-914d-a42e5bd261d1', '長安月夜與友人話故山', '长安月夜與友人話故山', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["宅邊秋水浸苔磯，日日持竿去不歸。","楊柳風多潮未落，蒹葭霜冷雁初飛。","重嘶匹馬吟紅葉，却聽疎鐘憶翠微。","今夜秦城滿樓月，故人相見一沾衣。"]', '["宅邊秋水浸苔磯，日日持竿去不归。","楊柳风多潮未落，蒹葭霜冷雁初飞。","重嘶匹马吟紅葉，却听疎鐘憶翠微。","今夜秦城满楼月，故人相见一沾衣。"]', '诗', 'shi', '', NULL, '長安月夜與友人話故山 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('afade0d6-6e8e-4b1e-854e-a3fb8705aa20', '題橫水驛雙峰院松', '題橫水驛雙峰院松', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["故園溪上雪中別，野館門前雲外逢。","白髮漸多何事苦，清陰長在好相容。","迎風幾拂朝天騎，帶月猶含度嶺鐘。","更憶葛洪丹井畔，數株臨水欲成龍。"]', '["故园溪上雪中別，野館门前云外逢。","白髮漸多何事苦，清陰长在好相容。","迎风幾拂朝天騎，带月猶含度嶺鐘。","更憶葛洪丹井畔，數株臨水欲成龙。"]', '诗', 'shi', '', NULL, '題橫水驛雙峰院松 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd685c23-ce86-40b1-b806-37ebb155034c', '發剡中', '發剡中', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["正懷何謝俯長流，更覽餘封識嵊州。","樹色老依官舍晚，溪聲涼傍客衣秋。","南巖氣爽橫郛郭，天姥雲晴拂寺樓。","日暮不堪還上馬，蓼花風起路悠悠。"]', '["正懷何謝俯长流，更覽餘封識嵊州。","樹色老依官舍晚，溪声涼傍客衣秋。","南巖氣爽橫郛郭，天姥云晴拂寺楼。","日暮不堪還上马，蓼花风起路悠悠。"]', '诗', 'shi', '', NULL, '發剡中 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb131ccc-3dcd-472b-b13f-bcb1d72d89d6', '登安陸西樓', '登安陸西楼', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["樓上華筵日日開，眼前人事祗堪哀。","征車自入紅塵去，遠水長穿綠樹來。","雲雨暗更歌舞伴，山川不盡別離杯。","無由併寫春風恨，欲下鄖城首重回。"]', '["楼上华筵日日开，眼前人事祗堪哀。","征车自入紅塵去，远水长穿綠樹来。","云雨暗更歌舞伴，山川不尽別離杯。","無由併寫春风恨，欲下鄖城首重回。"]', '诗', 'shi', '', NULL, '登安陸西樓 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d654208b-ae8d-4b62-8c21-d2b81192685f', '九日陪越州元相燕龜山寺', '九日陪越州元相燕龟山寺', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["佳晨何處泛花遊，丞相筵開水上頭。","雙影斾搖山雨霽，一聲歌動寺雲秋。","林光靜帶高城晚，湖色寒分半檻流。","共賀萬家逢此節，可憐風物似荆州。"]', '["佳晨何处泛花游，丞相筵开水上头。","雙影斾搖山雨霽，一声歌动寺云秋。","林光静带高城晚，湖色寒分半檻流。","共賀万家逢此節，可怜风物似荆州。"]', '诗', 'shi', '', NULL, '九日陪越州元相燕龜山寺 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43391dcb-30ce-48ab-898e-7ca699a0bf6d', '經漢武泉', '經漢武泉', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["芙蓉苑裏起清秋，漢武泉聲落御溝。","他日江山映蓬鬢，二年楊柳別漁舟。","竹間駐馬題詩去，物外何人識醉遊。","盡把歸心付紅葉，晚來隨水向東流。"]', '["芙蓉苑裏起清秋，漢武泉声落御溝。","他日江山映蓬鬢，二年楊柳別漁舟。","竹间駐马題诗去，物外何人識醉游。","尽把归心付紅葉，晚来隨水向东流。"]', '诗', 'shi', '', NULL, '經漢武泉 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d92ae3aa-8a63-4f1c-bfd8-b19fa3a92c92', '曲江春望懷江南故人', '曲江春望懷江南故人', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["杜若洲邊人未歸，水寒煙暖想柴扉。","故園何處風吹柳，新雁南來雪滿衣。","目極思隨原草遍，浪高書到海門稀。","此時愁望情多少，萬里春流遶釣磯。"]', '["杜若洲邊人未归，水寒煙暖想柴扉。","故园何处风吹柳，新雁南来雪满衣。","目極思隨原草遍，浪高书到海门稀。","此时愁望情多少，万里春流遶釣磯。"]', '诗', 'shi', '', NULL, '曲江春望懷江南故人 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e854f8a4-bcaa-49bd-91e6-d677c815de08', '上令狐相公', '上令狐相公', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["鶚在卿雲冰在壺，代天才業奉訏謨。","榮同伊陟傳朱戶，秀比王商入畫圖。","昨夜星辰回劍履，前年風月滿江湖。","不知機務時多暇，猶許詩家屬和無。"]', '["鶚在卿云冰在壺，代天才業奉訏謨。","榮同伊陟傳朱戶，秀比王商入畫圖。","昨夜星辰回劍履，前年风月满江湖。","不知機務时多暇，猶許诗家屬和無。"]', '诗', 'shi', '', NULL, '上令狐相公 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f782781-8f3c-4ccc-98ae-a719d5e269a9', '憶山陽', '憶山陽', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["家在枚臯舊宅邊，竹軒晴與楚坡連。","芰荷香遶垂鞭袖，楊柳風橫弄笛船。","城礙十洲煙島路，寺臨千頃夕陽川。","可憐時節堪歸去，花落猿啼又一年。"]', '["家在枚臯旧宅邊，竹軒晴與楚坡連。","芰荷香遶垂鞭袖，楊柳风橫弄笛船。","城礙十洲煙島路，寺臨千頃夕陽川。","可怜时節堪归去，花落猿啼又一年。"]', '诗', 'shi', '', NULL, '憶山陽 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6d3789e-3b3c-42a2-b08e-8c44a67b1f26', '二', '二', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["折柳城邊起暮愁，可憐春色獨懷憂。","傷心正歎人間事，回首更慚江上鷗。","鶗鴂聲中寒食雨，芙蓉花外夕陽樓。","憑高滿眼送清渭，去傍故山山下流。"]', '["折柳城邊起暮愁，可怜春色独懷憂。","傷心正歎人间事，回首更慚江上鷗。","鶗鴂声中寒食雨，芙蓉花外夕陽楼。","憑高满眼送清渭，去傍故山山下流。"]', '诗', 'shi', '', NULL, '二 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dec141df-ee86-4131-8ddc-194c82469e7d', '送僧歸廬山', '送僧归廬山', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["禪棲忽憶五峰遊，去著方袍謝列侯。","經啓樓臺千葉曙，錫含風雨一枝秋。","題詩片石侵雲在，洗鉢香泉覆菊流。","却憶前年別師處，馬嘶殘月虎溪頭。"]', '["禪棲忽憶五峰游，去著方袍謝列侯。","經啓楼台千葉曙，錫含风雨一枝秋。","題诗片石侵云在，洗鉢香泉覆菊流。","却憶前年別師处，马嘶殘月虎溪头。"]', '诗', 'shi', '', NULL, '送僧歸廬山 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b47acf7-d4b6-4d70-a7fe-beb79b54c9c8', '贈天卿寺神亮上人', '贈天卿寺神亮上人', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["五看春盡此江濆，花自飄零日自曛。","空有慈悲隨物念，已無蹤跡在人羣。","迎秋日色簷前見，入夜鐘聲竹外聞。","笑指白蓮心自得，世間煩惱是浮雲。"]', '["五看春尽此江濆，花自飄零日自曛。","空有慈悲隨物念，已無蹤跡在人羣。","迎秋日色簷前见，入夜鐘声竹外闻。","笑指白蓮心自得，世间煩惱是浮云。"]', '诗', 'shi', '', NULL, '贈天卿寺神亮上人 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('307d584e-b839-4f4c-a11e-708bbf515eee', '降虜', '降虜', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["廣武溪頭降虜稀，一聲寒角怨金微。","河湟不在春風地，歌舞空裁雪夜衣。","鐵馬半嘶邊草去，狼煙高映塞鴻飛。","揚雄尚白相如吃，今日何人從獵歸。"]', '["廣武溪头降虜稀，一声寒角怨金微。","河湟不在春风地，歌舞空裁雪夜衣。","鐵马半嘶邊草去，狼煙高映塞鴻飞。","揚雄尚白相如吃，今日何人從獵归。"]', '诗', 'shi', '', NULL, '降虜 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec639249-6714-4af1-8451-1670adb37227', '平戎', '平戎', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["邊聲一夜殷秋鼙，牙帳連烽擁萬蹄。","武帝未能忘塞北，董生纔足使膠西。","冰橫曉渡胡兵合，雪滿窮沙漢騎迷。","自古平戎有良策，將軍不用倚雲梯。"]', '["邊声一夜殷秋鼙，牙帳連烽擁万蹄。","武帝未能忘塞北，董生纔足使膠西。","冰橫晓渡胡兵合，雪满窮沙漢騎迷。","自古平戎有良策，將軍不用倚云梯。"]', '诗', 'shi', '', NULL, '平戎 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23f92364-8920-49e3-9b7f-d9c70cfcbf95', '宿楚國寺有懷', '宿楚国寺有懷', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["風動衰荷寂寞香，斷煙殘月共蒼蒼。","寒生晚寺波搖壁，紅墮疎林葉滿牀。","起雁似驚南浦棹，陰雲欲護北樓霜。","江邊松菊荒應盡，八月長安夜正長。"]', '["风动衰荷寂寞香，斷煙殘月共蒼蒼。","寒生晚寺波搖壁，紅墮疎林葉满牀。","起雁似驚南浦棹，陰云欲護北楼霜。","江邊松菊荒應尽，八月长安夜正长。"]', '诗', 'shi', '', NULL, '宿楚國寺有懷 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e2b1384-6bb1-43ae-b12f-447998c8b84a', '早發剡中石城寺', '早發剡中石城寺', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["暫息勞生樹色間，平明機慮又相關。","吟辭宿處煙霞去，心負秋來水石閒。","竹戶半開鐘未絕，松枝靜霽鶴初還。","明朝一倍堪惆悵，回首塵中見此山。"]', '["暫息勞生樹色间，平明機慮又相关。","吟辞宿处煙霞去，心負秋来水石閒。","竹戶半开鐘未絕，松枝静霽鹤初還。","明朝一倍堪惆悵，回首塵中见此山。"]', '诗', 'shi', '', NULL, '早發剡中石城寺 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4f8653d-f4d9-4668-9df6-b164483cc8ea', '寄歸', '寄归', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["三年踏盡化衣塵，只見長安不見春。","馬過雪街天未曙，客迷關路淚空頻。","桃花塢接啼猿寺，野竹庭通畫鷁津。","早晚相酬身事了，水邊歸去一閒人。"]', '["三年踏尽化衣塵，只见长安不见春。","马過雪街天未曙，客迷关路泪空頻。","桃花塢接啼猿寺，野竹庭通畫鷁津。","早晚相酬身事了，水邊归去一閒人。"]', '诗', 'shi', '', NULL, '寄歸 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8c6d737-9301-4233-91d1-2f031b753f08', '獻淮南李相公', '獻淮南李相公', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["傅巖高靜見台星，廟畧當時討不庭。","萬里有雲歸碧落，百川無浪到滄溟。","軍中老將傳兵術，江上諸侯受政經。","聞道國人思再入，鎔金新鑄鶴儀形。"]', '["傅巖高静见台星，廟畧當时討不庭。","万里有云归碧落，百川無浪到滄溟。","軍中老將傳兵術，江上諸侯受政經。","闻道国人思再入，鎔金新鑄鹤儀形。"]', '诗', 'shi', '', NULL, '獻淮南李相公 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7109d871-873f-4c45-a1a1-77e694702be5', '宛陵寓居上沈大夫二首 一', '宛陵寓居上沈大夫二首 一', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["滿耳歌謠滿眼山，宛陵城郭翠微間。","人情已覺春長在，溪戶仍將水共閒。","曉色入樓紅藹藹，夜聲尋砌碧潺潺。","幽雲高鳥俱無事，晚伴西風醉客還。"]', '["满耳歌謠满眼山，宛陵城郭翠微间。","人情已覺春长在，溪戶仍將水共閒。","晓色入楼紅藹藹，夜声尋砌碧潺潺。","幽云高鸟俱無事，晚伴西风醉客還。"]', '诗', 'shi', '', NULL, '宛陵寓居上沈大夫二首 一 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56c3e46b-4df7-4303-86c8-37e7ffd3b9ad', '宛陵寓居上沈大夫二首 二', '宛陵寓居上沈大夫二首 二', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["溪樹參差綠可攀，謝家雲水滿東山。","能忘天上他年貴，來結林中一日閒。","醉叩玉盤歌褭褭，暖鳴幽澗鳥關關。","觥籌不盡須歸去，路在春風縹緲間。"]', '["溪樹參差綠可攀，謝家云水满东山。","能忘天上他年貴，来結林中一日閒。","醉叩玉盤歌褭褭，暖鳴幽澗鸟关关。","觥籌不尽須归去，路在春风縹緲间。"]', '诗', 'shi', '', NULL, '宛陵寓居上沈大夫二首 二 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45b15ad4-1038-4d60-b99a-7f9ef2b9c4c7', '淮信賀滕邁台州', '淮信賀滕邁台州', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["凋瘵民思太古風，上賢綏輯副宸衷。","舟移清鏡禹祠北，路轉翠屏天姥東。","旌斾影前橫竹馬，詠歌聲裏樂樵童。","遙知到郡滄波晏，三島離離一望中。"]', '["凋瘵民思太古风，上賢綏輯副宸衷。","舟移清镜禹祠北，路轉翠屏天姥东。","旌斾影前橫竹马，詠歌声裏乐樵童。","遙知到郡滄波晏，三島離離一望中。"]', '诗', 'shi', '', NULL, '淮信賀滕邁台州 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('add078e7-486f-4602-87d3-3e5948303cdd', '下第寄宣城幕中諸公', '下第寄宣城幕中諸公', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["一醉曾將萬事齊，暫陪歡去便如泥。","黃花李白墓前路，碧浪桓彝宅後溪。","九月霜中隨計吏，十年江上灌春畦。","莫言春盡不惆悵，自有閒眠到日西。"]', '["一醉曾將万事齊，暫陪歡去便如泥。","黄花李白墓前路，碧浪桓彝宅後溪。","九月霜中隨計吏，十年江上灌春畦。","莫言春尽不惆悵，自有閒眠到日西。"]', '诗', 'shi', '', NULL, '下第寄宣城幕中諸公 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38323138-3009-48f3-851b-0b8eee404c58', '送令狐郎中赴郢州', '送令狐郎中赴郢州', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["佐幕才多始拜侯，一門清貴動神州。","霜蹄曉駐秦雲斷，野斾晴翻郢樹秋。","幾處塵生隨候騎，半江帆盡見分流。","大馮罷相吟詩地，莫惜頻登白雪樓。"]', '["佐幕才多始拜侯，一门清貴动神州。","霜蹄晓駐秦云斷，野斾晴翻郢樹秋。","幾处塵生隨候騎，半江帆尽见分流。","大馮罷相吟诗地，莫惜頻登白雪楼。"]', '诗', 'shi', '', NULL, '送令狐郎中赴郢州 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e0c08a0-faf0-483e-a682-b5e8f4b82d38', '送盧緘歸揚州', '送盧緘归揚州', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["曾向雷塘寄掩扉，荀家燈火有餘輝。","關河日暮望空極，楊柳渡頭人獨歸。","隋苑荒臺風褭褭，灞陵殘雨夢依依。","今年春色還相悞，爲我江邊謝釣磯。"]', '["曾向雷塘寄掩扉，荀家灯火有餘輝。","关河日暮望空極，楊柳渡头人独归。","隋苑荒台风褭褭，灞陵殘雨梦依依。","今年春色還相悞，爲我江邊謝釣磯。"]', '诗', 'shi', '', NULL, '送盧緘歸揚州 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9b37602-b2a6-44d5-9d33-2eb7d40266f7', '送李裴評事', '送李裴評事', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["塞垣從事識兵機，只擬平戎不擬歸。","入夜笳聲含白髮，報秋榆葉落征衣。","城臨戰壘黃雲晚，馬渡寒沙夕照微。","此別不應書斷絕，滿天霜雪有鴻飛。"]', '["塞垣從事識兵機，只擬平戎不擬归。","入夜笳声含白髮，報秋榆葉落征衣。","城臨戰壘黄云晚，马渡寒沙夕照微。","此別不應书斷絕，满天霜雪有鴻飞。"]', '诗', 'shi', '', NULL, '送李裴評事 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d96ab8f4-d899-42fc-a251-261b08c09eea', '別麻氏', '別麻氏', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["曉哭呱呱動四隣，于君我作負心人。","出門便涉東西路，回首初驚枕席塵。","滿眼淚珠和語咽，舊窗風月更誰親。","分離況值花時節，從此東風不似春。"]', '["晓哭呱呱动四隣，于君我作負心人。","出门便涉东西路，回首初驚枕席塵。","满眼泪珠和語咽，旧窗风月更誰親。","分離況值花时節，從此东风不似春。"]', '诗', 'shi', '', NULL, '別麻氏 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12b7bac3-a96f-4d07-a287-6bc8c02a5887', '代人贈別', '代人贈別', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["月自斜窗夢自驚，衷腸中有萬愁生。","清猿處處三聲盡，碧落悠悠一水橫。","平子定情詞麗絕，詩人匪石誓分明。","會須攜手乘鸞去，簫史樓臺在玉京。"]', '["月自斜窗梦自驚，衷腸中有万愁生。","清猿处处三声尽，碧落悠悠一水橫。","平子定情词丽絕，诗人匪石誓分明。","會須携手乘鸾去，簫史楼台在玉京。"]', '诗', 'shi', '', NULL, '代人贈別 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('248db898-c5cc-48a0-b6a9-eed682ac3e75', '寒食新豐別友人', '寒食新豐別友人', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["一百五日家未歸，新豐雞犬獨依依。","滿樓春色傍人醉，半夜雨聲前計非。","繚繞溝塍含綠晚，荒涼樹石向川微。","東風吹淚對花落，憔悴故交相見稀。"]', '["一百五日家未归，新豐雞犬独依依。","满楼春色傍人醉，半夜雨声前計非。","繚繞溝塍含綠晚，荒涼樹石向川微。","东风吹泪对花落，憔悴故交相见稀。"]', '诗', 'shi', '', NULL, '寒食新豐別友人 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f45078c0-53c5-465b-8678-bb2b97da0413', '李侍御歸山同宿華嚴寺', '李侍御归山同宿华嚴寺', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["家有青山近玉京，風流柱史早知名。","園林手植自含綠，霄漢眼看當去程。","處處白雲迷駐馬，家家紅樹近流鶯。","相逢一宿最高寺，夜夜翠微泉落聲。"]', '["家有青山近玉京，风流柱史早知名。","园林手植自含綠，霄漢眼看當去程。","处处白云迷駐马，家家紅樹近流鶯。","相逢一宿最高寺，夜夜翠微泉落声。"]', '诗', 'shi', '', NULL, '李侍御歸山同宿華嚴寺 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6cd87e3-70ae-4eec-b61e-854434eb0c92', '今年新先輩以遏密之際每有讌集必資清談書此奉賀', '今年新先輩以遏密之際每有讌集必資清談书此奉賀', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["天上高高月桂叢，分明三十一枝風。","滿懷春色向人動，遮路亂花迎馬紅。","鶴馭迴飄雲雨外，蘭亭不在管絃中。","居然自是前賢事，何必青樓倚翠空。"]', '["天上高高月桂叢，分明三十一枝风。","满懷春色向人动，遮路亂花迎马紅。","鹤馭迴飄云雨外，蘭亭不在管絃中。","居然自是前賢事，何必青楼倚翠空。"]', '诗', 'shi', '', NULL, '今年新先輩以遏密之際每有讌集必資清談書此奉賀 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f9739d7-4af2-46a6-ba68-3891e083f3af', '自遣', '自遣', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["晚樹疎蟬起別愁，遠人回首憶滄洲。","江連故國無窮恨，日帶殘雲一片秋。","久客轉諳時態薄，多情只共酒淹留。","到頭生長煙霞者，須向煙霞老始休。"]', '["晚樹疎蟬起別愁，远人回首憶滄洲。","江連故国無窮恨，日带殘云一片秋。","久客轉諳时態薄，多情只共酒淹留。","到头生长煙霞者，須向煙霞老始休。"]', '诗', 'shi', '', NULL, '自遣 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b6e8726-4351-4c95-b2a1-450b20181604', '浙東陪元相公遊雲門寺', '浙东陪元相公游云门寺', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["松下山前一徑通，燭迎千騎滿山紅。","溪雲乍歛幽巖雨，曉氣初高大斾風。","小檻宴花容客醉，上方看竹與僧同。","歸來吹盡嚴城角，路轉橫塘亂水東。"]', '["松下山前一徑通，燭迎千騎满山紅。","溪云乍歛幽巖雨，晓氣初高大斾风。","小檻宴花容客醉，上方看竹與僧同。","归来吹尽嚴城角，路轉橫塘亂水东。"]', '诗', 'shi', '', NULL, '浙東陪元相公遊雲門寺 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0c73b27-7c27-4af7-9ffc-1b526ada9f03', '陪韋中丞宴扈都頭花園', '陪韋中丞宴扈都头花园', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["門下煙橫載酒船，謝家攜客醉華筵。","尋花偶坐將軍樹，飲水方重刺史天。","幾曲豔歌春色裏，斷行高鳥暮雲邊。","分明聽得輿人語，願及行春更一年。"]', '["门下煙橫載酒船，謝家携客醉华筵。","尋花偶坐將軍樹，饮水方重刺史天。","幾曲豔歌春色裏，斷行高鸟暮云邊。","分明听得輿人語，願及行春更一年。"]', '诗', 'shi', '', NULL, '陪韋中丞宴扈都頭花園 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dfab9241-05d2-496c-81ab-be6e173d6e3d', '花園即事呈常中丞', '花园即事呈常中丞', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["煙煖池塘柳覆臺，百花園裏看花來。","燒衣焰席三千樹，破鼻醒愁一萬杯。","不肯爲歌隨拍落，却因令舞帶香迴。","山公仰爾延賓客，好傍春風次第開。"]', '["煙煖池塘柳覆台，百花园裏看花来。","燒衣焰席三千樹，破鼻醒愁一万杯。","不肯爲歌隨拍落，却因令舞带香迴。","山公仰爾延賓客，好傍春风次第开。"]', '诗', 'shi', '', NULL, '花園即事呈常中丞 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b40e046-40a9-4736-b39d-5edbe81a8288', '宿何書記先輩延福新居', '宿何书記先輩延福新居', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["松下有琴閑未收，一燈高爲石叢留。","詩情似到山家夜，樹色輕含御水秋。","小榼提攜終永日，半斑容鬢漫生愁。","因君撫掌問時俗，紫閣堆簷不舉頭。"]', '["松下有琴闲未收，一灯高爲石叢留。","诗情似到山家夜，樹色轻含御水秋。","小榼提携終永日，半斑容鬢漫生愁。","因君撫掌问时俗，紫閣堆簷不舉头。"]', '诗', 'shi', '', NULL, '宿何書記先輩延福新居 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d459b23-682a-4d1e-8734-1435a0089730', '秦中逢王處士', '秦中逢王处士', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["萬水東流去不迴，先生獨自負仙才。","蘂宮橫浪海邊別，鶴翅駐雲天上來。","幾處吹簫森羽衛，誰家殘月下樓臺。","春風正好分瓊液，乞取當時白玉杯。"]', '["万水东流去不迴，先生独自負仙才。","蘂宮橫浪海邊別，鹤翅駐云天上来。","幾处吹簫森羽衛，誰家殘月下楼台。","春风正好分瓊液，乞取當时白玉杯。"]', '诗', 'shi', '', NULL, '秦中逢王處士 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f90c14b-26a6-4ba0-bf1d-f457599f4b48', '江上逢許逸人', '江上逢許逸人', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["是非處處生塵埃，唯君襟抱無嫌猜。","收帆依雁湓浦宿，帶雨別僧衡嶽迴。","芳罇稍駐落日唱，醉袖更拂長雲開。","清秋華髮好相似，却把釣竿歸去來。"]', '["是非处处生塵埃，唯君襟抱無嫌猜。","收帆依雁湓浦宿，带雨別僧衡嶽迴。","芳罇稍駐落日唱，醉袖更拂长云开。","清秋华髮好相似，却把釣竿归去来。"]', '诗', 'shi', '', NULL, '江上逢許逸人 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86c257e7-faed-4e51-a543-9e1e16f7d3dd', '和令狐補闕春日獨遊西街', '和令狐補闕春日独游西街', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["左掖初辭近侍班，馬嘶尋得過街閑。","映鞭柳色微遮水，隨步花枝欲礙山。","暖泛鳥聲來席上，醉從詩句落人間。","此時失意哀吟客，更覺風流不可攀。"]', '["左掖初辞近侍班，马嘶尋得過街闲。","映鞭柳色微遮水，隨步花枝欲礙山。","暖泛鸟声来席上，醉從诗句落人间。","此时失意哀吟客，更覺风流不可攀。"]', '诗', 'shi', '', NULL, '和令狐補闕春日獨遊西街 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70e4febc-6541-4809-a89c-29c5dcbea490', '廣陵答崔琛', '廣陵答崔琛', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["棹倚隋家舊院墻，柳金梅雪撲簷香。","朱樓映日重重晚，碧水含光灩灩長。","八斗已聞傳姓字，一枝何足計行藏。","聲名官職應前定，且把旌麾入醉鄉。"]', '["棹倚隋家旧院墻，柳金梅雪撲簷香。","朱楼映日重重晚，碧水含光灩灩长。","八斗已闻傳姓字，一枝何足計行藏。","声名官職應前定，且把旌麾入醉乡。"]', '诗', 'shi', '', NULL, '廣陵答崔琛 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa22703c-5da1-4b6e-8b05-968dedc109cc', '答友人', '答友人', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["詩家才子酒家仙，遊宦曾依積水邊。","窗戶動搖三島樹，琴尊安穩五湖船。","羅浮道士分瓊液，錦席佳人豔楚蓮。","今日相逢朗吟罷，滿城砧杵一燈前。"]', '["诗家才子酒家仙，游宦曾依積水邊。","窗戶动搖三島樹，琴尊安穩五湖船。","羅浮道士分瓊液，錦席佳人豔楚蓮。","今日相逢朗吟罷，满城砧杵一灯前。"]', '诗', 'shi', '', NULL, '答友人 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2be3378c-691c-41a1-914b-1e4b417d7bf4', '送張又新除溫州', '送張又新除溫州', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["東晉江山稱永嘉，莫辭紅斾向天涯。","凝絃夜醉松亭月，歇馬曉尋溪寺花。","地與剡川分水石，境將蓬島共煙霞。","却愁明詔徵非晚，不得秋來見海槎。"]', '["东晉江山稱永嘉，莫辞紅斾向天涯。","凝絃夜醉松亭月，歇马晓尋溪寺花。","地與剡川分水石，境將蓬島共煙霞。","却愁明詔徵非晚，不得秋来见海槎。"]', '诗', 'shi', '', NULL, '送張又新除溫州 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('023b37fe-fa4a-4bc7-8f9d-56c46966edae', '送滕邁郎中赴睦州', '送滕邁郎中赴睦州', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["郡齋秋盡一江橫，頻命郎官地更清。","星月去隨新詔動，旌旗遙映故山明。","詩尋片石依依晚，帆挂孤雲杳杳輕。","想到釣臺逢竹馬，只應歌詠伴猿聲。"]', '["郡斋秋尽一江橫，頻命郎官地更清。","星月去隨新詔动，旌旗遙映故山明。","诗尋片石依依晚，帆挂孤云杳杳轻。","想到釣台逢竹马，只應歌詠伴猿声。"]', '诗', 'shi', '', NULL, '送滕邁郎中赴睦州 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a123f5b-5525-4a18-9487-8a556d84ae55', '送剡客', '送剡客', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["兩重江外片帆斜，數里林塘遶一家。","門掩右軍餘水石，路橫諸謝舊煙霞。","扁舟幾處逢溪雪，長笛何人怨柳花。","若到天台洞陽觀，葛洪丹井在雲涯。"]', '["兩重江外片帆斜，數里林塘遶一家。","门掩右軍餘水石，路橫諸謝旧煙霞。","扁舟幾处逢溪雪，长笛何人怨柳花。","若到天台洞陽观，葛洪丹井在云涯。"]', '诗', 'shi', '', NULL, '送剡客 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f690b93a-075c-47b6-8ced-efb42f55cb90', '李先輩擢第東歸有贈送', '李先輩擢第东归有贈送', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["金榜前頭無是非，平人分得一枝歸。","正憐日煖雲飄路，何處宴迴風滿衣？","門掩長淮心更遠，渡連芳草馬如飛。","茂陵自笑猶多病，空有書齋在翠微。"]', '["金榜前头無是非，平人分得一枝归。","正怜日煖云飄路，何处宴迴风满衣？","门掩长淮心更远，渡連芳草马如飞。","茂陵自笑猶多病，空有书斋在翠微。"]', '诗', 'shi', '', NULL, '李先輩擢第東歸有贈送 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2347547e-3d3e-42a4-a21d-b5719416ae18', '送同年鄭祥先輩歸漢南', '送同年鄭祥先輩归漢南', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["年來驚喜兩心知，高處同攀次第枝。","人倚繡屏閑賞夜，馬嘶花徑醉歸時。","聲名本是文章得，藩閫曾勞筆硯隨。","家去恩門四千里，只應從此夢旌旗。"]', '["年来驚喜兩心知，高处同攀次第枝。","人倚繡屏闲賞夜，马嘶花徑醉归时。","声名本是文章得，藩閫曾勞笔硯隨。","家去恩门四千里，只應從此梦旌旗。"]', '诗', 'shi', '', NULL, '送同年鄭祥先輩歸漢南 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9ab718a-6cf2-4b9e-a6d7-8e6f79254e26', '送沈單作尉江都', '送沈單作尉江都', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["煬帝都城春水邊，笙歌夜上木蘭船。","三千宮女自塗地，十萬人家如洞天。","焰焰花枝官舍晚，重重雲影寺墻連。","少年作尉須矜慎，莫向樓前墜馬鞭。"]', '["煬帝都城春水邊，笙歌夜上木蘭船。","三千宮女自塗地，十万人家如洞天。","焰焰花枝官舍晚，重重云影寺墻連。","少年作尉須矜慎，莫向楼前墜马鞭。"]', '诗', 'shi', '', NULL, '送沈單作尉江都 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39e35ec5-7dfb-458b-81d4-0c4efb54706c', '送李蘊赴鄭州因獻盧郎中俶', '送李蘊赴鄭州因獻盧郎中俶', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["僕射陂西想到時，滿川晴色見旌旗。","馬融閑臥笛聲遠，王粲醉吟樓影移。","幾日賦詩秋水寺，經年草詔白雲司。","唯君此去人多羨，却是恩深自不知。"]', '["僕射陂西想到时，满川晴色见旌旗。","马融闲臥笛声远，王粲醉吟楼影移。","幾日賦诗秋水寺，經年草詔白云司。","唯君此去人多羨，却是恩深自不知。"]', '诗', 'shi', '', NULL, '送李蘊赴鄭州因獻盧郎中俶 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6b1ba77-fee7-4750-a37e-42f0676f1e66', '送韓絳歸淮南寄韓綽先輩', '送韓絳归淮南寄韓綽先輩', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["島上花枝繫釣船，隋家宮畔水連天。","江帆自落鳥飛外，月觀靜依春色邊。","門巷草生車轍在，朝廷恩及雁行聯。","相逢且問昭州事，曾鼓莊盆對逝川。"]', '["島上花枝繫釣船，隋家宮畔水連天。","江帆自落鸟飞外，月观静依春色邊。","门巷草生车轍在，朝廷恩及雁行聯。","相逢且问昭州事，曾鼓莊盆对逝川。"]', '诗', 'shi', '', NULL, '送韓絳歸淮南寄韓綽先輩 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26a53744-e898-418d-9766-7156ec45c03a', '送薛耽先輩歸謁漢南', '送薛耽先輩归謁漢南', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["雲繞千峰驛路長，謝家聯句待檀郎。","手持碧落新攀桂，月在東軒舊選牀。","幾日旌幢延駿馬，到時冰玉動華堂。","孔門多少風流處，不遣顏回識醉鄉。"]', '["云繞千峰驛路长，謝家聯句待檀郎。","手持碧落新攀桂，月在东軒旧選牀。","幾日旌幢延駿马，到时冰玉动华堂。","孔门多少风流处，不遣顏回識醉乡。"]', '诗', 'shi', '', NULL, '送薛耽先輩歸謁漢南 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bddcc5c2-70c6-4669-9a1e-abe08ba0489e', '送陳嘏登第作尉歸覲', '送陳嘏登第作尉归覲', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["千峰歸去舊林塘，溪縣門前即故鄉。","曾把桂誇春里巷，重憐身稱錦衣裳。","洲迷翠羽雲遮檻，露濕紅蕉月滿廊。","就養舉朝人共羨，清資讓却校書郎。"]', '["千峰归去旧林塘，溪縣门前即故乡。","曾把桂誇春里巷，重怜身稱錦衣裳。","洲迷翠羽云遮檻，露濕紅蕉月满廊。","就養舉朝人共羨，清資讓却校书郎。"]', '诗', 'shi', '', NULL, '送陳嘏登第作尉歸覲 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02c1d955-fd23-4b83-9af5-e92df0c462ee', '送裴延翰下第歸覲滁州', '送裴延翰下第归覲滁州', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["失意何曾恨解攜，問安歸去秣陵西。","郡斜楊柳春風岸，山映樓臺明月溪。","江上詩書懸素業，日邊門戶倚丹梯。","一枝攀折回頭是，莫向清秋惜馬蹄。"]', '["失意何曾恨解携，问安归去秣陵西。","郡斜楊柳春风岸，山映楼台明月溪。","江上诗书懸素業，日邊门戶倚丹梯。","一枝攀折回头是，莫向清秋惜马蹄。"]', '诗', 'shi', '', NULL, '送裴延翰下第歸覲滁州 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d59a4f22-98aa-4d54-93a8-58bc761bd066', '題崇聖寺簡雲端僧錄', '題崇聖寺簡云端僧錄', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["暮塵飄盡客愁長，來扣禪關月滿廊。","宋玉逢秋空雪涕，淨名無地可容牀。","高雲覆檻千巖樹，疎磬含風一夜霜。","回首故園紅葉外，只將多病告醫王。"]', '["暮塵飄尽客愁长，来扣禪关月满廊。","宋玉逢秋空雪涕，淨名無地可容牀。","高云覆檻千巖樹，疎磬含风一夜霜。","回首故园紅葉外，只將多病告醫王。"]', '诗', 'shi', '', NULL, '題崇聖寺簡雲端僧錄 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21709e78-e494-49ab-b445-14410d174796', '越中寺居寄上主人', '越中寺居寄上主人', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["野寺初容訪靜來，晚晴江上見樓臺。","中林有路到花盡，一日無人看竹迴。","自曬詩書經雨後，別留門戶爲僧開。","苦心若是酬恩事，不敢吟春憶酒杯。"]', '["野寺初容訪静来，晚晴江上见楼台。","中林有路到花尽，一日無人看竹迴。","自曬诗书經雨後，別留门戶爲僧开。","苦心若是酬恩事，不敢吟春憶酒杯。"]', '诗', 'shi', '', NULL, '越中寺居寄上主人 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65354c7f-8518-482d-b69a-f2b2b306dd3e', '早出洞仙觀', '早出洞仙观', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["露濃如水灑蒼苔，洞口煙蘿密不開。","殘月色低當戶後，曉鐘聲逈隔山來。","春生藥圃芝猶短，夜醮齋壇鶴未迴。","愁是獨尋歸路去，人間步步是塵埃。"]', '["露濃如水灑蒼苔，洞口煙蘿密不开。","殘月色低當戶後，晓鐘声逈隔山来。","春生藥圃芝猶短，夜醮斋壇鹤未迴。","愁是独尋归路去，人间步步是塵埃。"]', '诗', 'shi', '', NULL, '早出洞仙觀 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8dd06c4e-59ce-4c65-bbc4-6c01026b0f0b', '題昭應王明府溪亭', '題昭應王明府溪亭', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["靖節何須彭澤逢，菊洲松島水悠溶。","行人自折門前柳，高鳥不離溪畔峰。","曉渭度簷帆的的，晚原含雨樹重重。","軒車過盡無公事，枕上一聲長樂鐘。"]', '["靖節何須彭澤逢，菊洲松島水悠溶。","行人自折门前柳，高鸟不離溪畔峰。","晓渭度簷帆的的，晚原含雨樹重重。","軒车過尽無公事，枕上一声长乐鐘。"]', '诗', 'shi', '', NULL, '題昭應王明府溪亭 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('228f838e-18e4-4983-a185-57c93643867f', '贈王先生', '贈王先生', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["太一真人隱翠霞，早年曾降蔡經家。","羽衣使者峭於鶴，鳥爪侍娘飄若花。","九鼎欄干歸馬齒，三山窕窈步雲涯。","時因弟子偷靈藥，散落人間駐物華。"]', '["太一真人隐翠霞，早年曾降蔡經家。","羽衣使者峭於鹤，鸟爪侍娘飄若花。","九鼎欄干归马齒，三山窕窈步云涯。","时因弟子偷靈藥，散落人间駐物华。"]', '诗', 'shi', '', NULL, '贈王先生 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e050d8e2-333b-4bf1-a4c7-c06e2af93116', '贈道者', '贈道者', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["華蓋飄飄綠鬢翁，往來朝謁蘂珠宮。","幾年山下陰陽鼎，盡日澗邊桃李風。","野跡似雲無處著，仙容如水與誰同。","應憐有客外妻子，思在長生一顧中。"]', '["华蓋飄飄綠鬢翁，往来朝謁蘂珠宮。","幾年山下陰陽鼎，尽日澗邊桃李风。","野跡似云無处著，仙容如水與誰同。","應怜有客外妻子，思在长生一顧中。"]', '诗', 'shi', '', NULL, '贈道者 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('256134eb-9636-4d33-96af-cae6ec56a121', '王先生不別而去', '王先生不別而去', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["仙翁歸袖拂煙霓，一卷素書還獨攜。","劚藥滿囊身不病，抱琴何處鶴同棲？","霑衣盡日看山坐，搔首殘春向路迷。","樹樹白雲幽徑絕，短船空倚武陵溪。"]', '["仙翁归袖拂煙霓，一卷素书還独携。","劚藥满囊身不病，抱琴何处鹤同棲？","霑衣尽日看山坐，搔首殘春向路迷。","樹樹白云幽徑絕，短船空倚武陵溪。"]', '诗', 'shi', '', NULL, '王先生不別而去 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe6a66ee-688b-4fd2-98a8-78a10bb77134', '山陽盧明府以雙鶴寄遺白氏以詩回答因寄和', '山陽盧明府以雙鹤寄遺白氏以诗回答因寄和', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["緱山雙去羽翰輕，應爲仙家好弟兄。","茅固枕前秋對舞，陸雲溪上夜同鳴。","紫泥封處曾回首，碧落歸時莫問程。","自笑滄江一漁叟，何由似爾到層城。"]', '["緱山雙去羽翰轻，應爲仙家好弟兄。","茅固枕前秋对舞，陸云溪上夜同鳴。","紫泥封处曾回首，碧落归时莫问程。","自笑滄江一漁叟，何由似爾到層城。"]', '诗', 'shi', '', NULL, '山陽盧明府以雙鶴寄遺白氏以詩回答因寄和 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('884f2266-b4af-4c36-8dbe-e3658e5cc46a', '贈李秘書', '贈李秘书', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["束帶臨風氣調新，孔門才業獨誰倫。","杉松韻冷雪溪暗，鸞鶴勢高天路春。","美玉韞來休問價，芳枝攀去正無塵。","莫將芸閣輕科第，須作人間第一人。"]', '["束带臨风氣調新，孔门才業独誰倫。","杉松韻冷雪溪暗，鸾鹤勢高天路春。","美玉韞来休问價，芳枝攀去正無塵。","莫將芸閣轻科第，須作人间第一人。"]', '诗', 'shi', '', NULL, '贈李秘書 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e92e9d5-e384-480c-9a59-1521d47c28a3', '迴於道中寄舒州李珏相公', '迴於道中寄舒州李珏相公', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["都無鄙吝隔塵埃，昨日丘門避席來。","靜語乍臨清廟瑟，披風如在九層臺。","幾煩命妓浮溪棹，再許論詩注酒杯。","從此微塵知感戀，七真臺上望三台。"]', '["都無鄙吝隔塵埃，昨日丘门避席来。","静語乍臨清廟瑟，披风如在九層台。","幾煩命妓浮溪棹，再許論诗注酒杯。","從此微塵知感戀，七真台上望三台。"]', '诗', 'shi', '', NULL, '迴於道中寄舒州李珏相公 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cbead6b6-992c-4c90-a631-93ecfe2d31a2', '舒州獻李相公', '舒州獻李相公', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["野人留得五湖船，丞相興歌郡國年。","醉筆倚風飄澗雪，靜襟披月坐樓天。","鶴歸華表山河在，氣返青雲雨露全。","聞說萬方思舊德，一時傾望重陶甄。"]', '["野人留得五湖船，丞相兴歌郡国年。","醉笔倚风飄澗雪，静襟披月坐楼天。","鹤归华表山河在，氣返青云雨露全。","闻说万方思旧德，一时傾望重陶甄。"]', '诗', 'shi', '', NULL, '舒州獻李相公 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('275b88fc-4319-4748-a9e8-b763024d50e2', '成名年獻座主僕射兼呈同年', '成名年獻座主僕射兼呈同年', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["拂煙披月羽毛新，千里初辭九陌塵。","曾失玄珠求[象罔]，不將雙耳負伶倫。","賈嵩詞賦相如手，楊乘歌篇李白身。","除却今年仙侶外，堂堂又見兩三春。"]', '["拂煙披月羽毛新，千里初辞九陌塵。","曾失玄珠求[象罔]，不將雙耳負伶倫。","賈嵩词賦相如手，楊乘歌篇李白身。","除却今年仙侶外，堂堂又见兩三春。"]', '诗', 'shi', '', NULL, '成名年獻座主僕射兼呈同年 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66aa669c-304d-41c4-b4ac-59a90328149b', '抒懷上歙州盧中丞宣州杜侍郎', '抒懷上歙州盧中丞宣州杜侍郎', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["東來珠履與旌旗，前者登朝亦一時。","竹馬迎呼逢稚子，柏臺長告見男兒。","花飄舞袖樓相倚，角送歸軒客盡隨。","獨有賤夫懷感激，十年兩地負恩知。"]', '["东来珠履與旌旗，前者登朝亦一时。","竹马迎呼逢稚子，柏台长告见男兒。","花飄舞袖楼相倚，角送归軒客尽隨。","独有賤夫懷感激，十年兩地負恩知。"]', '诗', 'shi', '', NULL, '抒懷上歙州盧中丞宣州杜侍郎 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d526273-3e89-4d5e-8f89-5ed442ecfccd', '山陽韋中丞罷郡因獻', '山陽韋中丞罷郡因獻', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["笙歌只是舊笙歌，腸斷風流奈別何。","照物二年春色在，感恩千室淚痕多。","盡將魂夢隨西去，猶望旌旗暫一過。","今日尊前無限思，萬重雲月隔煙波。"]', '["笙歌只是旧笙歌，腸斷风流奈別何。","照物二年春色在，感恩千室泪痕多。","尽將魂梦隨西去，猶望旌旗暫一過。","今日尊前無限思，万重云月隔煙波。"]', '诗', 'shi', '', NULL, '山陽韋中丞罷郡因獻 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('008ee9a3-bded-4277-b1fb-abed94d1c941', '山陽即席獻裴中丞', '山陽即席獻裴中丞', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["早年天上見清塵，今日樓中醉一春。","暫肯剖符臨水石，幾曾焚筆動星辰。","瓊臺雪映迢迢鶴，蓬島波橫浩浩津。","好是仙家羽衣使，欲敎垂涕問何人。"]', '["早年天上见清塵，今日楼中醉一春。","暫肯剖符臨水石，幾曾焚笔动星辰。","瓊台雪映迢迢鹤，蓬島波橫浩浩津。","好是仙家羽衣使，欲敎垂涕问何人。"]', '诗', 'shi', '', NULL, '山陽即席獻裴中丞 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11ccd723-89cc-4c2b-8e0a-007d30285fc1', '西峰即事獻沈大夫', '西峰即事獻沈大夫', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["松竹閑遊道路身，衣襟落盡往來塵。","山連謝宅餘霞在，水映琴溪舊浪春。","拂榻從容今有地，酬恩寂寞久無人。","安知不及屠沽者，曾對青萍淚滿巾。"]', '["松竹闲游道路身，衣襟落尽往来塵。","山連謝宅餘霞在，水映琴溪旧浪春。","拂榻從容今有地，酬恩寂寞久無人。","安知不及屠沽者，曾对青萍泪满巾。"]', '诗', 'shi', '', NULL, '西峰即事獻沈大夫 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('baddcc92-7920-4b9b-946e-f44542a75daa', '杜陵貽杜牧侍御', '杜陵貽杜牧侍御', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["紫陌塵多不可尋，南溪酒熟一披襟。","山高晝枕石牀隱，泉落夜窗煙樹深。","白首尋人嗟問計，青雲無路覓知音。","唯君懷抱安如水，他日門墻許醉吟。"]', '["紫陌塵多不可尋，南溪酒熟一披襟。","山高晝枕石牀隐，泉落夜窗煙樹深。","白首尋人嗟问計，青云無路覓知音。","唯君懷抱安如水，他日门墻許醉吟。"]', '诗', 'shi', '', NULL, '杜陵貽杜牧侍御 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98b09337-420d-435f-81f9-f73e367e45ba', '下第後上李中丞', '下第後上李中丞', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["落第逢人慟哭初，平生志業欲何如。","鬢毛灑盡一枝桂，淚血滴來千里書。","谷外風高摧羽翮，江邊春在憶樵漁。","唯應感激知恩地，不待功成死有餘。"]', '["落第逢人慟哭初，平生志業欲何如。","鬢毛灑尽一枝桂，泪血滴来千里书。","谷外风高摧羽翮，江邊春在憶樵漁。","唯應感激知恩地，不待功成死有餘。"]', '诗', 'shi', '', NULL, '下第後上李中丞 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92c0a903-8597-4d36-8934-32253df3efd1', '淛東贈李副使員外', '淛东贈李副使員外', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["妙盡戎機佐上台，少年清苦自霜臺。","馬嘶深竹閑宜貴，花拂朱衣美稱才。","早入半緣分務重，晚吟多是看山迴。","名高漸少翻飛伴，幾度煙霄獨去來。"]', '["妙尽戎機佐上台，少年清苦自霜台。","马嘶深竹闲宜貴，花拂朱衣美稱才。","早入半緣分務重，晚吟多是看山迴。","名高漸少翻飞伴，幾度煙霄独去来。"]', '诗', 'shi', '', NULL, '淛東贈李副使員外 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7bbcd9e-7b1e-462e-984d-b5b3d94b9bf2', '寄淮南幕中劉員外', '寄淮南幕中劉員外', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["郎官何遜最風流，愛月憐山不下樓。","三佐戎旃換朱紱，一辭蘭省見清秋。","桂生巖石本瀟灑，鶴到煙空更自由。","休向西齋久閑臥，滿朝傾蓋是依劉。"]', '["郎官何遜最风流，愛月怜山不下楼。","三佐戎旃換朱紱，一辞蘭省见清秋。","桂生巖石本瀟灑，鹤到煙空更自由。","休向西斋久闲臥，满朝傾蓋是依劉。"]', '诗', 'shi', '', NULL, '寄淮南幕中劉員外 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc0602d8-7606-4e6f-a993-739027884900', '薛廷範從事自宣城至因贈', '薛廷範從事自宣城至因贈', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["少年從事霍嫖姚，來自楓林度柳橋。","金管別筵樓灼灼，玉溪回首馬蕭蕭。","清風氣調真君輩，知己風流滿聖朝。","獨有故人愁欲死，晚簷疎雨動空瓢。"]', '["少年從事霍嫖姚，来自楓林度柳橋。","金管別筵楼灼灼，玉溪回首马蕭蕭。","清风氣調真君輩，知己风流满聖朝。","独有故人愁欲死，晚簷疎雨动空瓢。"]', '诗', 'shi', '', NULL, '薛廷範從事自宣城至因贈 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be03ae8e-223c-474d-9369-8bbe0c4692d8', '寄潯陽趙校書', '寄潯陽趙校书', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["簾下秋江夜影空，倚樓人在月明中。","不將行止問朝列，唯脫衣裳與釣翁。","幾處別巢悲去燕，十年回首送歸鴻。","那應更結廬山社，見說心閒勝遠公。"]', '["簾下秋江夜影空，倚楼人在月明中。","不將行止问朝列，唯脫衣裳與釣翁。","幾处別巢悲去燕，十年回首送归鴻。","那應更結廬山社，见说心閒勝远公。"]', '诗', 'shi', '', NULL, '寄潯陽趙校書 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34d3ded9-d202-430b-b9a6-fa46bb591496', '贈李從貴', '贈李從貴', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["白馬嘶風何處還，鞭梢拂地看南山。","珠簾捲盡不回首，春色欲闌休閉關。","花外鳥歸殘雨暮，竹邊人語夕陽閑。","知君舊隱嵩雲下，巖桂從今幾更攀。"]', '["白马嘶风何处還，鞭梢拂地看南山。","珠簾捲尽不回首，春色欲闌休閉关。","花外鸟归殘雨暮，竹邊人語夕陽闲。","知君旧隐嵩云下，巖桂從今幾更攀。"]', '诗', 'shi', '', NULL, '贈李從貴 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6331512-d4a6-4822-889b-7e3688aa4999', '贈陳正字', '贈陳正字', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["魯儒今日意何如，名挂春官選籍初。","野艇幾曾尋水去，故山從此與雲疎。","吟憐受露花陰足，行覺嘶風馬力餘。","聞說晚心心更靜，竹間依舊臥看書。"]', '["魯儒今日意何如，名挂春官選籍初。","野艇幾曾尋水去，故山從此與云疎。","吟怜受露花陰足，行覺嘶风马力餘。","闻说晚心心更静，竹间依旧臥看书。"]', '诗', 'shi', '', NULL, '贈陳正字 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('503a5f1a-5c76-4b43-ba8c-77fa90b9fe28', '洞庭寄所思', '洞庭寄所思', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["目斷蘭臺空望歸，錦衾香冷夢來稀。","書中自報刀頭約，天上三看破鏡飛。","孤浪謾疑紅臉笑，輕雲忽似舞羅衣。","遙知不語坐相憶，寂寞洞房寒燭微。"]', '["目斷蘭台空望归，錦衾香冷梦来稀。","书中自報刀头約，天上三看破镜飞。","孤浪謾疑紅臉笑，轻云忽似舞羅衣。","遙知不語坐相憶，寂寞洞房寒燭微。"]', '诗', 'shi', '', NULL, '洞庭寄所思 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b17508b-8cf2-4132-bac9-cc2ab268dfed', '代人贈杜牧侍御', '代人贈杜牧侍御', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["郎作東臺御史時，妾長西望歛雙眉。","一從詔下人皆羨，豈料恩衰不自知。","高闕如天縈曉夢，華筵似水隔秋期。","坐來情態猶無限，更向樓前舞柘枝。"]', '["郎作东台御史时，妾长西望歛雙眉。","一從詔下人皆羨，豈料恩衰不自知。","高闕如天縈晓梦，华筵似水隔秋期。","坐来情態猶無限，更向楼前舞柘枝。"]', '诗', 'shi', '', NULL, '代人贈杜牧侍御 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b42b5315-07b0-4120-bc49-7445752fc293', '旅館聞雁別友人', '旅館闻雁別友人', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["路遶秋塘首獨搔，背羣燕雁正呼號。","故關何處重相失，碧落有雲終自高。","旅宿去緘他日恨，單飛誰見此生勞。","行衣濕盡千山雪，腸斷金籠好羽毛。"]', '["路遶秋塘首独搔，背羣燕雁正呼號。","故关何处重相失，碧落有云終自高。","旅宿去緘他日恨，單飞誰见此生勞。","行衣濕尽千山雪，腸斷金籠好羽毛。"]', '诗', 'shi', '', NULL, '旅館聞雁別友人 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd05ebbd-fe4d-4a79-9758-bcacf6d63d3c', '泊鳧磯江館', '泊鳧磯江館', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["風雪晴來歲欲除，孤舟晚下意何如。","月當軒色湖平後，雁斷雲聲夜起初。","傍曉管絃何處靜，犯寒楊柳遶津疎。","三間茅屋東溪上，歸去生涯竹與書。"]', '["风雪晴来歲欲除，孤舟晚下意何如。","月當軒色湖平後，雁斷云声夜起初。","傍晓管絃何处静，犯寒楊柳遶津疎。","三间茅屋东溪上，归去生涯竹與书。"]', '诗', 'shi', '', NULL, '泊鳧磯江館 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('adfdf949-0b83-4855-9f27-00ac40fd4a5f', '春盡獨遊慈恩寺南池', '春尽独游慈恩寺南池', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["竹外池塘煙雨收，送春無伴亦遲留。","秦城馬上半年客，潘鬢水邊今日愁。","氣變晚雲紅映闕，風含高樹碧遮樓。","杏園花落遊人盡，獨爲圭峰一舉頭。"]', '["竹外池塘煙雨收，送春無伴亦遲留。","秦城马上半年客，潘鬢水邊今日愁。","氣变晚云紅映闕，风含高樹碧遮楼。","杏园花落游人尽，独爲圭峰一舉头。"]', '诗', 'shi', '', NULL, '春盡獨遊慈恩寺南池 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ab7aff2-45b5-443c-abc0-54cfcb1afded', '重遊楚國寺', '重游楚国寺', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["往事飄然去不迴。","空餘山色在樓臺，池塘風暖雁尋去。","松桂寺高人獨來，莊叟著書真達者。","賈生揮涕信悠哉，老僧心地閑於水。","猶被流年日日催。"]', '["往事飄然去不迴。","空餘山色在楼台，池塘风暖雁尋去。","松桂寺高人独来，莊叟著书真達者。","賈生揮涕信悠哉，老僧心地闲於水。","猶被流年日日催。"]', '诗', 'shi', '', NULL, '重遊楚國寺 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8ded480-d885-4be9-9556-4b420b07f40f', '三像寺酬元秘書', '三像寺酬元秘书', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["官總芸香閣署崇，可憐詩句落春風。","偶然侍坐水聲裏，還許醉吟松影中。","車馬照來紅樹合，煙霞詠盡翠微空。","不因高寺閑回首，誰識飄飄一塞翁。"]', '["官總芸香閣署崇，可怜诗句落春风。","偶然侍坐水声裏，還許醉吟松影中。","车马照来紅樹合，煙霞詠尽翠微空。","不因高寺闲回首，誰識飄飄一塞翁。"]', '诗', 'shi', '', NULL, '三像寺酬元秘書 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee543ced-fbcd-4ad9-8a2c-bbf1a7631982', '獻淮南李僕射', '獻淮南李僕射', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["早年曾謁富民侯，今日難甘失鵠羞。","新諾似山無力負，舊恩如水滿身流。","馬嘶紅葉蕭蕭晚，日照長江灩灩秋。","功德萬重知不惜，一言拋得百生愁。"]', '["早年曾謁富民侯，今日难甘失鵠羞。","新諾似山無力負，旧恩如水满身流。","马嘶紅葉蕭蕭晚，日照长江灩灩秋。","功德万重知不惜，一言拋得百生愁。"]', '诗', 'shi', '', NULL, '獻淮南李僕射 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('091b1861-398f-4266-ba9d-2512b320ce39', '江亭晚望', '江亭晚望', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["碧江涼冷雁來疎，閒望江雲思有餘。","秋館池亭荷葉歇，野人籬落豆花初。","無愁自得仙翁術，多病能忘太史書。","聞說故園香稻熟，片帆歸去就鱸魚。"]', '["碧江涼冷雁来疎，閒望江云思有餘。","秋館池亭荷葉歇，野人籬落豆花初。","無愁自得仙翁術，多病能忘太史书。","闻说故园香稻熟，片帆归去就鱸鱼。"]', '诗', 'shi', '', NULL, '江亭晚望 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9adced95-50e0-4add-b15d-9d4f64edb50a', '贈曹處士幽居', '贈曹处士幽居', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["勾漏先生冰玉然，曾將八石問羣仙。","中山暫醉一千日，南苑往來三百年。","碁局不收花滿洞，霓旌欲別浪翻天。","何須更學鴟夷子，頭白江湖一短船。"]', '["勾漏先生冰玉然，曾將八石问羣仙。","中山暫醉一千日，南苑往来三百年。","碁局不收花满洞，霓旌欲別浪翻天。","何須更学鴟夷子，头白江湖一短船。"]', '诗', 'shi', '', NULL, '贈曹處士幽居 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63079530-4219-4af8-b780-cf16bedbb310', '重陽日示舍弟', '重陽日示舍弟', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["多少鄉心入酒杯，野塘今日菊花開。","新霜何處雁初下，故國窮秋首正迴。","漸老向人空感激，一生驅馬傍塵埃。","侯門無路提攜爾，虛共扁舟萬里來。"]', '["多少乡心入酒杯，野塘今日菊花开。","新霜何处雁初下，故国窮秋首正迴。","漸老向人空感激，一生驱马傍塵埃。","侯门無路提携爾，虛共扁舟万里来。"]', '诗', 'shi', '', NULL, '重陽日示舍弟 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('adb27b34-0f01-48b7-a406-4b743715970a', '客至', '客至', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["得路逢津更俊才，可憐鞍馬照春來。","殘花幾日小齋閉，大笑一聲幽抱開。","袖拂碧溪寒繚繞，冠欹紅樹晚裴回。","相逢少別更堪恨，何必秋風江上臺。"]', '["得路逢津更俊才，可怜鞍马照春来。","殘花幾日小斋閉，大笑一声幽抱开。","袖拂碧溪寒繚繞，冠欹紅樹晚裴回。","相逢少別更堪恨，何必秋风江上台。"]', '诗', 'shi', '', NULL, '客至 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2451e7c1-68dd-44cd-a113-07120b3056d0', '歲暮江軒寄盧端公', '歲暮江軒寄盧端公', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["積水生高浪，長風自北時。","萬艘俱擁棹，上客獨吟詩。","路以重湖阻，心將小謝期。","渚雲愁正斷，江雁重驚悲。","笑憶遊星子，歌尋罷貴池。","夢來孤島在，醉醒百憂隨。","戍逈煙生晚，江寒鳥過遲。","問山樵者對，經雨釣船移。","敢歎今留滯，猶勝曩別離。","醉從陶令得，善必丈人知。","道蹇才何取，恩深劍不疑。","此身同岸柳，只待變寒枝。"]', '["積水生高浪，长风自北时。","万艘俱擁棹，上客独吟诗。","路以重湖阻，心將小謝期。","渚云愁正斷，江雁重驚悲。","笑憶游星子，歌尋罷貴池。","梦来孤島在，醉醒百憂隨。","戍逈煙生晚，江寒鸟過遲。","问山樵者对，經雨釣船移。","敢歎今留滯，猶勝曩別離。","醉從陶令得，善必丈人知。","道蹇才何取，恩深劍不疑。","此身同岸柳，只待变寒枝。"]', '诗', 'shi', '', NULL, '歲暮江軒寄盧端公 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b786f7c-5a8b-4302-8350-a1990224c4a7', '秋日吳中觀貢藕', '秋日吳中观貢藕', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["野艇幾西東，清泠映碧空。","褰衣來水上，捧玉出泥中。","葉亂田田綠，蓮餘片片紅。","激波纔入選，就日已生風。","御潔玲瓏膳，人懷拔擢功。","梯山謾多品，不與世流同。"]', '["野艇幾西东，清泠映碧空。","褰衣来水上，捧玉出泥中。","葉亂田田綠，蓮餘片片紅。","激波纔入選，就日已生风。","御潔玲瓏膳，人懷拔擢功。","梯山謾多品，不與世流同。"]', '诗', 'shi', '', NULL, '秋日吳中觀貢藕 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1dc19ddd-357b-4a1a-b5b2-260954fde2a4', '華清宮和杜舍人', '华清宮和杜舍人', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["五十年天子，離宮仰峻墻。","登封時正泰，御宇日何長。","上位先名實，中興事憲章。","起戎輕甲胄，餘地復河湟。","道帝玄元祖，儒封孔子王。","因緣百司署，藂會一人湯。","渭水波搖綠，秦郊草半黃。","馬馴金勒細，鷹健玉鈴鏘。","下箭朱弓滿，鳴鞭皓腕攘。","畋思獲呂望，諫祇避周昌。","兔跡貪前逐，梟心不早防。","幾添鸚鵡勸，先賜荔枝嘗。","月鎖千門靜，天吹一笛涼。","細音搖羽珮，輕步宛霓裳。","禍亂基潛結，升平意遽忘。","衣冠逃犬虜，鼙鼓動漁陽。","外戚心殊迫，中途事可量。","血埋妃子豔，刅斷祿兒腸。","近侍煙塵隔，前蹤輦路荒。","益知迷寵佞，遺恨喪賢良。","北闕尊明主，南宮遜上皇。","禁清餘鳳吹，池冷睡龍光。","祝壽山猶在，流年水共傷。","杜鵑魂厭蜀，蝴蝶夢悲莊。","雀卵遺雕栱，蟲絲罥畫粱。","紫苔侵壁潤，紅樹閉門芳。","守吏齊鴛瓦，耕民得翠璫。","登年齊酺樂，講武舊兵場。","暮草深巖翠，幽花墜徑香。","不堪垂白叟，行折御溝楊。"]', '["五十年天子，離宮仰峻墻。","登封时正泰，御宇日何长。","上位先名實，中兴事憲章。","起戎轻甲胄，餘地复河湟。","道帝玄元祖，儒封孔子王。","因緣百司署，藂會一人湯。","渭水波搖綠，秦郊草半黄。","马馴金勒細，鷹健玉鈴鏘。","下箭朱弓满，鳴鞭皓腕攘。","畋思獲呂望，諫祇避周昌。","兔跡貪前逐，梟心不早防。","幾添鸚鵡勸，先賜荔枝嘗。","月鎖千门静，天吹一笛涼。","細音搖羽珮，轻步宛霓裳。","禍亂基潛結，升平意遽忘。","衣冠逃犬虜，鼙鼓动漁陽。","外戚心殊迫，中途事可量。","血埋妃子豔，刅斷祿兒腸。","近侍煙塵隔，前蹤輦路荒。","益知迷寵佞，遺恨喪賢良。","北闕尊明主，南宮遜上皇。","禁清餘鳳吹，池冷睡龙光。","祝壽山猶在，流年水共傷。","杜鵑魂厭蜀，蝴蝶梦悲莊。","雀卵遺雕栱，蟲絲罥畫粱。","紫苔侵壁潤，紅樹閉门芳。","守吏齊鴛瓦，耕民得翠璫。","登年齊酺乐，講武旧兵場。","暮草深巖翠，幽花墜徑香。","不堪垂白叟，行折御溝楊。"]', '诗', 'shi', '', NULL, '華清宮和杜舍人 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a7304d2-9568-4718-b19e-b27223071ece', '下第', '下第', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["南溪抱瓮客，失意自懷羞。","晚路誰攜手，殘春自白頭。"]', '["南溪抱瓮客，失意自懷羞。","晚路誰携手，殘春自白头。"]', '诗', 'shi', '', NULL, '下第 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e37422f9-a0eb-4593-8b8b-cde70dd03dcd', '到家', '到家', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["童稚苦相問，歸來何太遲。","共誰爭歲月，贏得鬢邊絲。"]', '["童稚苦相问，归来何太遲。","共誰爭歲月，贏得鬢邊絲。"]', '诗', 'shi', '', NULL, '到家 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fcd93539-7f6d-4bda-ae35-3db7176cf8b5', '春釀', '春釀', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["春釀正風流，梨花莫問愁。","馬卿思一醉，不惜鷫鸘裘。"]', '["春釀正风流，梨花莫问愁。","马卿思一醉，不惜鷫鸘裘。"]', '诗', 'shi', '', NULL, '春釀 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1064aa9-4b66-4a1a-9f95-8675b1141fb7', '寒塘', '寒塘', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["曉髮梳臨水，寒塘坐見秋。","鄉心正無限，一雁度南樓。"]', '["晓髮梳臨水，寒塘坐见秋。","乡心正無限，一雁度南楼。"]', '诗', 'shi', '', NULL, '寒塘 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df71e847-2c43-4330-93b6-d9746cc9ce74', '寄前黃州竇使君', '寄前黄州竇使君', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["池上笙歌寂不聞，樓中愁殺碧虛雲。","玉壺凝盡重重淚，寄與風流舊使君。"]', '["池上笙歌寂不闻，楼中愁殺碧虛云。","玉壺凝尽重重泪，寄與风流旧使君。"]', '诗', 'shi', '', NULL, '寄前黃州竇使君 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d66a9cf4-daff-4508-b3df-92cbe4bb95dd', '八月二十九日宿懷', '八月二十九日宿懷', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["秋天晴日菊還香，獨坐書齋思已長。","無奈風光易流轉，強須傾酒一杯觴。"]', '["秋天晴日菊還香，独坐书斋思已长。","無奈风光易流轉，強須傾酒一杯觴。"]', '诗', 'shi', '', NULL, '八月二十九日宿懷 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b88c0412-546b-454c-a373-d88b4da95816', '泗上奉送相公', '泗上奉送相公', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["語堪銘座默含春，西漢公卿絕比倫。","今日抱轅留不得，欲揮雙涕學舒人。"]', '["語堪銘座默含春，西漢公卿絕比倫。","今日抱轅留不得，欲揮雙涕学舒人。"]', '诗', 'shi', '', NULL, '泗上奉送相公 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d16083f-c5eb-4774-9855-305a256961c6', '贈桐鄉丞', '贈桐乡丞', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["舟觸長松岸勢回，潺湲一夜繞亭臺。","若敎靖節先生見，不肯更吟歸去來。"]', '["舟觸长松岸勢回，潺湲一夜繞亭台。","若敎靖節先生见，不肯更吟归去来。"]', '诗', 'shi', '', NULL, '贈桐鄉丞 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c286345-cf35-410e-b8b4-e95a51466009', '哭李進士', '哭李進士', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["牽馬街中哭送君，靈車輾雪隔城聞。","唯有山僧與樵客，共舁孤櫬入幽墳。"]', '["牽马街中哭送君，靈车輾雪隔城闻。","唯有山僧與樵客，共舁孤櫬入幽墳。"]', '诗', 'shi', '', NULL, '哭李進士 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c472d1b-af32-48e0-9c86-37c69fcd4427', '重陽', '重陽', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["節逢重九海門外，家在五湖煙水東。","還向秋山覓詩句，伴僧吟對菊花風。"]', '["節逢重九海门外，家在五湖煙水东。","還向秋山覓诗句，伴僧吟对菊花风。"]', '诗', 'shi', '', NULL, '重陽 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d36b2c8d-b365-4bf8-8b85-5a8a518b31d4', '重陽日即事', '重陽日即事', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["病酒堅辭綺席春，菊花空伴水邊身。","由來舉止非閑雅，不是龍山落帽人。"]', '["病酒堅辞綺席春，菊花空伴水邊身。","由来舉止非闲雅，不是龙山落帽人。"]', '诗', 'shi', '', NULL, '重陽日即事 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55d37a59-81c0-4c02-adab-5ec0a29b67c4', '十無詩寄桂府楊中丞 一', '十無诗寄桂府楊中丞 一', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["琴酒曾將風月須，謝公名跡滿江湖。","不知貴擁旌旗後，猶暇憐詩愛酒無。"]', '["琴酒曾將风月須，謝公名跡满江湖。","不知貴擁旌旗後，猶暇怜诗愛酒無。"]', '诗', 'shi', '', NULL, '十無詩寄桂府楊中丞 一 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c0451bc-4866-4dd2-822c-106698e044ed', '十無詩寄桂府楊中丞 二', '十無诗寄桂府楊中丞 二', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["東省南宮興不孤，幾因詩酒謬招呼。","一從開署芙蓉幕，曾向風前記得無。"]', '["东省南宮兴不孤，幾因诗酒謬招呼。","一從开署芙蓉幕，曾向风前記得無。"]', '诗', 'shi', '', NULL, '十無詩寄桂府楊中丞 二 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fdfbac87-6a5c-42cb-8fab-98bae5fe4c07', '十無詩寄桂府楊中丞 三', '十無诗寄桂府楊中丞 三', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["遙聞桂水遶城隅，城上江山滿畫圖。","爲問訾家洲畔月，清秋擬許醉狂無。"]', '["遙闻桂水遶城隅，城上江山满畫圖。","爲问訾家洲畔月，清秋擬許醉狂無。"]', '诗', 'shi', '', NULL, '十無詩寄桂府楊中丞 三 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d36e1851-faa2-40ed-855c-0784cd99b7b4', '十無詩寄桂府楊中丞 四', '十無诗寄桂府楊中丞 四', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["日暮江邊一小儒，空憐未有白髭鬚。","馬融已貴諸生老，猶自容窺絳帳無。"]', '["日暮江邊一小儒，空怜未有白髭鬚。","马融已貴諸生老，猶自容窺絳帳無。"]', '诗', 'shi', '', NULL, '十無詩寄桂府楊中丞 四 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('998b0e98-59c2-4036-b0ae-4ea8424d7c6f', '十無詩寄桂府楊中丞 五', '十無诗寄桂府楊中丞 五', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["一種吟詩號孔徒，滄江有客獨疎愚。","初筵盡辟知名士，許到風前月下無。"]', '["一種吟诗號孔徒，滄江有客独疎愚。","初筵尽辟知名士，許到风前月下無。"]', '诗', 'shi', '', NULL, '十無詩寄桂府楊中丞 五 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ba15920-f15e-4d0f-a239-6ac06fd075eb', '十無詩寄桂府楊中丞 六', '十無诗寄桂府楊中丞 六', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["望斷南雲日已晡，便應憑夢過重湖。","不知自古登龍者，曾有因詩泥得無。"]', '["望斷南云日已晡，便應憑梦過重湖。","不知自古登龙者，曾有因诗泥得無。"]', '诗', 'shi', '', NULL, '十無詩寄桂府楊中丞 六 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('627c1d99-08a3-4b6c-b93a-8bc420b4fdb5', '十無詩寄桂府楊中丞 七', '十無诗寄桂府楊中丞 七', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["早游門館一樵夫，祗愛吟詩傍藥爐。","旌斾滿江身不見，思言記得穎川無。"]', '["早游门館一樵夫，祗愛吟诗傍藥爐。","旌斾满江身不见，思言記得穎川無。"]', '诗', 'shi', '', NULL, '十無詩寄桂府楊中丞 七 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ae3c442-0ede-47d5-b311-e230a0de0c5f', '十無詩寄桂府楊中丞 八', '十無诗寄桂府楊中丞 八', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["孔融襟抱稱名儒，愛物憐才與世殊。","今日賓堦忘姓字，當時省記薦雄無。"]', '["孔融襟抱稱名儒，愛物怜才與世殊。","今日賓堦忘姓字，當时省記薦雄無。"]', '诗', 'shi', '', NULL, '十無詩寄桂府楊中丞 八 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('acd0c10e-587a-4b45-91a3-34ae63bd9658', '十無詩寄桂府楊中丞 九', '十無诗寄桂府楊中丞 九', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["僻愛江山俯坐隅，人間不是便爲圖。","尊前爲問神仙伴，肯向三清慰薦無。"]', '["僻愛江山俯坐隅，人间不是便爲圖。","尊前爲问神仙伴，肯向三清慰薦無。"]', '诗', 'shi', '', NULL, '十無詩寄桂府楊中丞 九 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21c2e074-4b54-4742-83af-3a05c76be088', '十無詩寄桂府楊中丞 十', '十無诗寄桂府楊中丞 十', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["膺門不避額逢珠，絕境由來卷軸須。","早忝阿戎詩友契，趨庭曾薦禰生無。"]', '["膺门不避額逢珠，絕境由来卷軸須。","早忝阿戎诗友契，趨庭曾薦禰生無。"]', '诗', 'shi', '', NULL, '十無詩寄桂府楊中丞 十 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e48666fa-7a93-4116-bffb-d97fb415b83a', '寄山僧', '寄山僧', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["雲裏幽僧不置房，橡花藤葉蓋禪牀。","朝來逢著山中伴，聞說新移最上方。"]', '["云裏幽僧不置房，橡花藤葉蓋禪牀。","朝来逢著山中伴，闻说新移最上方。"]', '诗', 'shi', '', NULL, '寄山僧 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8aa719b-824f-4082-94f7-27d904718d68', '喜張濆及第', '喜張濆及第', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["九轉丹成最上仙，青天暖日踏雲軒。","春風賀喜無言語，排比花枝滿杏園。"]', '["九轉丹成最上仙，青天暖日踏云軒。","春风賀喜無言語，排比花枝满杏园。"]', '诗', 'shi', '', NULL, '喜張濆及第 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a24d8a04-59dd-4729-820d-2553759d1ccd', '贈張濆榜頭被駮落', '贈張濆榜头被駮落', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["莫向花前泣酒杯，謫仙依舊是仙才。","猶堪與世爲祥瑞，曾到蓬山頂上來。"]', '["莫向花前泣酒杯，謫仙依旧是仙才。","猶堪與世爲祥瑞，曾到蓬山頂上来。"]', '诗', 'shi', '', NULL, '贈張濆榜頭被駮落 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c83dafb-da9d-4c87-b3cd-cb4e835d2098', '悼亡二首 一', '悼亡二首 一', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["一燭從風到奈何，二年衾枕逐流波。","雖知不得公然淚，時泣闌干恨更多。"]', '["一燭從风到奈何，二年衾枕逐流波。","雖知不得公然泪，时泣闌干恨更多。"]', '诗', 'shi', '', NULL, '悼亡二首 一 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff4284b9-7b5e-4c32-b6ff-ddd71b422ee5', '悼亡二首 二', '悼亡二首 二', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["明月蕭蕭海上風，君歸泉路我飄蓬。","門前雖有如花貌，爭奈如花心不同。"]', '["明月蕭蕭海上风，君归泉路我飄蓬。","门前雖有如花貌，爭奈如花心不同。"]', '诗', 'shi', '', NULL, '悼亡二首 二 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c135ff0-a6f5-4ecb-a7f9-0d7c10710581', '宮烏栖', '宮烏栖', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["宮烏棲處玉樓深，微月生簷夜夜心。","香輦不回花自落，春來空佩辟寒金。"]', '["宮烏棲处玉楼深，微月生簷夜夜心。","香輦不回花自落，春来空佩辟寒金。"]', '诗', 'shi', '', NULL, '宮烏栖 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b5a070c-e194-4cef-b8e0-fa1a15f9b4d0', '長信宮', '长信宮', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["君恩已盡欲何歸，猶有殘香在舞衣。","自恨身輕不如燕，春來長遶御簾飛。"]', '["君恩已尽欲何归，猶有殘香在舞衣。","自恨身轻不如燕，春来长遶御簾飞。"]', '诗', 'shi', '', NULL, '長信宮 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4f72b44-1624-4663-bbe8-31242962ccd5', '廣陵城', '廣陵城', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["紅映高臺綠繞城，城邊春草傍墻生。","隋家不向此中盡，汴水應無東去聲。"]', '["紅映高台綠繞城，城邊春草傍墻生。","隋家不向此中尽，汴水應無东去声。"]', '诗', 'shi', '', NULL, '廣陵城 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65b32e14-32af-489d-b17a-482733889713', '冷日過驪山', '冷日過驪山', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["冷日微煙渭水愁，翠華宮樹不勝秋。","霓裳一曲千門鎖，白盡梨園弟子頭。"]', '["冷日微煙渭水愁，翠华宮樹不勝秋。","霓裳一曲千门鎖，白尽梨园弟子头。"]', '诗', 'shi', '', NULL, '冷日過驪山 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5db0b23a-1dc1-40db-b1f8-941de2fc2614', '下第後歸永樂里自題二首 一', '下第後归永乐里自題二首 一', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["無地無媒只一身，歸來空拂滿牀塵。","尊前盡日誰相對，唯有南山似故人。"]', '["無地無媒只一身，归来空拂满牀塵。","尊前尽日誰相对，唯有南山似故人。"]', '诗', 'shi', '', NULL, '下第後歸永樂里自題二首 一 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a806597-f7f6-4f1e-b033-57b757ce1bfd', '下第後歸永樂里自題二首 二', '下第後归永乐里自題二首 二', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["玄髮侵愁忽似翁，暖塵寒袖共東風。","公卿門戶不知處，立馬九衢春影中。"]', '["玄髮侵愁忽似翁，暖塵寒袖共东风。","公卿门戶不知处，立马九衢春影中。"]', '诗', 'shi', '', NULL, '下第後歸永樂里自題二首 二 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f1414de-02df-465b-840a-31570cb16e0e', '出試日獨遊曲江', '出試日独游曲江', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["江莎漸映花邊綠，樓日自開池上春。","雙鶴遶空來又去，不知臨水有愁人。"]', '["江莎漸映花邊綠，楼日自开池上春。","雙鹤遶空来又去，不知臨水有愁人。"]', '诗', 'shi', '', NULL, '出試日獨遊曲江 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dfe5d78a-8fc0-46ab-916c-6afacddc4ff0', '題曹娥廟', '題曹娥廟', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["青娥埋沒此江濱，江樹颼飀慘暮雲。","文字在碑碑已墮，波濤辜負色絲文。"]', '["青娥埋沒此江濱，江樹颼飀慘暮云。","文字在碑碑已墮，波濤辜負色絲文。"]', '诗', 'shi', '', NULL, '題曹娥廟 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f937e33-dc40-4ae8-a244-55cfbfa8f813', '題段氏中臺', '題段氏中台', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["看山臺下水無塵，碧篠前頭曲水春。","獨對一尊風雨夜，不知家有早朝人。"]', '["看山台下水無塵，碧篠前头曲水春。","独对一尊风雨夜，不知家有早朝人。"]', '诗', 'shi', '', NULL, '題段氏中臺 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06c9e6d5-f91d-497d-b40e-471f4c289d67', '華州座中獻盧給事', '华州座中獻盧給事', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["送迎皆到三峰下，滿面煙霜滿馬塵。","自是追攀認知己，青雲不假送迎人。"]', '["送迎皆到三峰下，满面煙霜满马塵。","自是追攀認知己，青云不假送迎人。"]', '诗', 'shi', '', NULL, '華州座中獻盧給事 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea49850f-bc2d-492a-96d5-92bee9655ba5', '商山道中', '商山道中', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["和如春色淨如秋，五月商山是勝遊。","當晝火雲生不得，一溪縈作萬重愁。"]', '["和如春色淨如秋，五月商山是勝游。","當晝火云生不得，一溪縈作万重愁。"]', '诗', 'shi', '', NULL, '商山道中 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('601e3e64-7d56-4e5b-9ba4-7ff6162e1f10', '贈歙州妓', '贈歙州妓', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["灩灩橫波思有餘，庾樓明月墮雲初。","揚州寒食春風寺，看遍花枝盡不如。"]', '["灩灩橫波思有餘，庾楼明月墮云初。","揚州寒食春风寺，看遍花枝尽不如。"]', '诗', 'shi', '', NULL, '贈歙州妓 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('026890c8-c99f-48ac-9cd9-77cd215dcb99', '贈王明府', '贈王明府', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["五柳逢秋影漸微，陶潛戀酒不知歸。","但存物外醉鄉在，誰向人間問是非。"]', '["五柳逢秋影漸微，陶潛戀酒不知归。","但存物外醉乡在，誰向人间问是非。"]', '诗', 'shi', '', NULL, '贈王明府 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24ad7bfb-5fb3-4175-a11c-8f7f881ef756', '呂校書雨中見訪', '呂校书雨中见訪', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["竹閣斜溪小檻明，惟君來賞見山情。","馬嘶風雨又歸去，獨聽子規千萬聲。"]', '["竹閣斜溪小檻明，惟君来賞见山情。","马嘶风雨又归去，独听子規千万声。"]', '诗', 'shi', '', NULL, '呂校書雨中見訪 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41a1eea7-0cd8-415f-9dec-91638ecaa5b4', '千秋嶺下', '千秋嶺下', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["知有巖前萬樹桃，未逢搖落思空勞。","年年盛發無人見，三十六溪春水高。"]', '["知有巖前万樹桃，未逢搖落思空勞。","年年盛發無人见，三十六溪春水高。"]', '诗', 'shi', '', NULL, '千秋嶺下 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f3cc689-1a60-43d5-a2a7-6f1227e0ca16', '歙州道中僕逃', '歙州道中僕逃', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["去跳風雨幾奔波，曾共辛勤奈若何。","莫遣窮歸不知處，秋山重疊戍旗多。"]', '["去跳风雨幾奔波，曾共辛勤奈若何。","莫遣窮归不知处，秋山重叠戍旗多。"]', '诗', 'shi', '', NULL, '歙州道中僕逃 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95512aed-4fe7-4e32-b698-d68e8fa28dc0', '重陽日寄韋舍人', '重陽日寄韋舍人', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["節過重陽菊委塵，江邊病起杖扶身。","不知此日龍山會，誰是風流落帽人。"]', '["節過重陽菊委塵，江邊病起杖扶身。","不知此日龙山會，誰是风流落帽人。"]', '诗', 'shi', '', NULL, '重陽日寄韋舍人 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b10ee1ae-744a-4af9-933a-05ca3cd49c06', '贈薛勛下第', '贈薛勛下第', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["一擲雖然未得盧，驚人不用繞牀呼。","牢之坐被青雲逼，祗問君能酷似無。"]', '["一擲雖然未得盧，驚人不用繞牀呼。","牢之坐被青云逼，祗问君能酷似無。"]', '诗', 'shi', '', NULL, '贈薛勛下第 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3e20bc3-b48a-4439-8c12-da9489021df5', '宛陵望月寄沈學士', '宛陵望月寄沈学士', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["一川如畫敬亭東，待詔閑遊處處同。","天竺山前鏡湖畔，何如今日庾樓中。"]', '["一川如畫敬亭东，待詔闲游处处同。","天竺山前镜湖畔，何如今日庾楼中。"]', '诗', 'shi', '', NULL, '宛陵望月寄沈學士 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40b14c6a-1ee6-4703-ba08-780fa7d023b9', '翡翠巖', '翡翠巖', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["芙蓉幕裏千場醉，翡翠巖前半日閑。","惆悵晉朝人不到，謝公拋力上東山。"]', '["芙蓉幕裏千場醉，翡翠巖前半日闲。","惆悵晉朝人不到，謝公拋力上东山。"]', '诗', 'shi', '', NULL, '翡翠巖 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('742eb740-805e-4e63-bd6c-a86eb5bb661b', '發新安後途中寄盧中丞二首 一', '發新安後途中寄盧中丞二首 一', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["樓上風流庾使君，笙歌曾醉此中聞。","目前已是陵陽路，回首叢山滿眼雲。"]', '["楼上风流庾使君，笙歌曾醉此中闻。","目前已是陵陽路，回首叢山满眼云。"]', '诗', 'shi', '', NULL, '發新安後途中寄盧中丞二首 一 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cec64e0f-fe44-4486-9a72-5f2918eca31d', '發新安後途中寄盧中丞二首 二', '發新安後途中寄盧中丞二首 二', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["晚樹蕭蕭促織愁，風簾似水滿牀秋。","千山不礙笙歌月，誰伴羊公上夜樓。"]', '["晚樹蕭蕭促织愁，风簾似水满牀秋。","千山不礙笙歌月，誰伴羊公上夜楼。"]', '诗', 'shi', '', NULL, '發新安後途中寄盧中丞二首 二 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0376ad8f-cf2c-4088-93e3-482c8395e20e', '留題興唐寺', '留題兴唐寺', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["滿水樓臺滿寺山，七年今日共躋攀。","月高對菊問行客，去折芳枝早晚還。"]', '["满水楼台满寺山，七年今日共躋攀。","月高对菊问行客，去折芳枝早晚還。"]', '诗', 'shi', '', NULL, '留題興唐寺 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc71446e-1119-464f-a37a-070cad1ab353', '廣陵道', '廣陵道', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["鬬雞臺邊花照塵，煬帝陵下水含春。","青雲回翅北歸雁，白首哭途何處人。"]', '["鬬雞台邊花照塵，煬帝陵下水含春。","青云回翅北归雁，白首哭途何处人。"]', '诗', 'shi', '', NULL, '廣陵道 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d99abf1-bc08-41b0-b347-2f0b340d6634', '茅山道中', '茅山道中', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["溪樹重重水亂流，馬嘶殘雨晚程秋。","門前便是仙山路，目送歸雲不得遊。"]', '["溪樹重重水亂流，马嘶殘雨晚程秋。","门前便是仙山路，目送归云不得游。"]', '诗', 'shi', '', NULL, '茅山道中 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8dbee52-3fc7-4f5f-9d65-8817156d0460', '江上與兄別', '江上與兄別', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["楚國湘江兩渺瀰，暖川晴雁背帆飛。","人間離別盡堪哭，何況不知何日歸。"]', '["楚国湘江兩渺瀰，暖川晴雁背帆飞。","人间離別尽堪哭，何況不知何日归。"]', '诗', 'shi', '', NULL, '江上與兄別 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62dbebd9-bd38-42e0-9747-1c8ac17f9eb9', '落第', '落第', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["九陌初晴處處春，不能回避看花塵。","由來得喪非吾事，本是釣魚船上人。"]', '["九陌初晴处处春，不能回避看花塵。","由来得喪非吾事，本是釣鱼船上人。"]', '诗', 'shi', '', NULL, '落第 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c78d4a35-d541-449a-a7e0-373adff95945', '宛陵館冬青樹', '宛陵館冬青樹', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["碧樹如煙覆晚波，清秋欲盡客重過。","故園亦有如煙樹，鴻雁不來風雨多。"]', '["碧樹如煙覆晚波，清秋欲尽客重過。","故园亦有如煙樹，鴻雁不来风雨多。"]', '诗', 'shi', '', NULL, '宛陵館冬青樹 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('459acb00-3fd5-4061-9c51-d7d3fcd73699', '贈五老韓尊師', '贈五老韓尊師', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["有客齋心事玉晨，對山鬚鬢綠無塵。","住山道士年如鶴，應識當時五老人。"]', '["有客斋心事玉晨，对山鬚鬢綠無塵。","住山道士年如鹤，應識當时五老人。"]', '诗', 'shi', '', NULL, '贈五老韓尊師 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e75a42e-ffa6-4c5f-8e4a-da82361c0464', '經汾陽舊宅', '經汾陽旧宅', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["門前不改舊山河，破虜曾輕馬伏波。","今日獨經歌舞地，古槐疎冷夕陽多。"]', '["门前不改旧山河，破虜曾轻马伏波。","今日独經歌舞地，古槐疎冷夕陽多。"]', '诗', 'shi', '', NULL, '經汾陽舊宅 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb2535d9-d47f-4975-bec5-4cc216403169', '寄盧中丞', '寄盧中丞', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["葉覆清溪灩灩紅，路橫秋色馬嘶風。","獨攜一榼郡齋酒，吟對青山憶謝公。"]', '["葉覆清溪灩灩紅，路橫秋色马嘶风。","独携一榼郡斋酒，吟对青山憶謝公。"]', '诗', 'shi', '', NULL, '寄盧中丞 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63b4fd17-3860-4666-8aa2-e0e8e4697298', '途中', '途中', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["故園回首雁初來，馬上千愁付一杯。","惟有新詩似相識，暮山吟處共徘徊。"]', '["故园回首雁初来，马上千愁付一杯。","惟有新诗似相識，暮山吟处共徘徊。"]', '诗', 'shi', '', NULL, '途中 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f26c917-df1f-494b-822b-673770a3d6fd', '寄裴瀾', '寄裴瀾', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["綺雲初墮亭亭月，錦席惟橫灩灩波。","宋玉逢秋正高臥，一篇吟盡奈情何。"]', '["綺云初墮亭亭月，錦席惟橫灩灩波。","宋玉逢秋正高臥，一篇吟尽奈情何。"]', '诗', 'shi', '', NULL, '寄裴瀾 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e74b3cb-5da6-497f-a984-51699e983940', '淮南丞相坐贈歌者虞姹', '淮南丞相坐贈歌者虞姹', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["綺筵無處避梁塵，虞姹清歌日日新。","來值渚亭花欲盡，一聲留得滿城春。"]', '["綺筵無处避梁塵，虞姹清歌日日新。","来值渚亭花欲尽，一声留得满城春。"]', '诗', 'shi', '', NULL, '淮南丞相坐贈歌者虞姹 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f739aca-2573-4d41-abb7-26dc65e714a5', '酬段侍御', '酬段侍御', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["蓮花上客思閑閑，數首新詩到篳關。","吟得楚天風雨霽，一條江水兩三山。"]', '["蓮花上客思闲闲，數首新诗到篳关。","吟得楚天风雨霽，一條江水兩三山。"]', '诗', 'shi', '', NULL, '酬段侍御 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d00b3f4-5a3d-4fcf-9e24-945d8cf55e87', '尋僧二首 一', '尋僧二首 一', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["臺殿參差日墮塵，塢西歸去一庵雲。","寒泉何處夜深落，聲隔半巖疎葉聞。"]', '["台殿參差日墮塵，塢西归去一庵云。","寒泉何处夜深落，声隔半巖疎葉闻。"]', '诗', 'shi', '', NULL, '尋僧二首 一 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a06afff-5756-4039-99c3-9c471a29613b', '尋僧二首 二', '尋僧二首 二', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["溪戶無人谷鳥飛，石橋橫木掛禪衣。","看雲日暮倚松立，野水亂鳴僧未歸。"]', '["溪戶無人谷鸟飞，石橋橫木掛禪衣。","看云日暮倚松立，野水亂鳴僧未归。"]', '诗', 'shi', '', NULL, '尋僧二首 二 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd34dbf1-3a5e-4dcc-bd1b-a5d2d7449f0a', '發栢梯寺', '發栢梯寺', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["一泓秋水千竿竹，靜得勞生半日身。","猶有向西無限地，別僧騎馬入紅塵。"]', '["一泓秋水千竿竹，静得勞生半日身。","猶有向西無限地，別僧騎马入紅塵。"]', '诗', 'shi', '', NULL, '發栢梯寺 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b7225ba-73e3-49ee-be99-6725380a2edb', '西江晚泊', '西江晚泊', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["茫茫靄靄失西東，柳浦桑村處處同。","戍鼓一聲帆影盡，水禽飛起夕陽中。"]', '["茫茫靄靄失西东，柳浦桑村处处同。","戍鼓一声帆影尽，水禽飞起夕陽中。"]', '诗', 'shi', '', NULL, '西江晚泊 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7f13f76-a9a2-4d24-9260-0a30faab44ff', '南池', '南池', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["照影池邊多少愁，往來重見此塘秋。","芙蓉苑外新經雨，紅葉相随何處流。"]', '["照影池邊多少愁，往来重见此塘秋。","芙蓉苑外新經雨，紅葉相随何处流。"]', '诗', 'shi', '', NULL, '南池 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('244610b1-65f6-41fb-a29a-490e3a75d3ce', '江樓舊感', '江楼旧感', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["獨上江樓思渺然，月光如水水如天。","同來望月人何處，風景依稀似去年。"]', '["独上江楼思渺然，月光如水水如天。","同来望月人何处，风景依稀似去年。"]', '诗', 'shi', '', NULL, '江樓舊感 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8baa85eb-1ea9-4cda-9112-795185abc4d2', '南園', '南园', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["雨過郊園綠尚微，落花惆悵滿塵衣。","芳尊有酒無人共，日暮看山還獨歸。"]', '["雨過郊园綠尚微，落花惆悵满塵衣。","芳尊有酒無人共，日暮看山還独归。"]', '诗', 'shi', '', NULL, '南園 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a65f7dff-61ac-4c5e-aa5e-30bf1946c60d', '南亭', '南亭', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["孤亭影在亂花中，悵望無人此醉同。","聽盡暮鐘猶獨坐，水邊襟袖起春風。"]', '["孤亭影在亂花中，悵望無人此醉同。","听尽暮鐘猶独坐，水邊襟袖起春风。"]', '诗', 'shi', '', NULL, '南亭 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('667ca439-8933-4f8c-bf92-49452c433865', '贈女仙', '贈女仙', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["水思雲情小鳳仙，月涵花態語如絃。","不因金骨三清客，誰識吳州有洞天。"]', '["水思云情小鳳仙，月涵花態語如絃。","不因金骨三清客，誰識吳州有洞天。"]', '诗', 'shi', '', NULL, '贈女仙 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e95b7df0-66de-40c6-ae6c-b119688a937e', '宣州送判官', '宣州送判官', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["來時健筆佐嫖姚，去折槐花度野橋。","誰見尊前此惆悵，一聲歌盡路迢迢。"]', '["来时健笔佐嫖姚，去折槐花度野橋。","誰见尊前此惆悵，一声歌尽路迢迢。"]', '诗', 'shi', '', NULL, '宣州送判官 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9258ebe8-568b-4306-b8dc-81590d5e02bd', '宿僧院', '宿僧院', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["月滿長空樹滿霜，度雲低拂近簷牀。","林中夜半一聲磬，臥見高僧入道場。"]', '["月满长空樹满霜，度云低拂近簷牀。","林中夜半一声磬，臥见高僧入道場。"]', '诗', 'shi', '', NULL, '宿僧院 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1362acd7-e6e8-4178-aac6-266cb346faf2', '尋僧', '尋僧', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["斜日橫窗起暗塵，水邊門戶閉閒春。","千竿竹裏花枝動，只道無人似有人。"]', '["斜日橫窗起暗塵，水邊门戶閉閒春。","千竿竹裏花枝动，只道無人似有人。"]', '诗', 'shi', '', NULL, '尋僧 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94f49863-1b47-4373-b109-3833d2626a41', '經王先生故居', '經王先生故居', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["晚波東去海茫茫，誰識蓬山不死鄉。","弄玉已歸蕭史去，碧樓紅樹倚斜陽。"]', '["晚波东去海茫茫，誰識蓬山不死乡。","弄玉已归蕭史去，碧楼紅樹倚斜陽。"]', '诗', 'shi', '', NULL, '經王先生故居 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('120086c5-198f-4ce9-9c10-15f2892f1f63', '送從翁中丞奉使黠戛斯六首 一', '送從翁中丞奉使黠戛斯六首 一', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["揚雄詞賦舉天聞，萬里油幢照塞雲。","僕射峰西幾千騎，一時迎著漢將軍。"]', '["揚雄词賦舉天闻，万里油幢照塞云。","僕射峰西幾千騎，一时迎著漢將軍。"]', '诗', 'shi', '', NULL, '送從翁中丞奉使黠戛斯六首 一 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5afc432e-1115-44f7-9dbb-2056ff04741b', '送從翁中丞奉使黠戛斯六首 二', '送從翁中丞奉使黠戛斯六首 二', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["旌旗杳杳雁蕭蕭，春盡窮沙雪未消。","料得堅昆受宣後，始知公主已歸朝。"]', '["旌旗杳杳雁蕭蕭，春尽窮沙雪未消。","料得堅昆受宣後，始知公主已归朝。"]', '诗', 'shi', '', NULL, '送從翁中丞奉使黠戛斯六首 二 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a873c91-9b2e-4e3b-a4bd-9f7947f1ea60', '送從翁中丞奉使黠戛斯六首 三', '送從翁中丞奉使黠戛斯六首 三', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["雖言窮北海雲中，屬國當時事不同。","九姓如今盡臣妾，歸期那肯待秋風。"]', '["雖言窮北海云中，屬国當时事不同。","九姓如今尽臣妾，归期那肯待秋风。"]', '诗', 'shi', '', NULL, '送從翁中丞奉使黠戛斯六首 三 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ce6e84a-ef90-4870-aad3-b11948c19d92', '送從翁中丞奉使黠戛斯六首 四', '送從翁中丞奉使黠戛斯六首 四', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["牢山望斷絕塵氛，灩灩河西拂地雲。","誰見魯儒持漢節，玉關降盡可汗軍。"]', '["牢山望斷絕塵氛，灩灩河西拂地云。","誰见魯儒持漢節，玉关降尽可汗軍。"]', '诗', 'shi', '', NULL, '送從翁中丞奉使黠戛斯六首 四 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d148287e-cb8f-4e95-92bc-9d7e9b81ac20', '送從翁中丞奉使黠戛斯六首 五', '送從翁中丞奉使黠戛斯六首 五', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["山川險易接胡塵，秦漢圖來或未真。","自此盡知邊塞事，河湟更欲託何人。"]', '["山川險易接胡塵，秦漢圖来或未真。","自此尽知邊塞事，河湟更欲託何人。"]', '诗', 'shi', '', NULL, '送從翁中丞奉使黠戛斯六首 五 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59cb7178-6cb1-4f8f-881c-e88d38d75aab', '送從翁中丞奉使黠戛斯六首 六', '送從翁中丞奉使黠戛斯六首 六', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["秦皇無策建長城，劉氏仍窮北路兵。","若遇單于舊牙帳，却應傷歎漢公卿。"]', '["秦皇無策建长城，劉氏仍窮北路兵。","若遇單于旧牙帳，却應傷歎漢公卿。"]', '诗', 'shi', '', NULL, '送從翁中丞奉使黠戛斯六首 六 趙嘏 shi');
